-- Wait until Roblox has finished loading before initializing the script.
if not game:IsLoaded() then
    game.Loaded:Wait()
end

do
    local Players    = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer
    while not LocalPlayer do RunService.Heartbeat:Wait() LocalPlayer = Players.LocalPlayer end

    -- Trx corridor noclip: continuously active while the local character is
    -- anywhere between the two X/Z coordinates, at ANY height.
    -- Collision is disabled on the local character only; world parts are untouched.
    do
        local _TrxNoclipMinX, _TrxNoclipMaxX = -387.848, -367.163
        local _TrxNoclipMinZ, _TrxNoclipMaxZ = 54.156, 85.621
        local _TrxNoclipMinY, _TrxNoclipMaxY = -7.10, 28.058
        local _TrxNoclipOriginal = setmetatable({}, { __mode = "k" })
        local _TrxNoclipCharacter
        local _TrxNoclipInside = false

        local function _TrxNoclipRestore()
            for part, original in pairs(_TrxNoclipOriginal) do
                if part and part.Parent then
                    pcall(function() part.CanCollide = original end)
                end
                _TrxNoclipOriginal[part] = nil
            end
        end

        local function _TrxNoclipSetCharacter(character, enabled)
            if not character then return end
            for _, inst in ipairs(character:GetDescendants()) do
                if inst:IsA("BasePart") then
                    if enabled then
                        if _TrxNoclipOriginal[inst] == nil then
                            _TrxNoclipOriginal[inst] = inst.CanCollide
                        end
                        if inst.CanCollide then inst.CanCollide = false end
                    elseif _TrxNoclipOriginal[inst] ~= nil then
                        pcall(function() inst.CanCollide = _TrxNoclipOriginal[inst] end)
                        _TrxNoclipOriginal[inst] = nil
                    end
                end
            end
        end

        RunService.Heartbeat:Connect(function()
            local character = LocalPlayer.Character
            if character ~= _TrxNoclipCharacter then
                _TrxNoclipRestore()
                _TrxNoclipCharacter = character
                _TrxNoclipInside = false
            end
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local pos = root and root.Position
            -- Use the axis-aligned 3D zone bounded by both supplied coordinates.
            local inside = pos ~= nil
                and pos.X >= _TrxNoclipMinX and pos.X <= _TrxNoclipMaxX
                and pos.Y >= _TrxNoclipMinY and pos.Y <= _TrxNoclipMaxY
                and pos.Z >= _TrxNoclipMinZ and pos.Z <= _TrxNoclipMaxZ
            _TrxNoclipInside = inside
            if inside then
                _TrxNoclipSetCharacter(character, true)
            else
                _TrxNoclipRestore()
            end
        end)

        -- Newly-added character parts (accessories/tools) also get noclip while
        -- the character is inside the corridor.
        LocalPlayer.CharacterAdded:Connect(function(character)
            _TrxNoclipRestore()
            _TrxNoclipCharacter = character
            _TrxNoclipInside = false
            character.DescendantAdded:Connect(function(inst)
                if _TrxNoclipInside and inst:IsA("BasePart") then
                    if _TrxNoclipOriginal[inst] == nil then
                        _TrxNoclipOriginal[inst] = inst.CanCollide
                    end
                    inst.CanCollide = false
                end
            end)
        end)
        if LocalPlayer.Character then
            LocalPlayer.Character.DescendantAdded:Connect(function(inst)
                if _TrxNoclipInside and inst:IsA("BasePart") then
                    if _TrxNoclipOriginal[inst] == nil then
                        _TrxNoclipOriginal[inst] = inst.CanCollide
                    end
                    inst.CanCollide = false
                end
            end)
        end
    end

    _G.Trx_ShowTPPath = (_G.Trx_ShowTPPath ~= false)

_G.TrxComputePetApproachRoute = function(part, fromPos) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
    local exactPos = part.Position
    local isSecondFloor = exactPos.Y > 10 and not f2UnderActive(exactPos.Y)
    local signPart = getClosestBaseSign(part)
    local targetBasePos
    local waypoints, usedPathfinding = {}, false
    local _sideChosen, _f2DropIn = false, false
    local _baseAvoidRoute
    local function _segAABB(ax, az, bx, bz, x0, z0, x1, z1) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
        local dx, dz = bx - ax, bz - az; local tmin, tmax = 0, 1
        if math.abs(dx) < 1e-6 then if ax < x0 or ax > x1 then return false end
        else local t1, t2 = (x0 - ax) / dx, (x1 - ax) / dx; if t1 > t2 then t1, t2 = t2, t1 end tmin = math.max(tmin, t1); tmax = math.min(tmax, t2); if tmin > tmax then return false end end
        if math.abs(dz) < 1e-6 then if az < z0 or az > z1 then return false end
        else local t1, t2 = (z0 - az) / dz, (z1 - az) / dz; if t1 > t2 then t1, t2 = t2, t1 end tmin = math.max(tmin, t1); tmax = math.min(tmax, t2); if tmin > tmax then return false end end
        return true
    end
    local _cR, _lE
    local function _charDims() LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if not _cR then
            local _c = LocalPlayer.Character
            local _h = _c and _c:FindFirstChild("HumanoidRootPart")
            local _hum = _c and _c:FindFirstChildOfClass("Humanoid")
            _cR = _h and math.clamp(math.max(_h.Size.X, _h.Size.Z) * 0.5 + 3, 4, 7) or 4
            _lE = _h and math.max(3, _h.Size.Y * 0.5 + ((_hum and _hum.HipHeight) or 2)) or 3
        end
        return _cR, _lE
    end
    local function _rpEx(extra, respect) LPH_ATTRIBUTES(ERROR_HANDLING(false))
        local ig = { LocalPlayer.Character }
        local cl = Workspace:FindFirstChild(tostring(LocalPlayer.UserId) .. "_Clone")
        if cl then ig[#ig + 1] = cl end
        if extra then for _, e in ipairs(extra) do ig[#ig + 1] = e end end
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = ig
        if respect then rp.RespectCanCollide = true end
        return rp, ig
    end
    local function tryPath(dst, srcY) LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if _baseAvoidRoute then local _r = _baseAvoidRoute(dst, srcY) if _r and #_r >= 1 then return _r, true end end
        return nil, false
    end
    local function cruiseYFor(_floorY) LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if not isSecondFloor then return -2.8 end
        local _cy2 = tonumber(_G.Trx_CruiseY_F2)
        if not _cy2 then
            _cy2 = 18
            if signPart and signPart:IsA("BasePart") then
                local _cfS, _sS = signPart.CFrame, signPart.Size
                local _eyS = math.abs(_cfS.RightVector.Y) * _sS.X + math.abs(_cfS.UpVector.Y) * _sS.Y + math.abs(_cfS.LookVector.Y) * _sS.Z
                local _, _legS = _charDims()
                _cy2 = signPart.Position.Y + _eyS * 0.5 + _legS + (tonumber(_G.Trx_F2SignClear) or 2)
            end end
        return _cy2
    end
    local plotsFolder = Workspace:FindFirstChild("Plots")
    local function plotOf(inst) LPH_ATTRIBUTES(ERROR_HANDLING(false))
        local node = inst
        while node and node.Parent do if node.Parent == plotsFolder then return node end node = node.Parent end
        return nil
    end
    local destPlot = signPart and plotOf(signPart) or nil
    local myPlot = nil
    if plotsFolder then
        local meName, meDisp = LocalPlayer.Name:lower(), LocalPlayer.DisplayName:lower()
        for _, plot in ipairs(plotsFolder:GetChildren()) do
            local sign = plot:FindFirstChild("PlotSign")
            local label = sign and sign:FindFirstChildWhichIsA("TextLabel", true)
            if label then
                local t = tostring(label.Text or ""):lower()
                if t:find(meName, 1, true) or t:find(meDisp, 1, true) then myPlot = plot; break end
            end end end
    local function collectObstacles() LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
        local _abs, _min, _max, _huge = math.abs, math.min, math.max, math.huge
        local _charR = tonumber(_G.Trx_CharRadius) or _charDims()
        local _obPad, _groundXZ = _G.Trx_ObstaclePad or 4, _G.Trx_GroundXZ or 90
        local _obMaxR, _plotMrg = _G.Trx_ObstacleMaxR or 150, _G.Trx_PlotSkipMargin or 4
        local _flatDef, _noclipSkipOn = (_G.Trx_WheelFlat ~= false), (_G.Trx_ObstacleSkipNoclip ~= false and _G.Trx_NoclipMachines ~= false)
        local _noclipKW = _G.Trx_NoclipKW or { "truck", "fuse", "craft", "incubator", "cupid", "soccerball" }
        local function _plotXZ(plot) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            if not plot then return nil end
            local _ok, _cf, _sz = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return plot:GetBoundingBox() end)
            if not _ok or not _cf then return nil end
            return _cf.Position.X, _cf.Position.Z, _max(_sz.X, _sz.Z) * 0.5
        end
        local _dpx, _dpz, _dpr = _plotXZ(destPlot)
        local _mpx, _mpz, _mpr = _plotXZ(myPlot)
        local function _nearPlot(cx, cz) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            return (_dpx and Vector2.new(cx - _dpx, cz - _dpz).Magnitude < (_dpr + _plotMrg))
                or (_mpx and Vector2.new(cx - _mpx, cz - _mpz).Magnitude < (_mpr + _plotMrg)) or false
        end
        local function _inb(q) LPH_ATTRIBUTES(ERROR_HANDLING(false))
return _abs(q.X)<50000 and _abs(q.Y)<50000 and _abs(q.Z)<50000 end
        local function _pbox(p) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
            local q = p.Position
            if not _inb(q) then return nil end
            local s, cf = p.Size, p.CFrame
            local rv, uv, lv = cf.RightVector, cf.UpVector, cf.LookVector
            local hx = (_abs(rv.X)*s.X + _abs(uv.X)*s.Y + _abs(lv.X)*s.Z) * 0.5
            local hy = (_abs(rv.Y)*s.X + _abs(uv.Y)*s.Y + _abs(lv.Y)*s.Z) * 0.5
            local hz = (_abs(rv.Z)*s.X + _abs(uv.Z)*s.Y + _abs(lv.Z)*s.Z) * 0.5
            if _max(hx, hz) * 2 > _groundXZ then return nil end
            return q, hx, hy, hz
        end
        local _exName = { Debris=true, Sounds=true, Interacts=true, rods=true, __PROJECTILES=true, RenderedMovingAnimals=true, ToolsAdds=true, Road=true }
        local _exSub = { "jew_","esp","tracer","xitp","xitemp","_clone","highlight","projectile","cybermap","vfx" }
        local function _excludedTop(inst) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
            if inst == myPlot or inst == destPlot or inst == plotsFolder or inst:IsA("Terrain") or inst:IsA("Camera") then return true end
            local nm = inst.Name
            if _exName[nm] or (nm == "Events" and _G.Trx_ObstacleSkipEvents == true) then return true end
            local n = nm:lower()
            for _, k in ipairs(_exSub) do if n:find(k, 1, true) then return true end end
            return inst:FindFirstChildOfClass("Humanoid") ~= nil
        end
        local _c0 = LocalPlayer.Character
        local _hrp0 = _c0 and _c0:FindFirstChild("HumanoidRootPart")
        local out, seen, _grpOk, _psvc = {}, {}, {}, game:GetService("PhysicsService")
        local _chGrp = _hrp0 and _hrp0.CollisionGroup or "Default"
        local function _collidesMe(g) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
            if _G.Trx_CollGroupAware == false or g == _chGrp then return true end
            local v = _grpOk[g]
            if v == nil then
                local ok, res = pcall(_psvc.CollisionGroupsAreCollidable, _psvc, _chGrp, g)
                v = (not ok) or (res and true or false); _grpOk[g] = v
            end
            return v
        end
        local function _emit(nm, mnx, mny, mnz, mxx, mxy, mxz, isHaz, isSpin, nameSpin, parts) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            local ex, ez = mxx - mnx, mxz - mnz
            local maxH = _max(ex, ez); local coreR = maxH * 0.5
            if maxH < 4 or coreR > _obMaxR then return end
            local cx, cz = (mnx + mxx) / 2, (mnz + mxz) / 2
            if _nearPlot(cx, cz) then return end
            local hx, hz = ex * 0.5, ez * 0.5
            local pad, wheel
            if isHaz then
                pad = (tonumber(_G.Trx_HazardPad) or 5) + _charR
            else
                local ar = _max(hx, hz) / _max(_min(hx, hz), 0.1)
                wheel = (isSpin or (nameSpin and (_G.Trx_SpinNameSquare == true or ar > (tonumber(_G.Trx_SpinArmRatio) or 1.6)))) and true or false
                pad = wheel and ((_G.Trx_WheelPad or 10) + _charR) or (_charR + _obPad)
            end
            out[#out + 1] = { center = Vector3.new(cx, (mny + mxy) / 2, cz), radius = coreR + pad, coreR = coreR, hx = hx, hz = hz, pad = pad, flat = _flatDef, name = nm, topY = mxy, wheel = wheel, haz = isHaz or nil, parts = parts }
        end
        local function _cluster(m) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
            if seen[m] then return end
            seen[m] = true
            local mn = m.Name
            local n = (mn or ""):lower()
            if _noclipSkipOn then for _, k in ipairs(_noclipKW) do if n:find(k, 1, true) then return end end end
            local nameSpin = n:find("wheel",1,true) or n:find("spin",1,true) or n:find("roulette",1,true) or n:find("rotat",1,true) or n:find("cyclone",1,true) or n:find("turbine",1,true)
            local _praw, _gY = {}, _huge
            for _, p in ipairs(m:IsA("BasePart") and { m } or m:GetDescendants()) do
                if p:IsA("BasePart") and p.CanCollide and _collidesMe(p.CollisionGroup) then
                    local q, hxp, hyp, hzp = _pbox(p)
                    if q then
                        local y0 = q.Y - hyp
                        if y0 < _gY then _gY = y0 end
                        _praw[#_praw + 1] = { x0 = q.X-hxp, x1 = q.X+hxp, z0 = q.Z-hzp, z1 = q.Z+hzp, y0 = y0, y1 = q.Y+hyp, ey = hyp * 2, spin = p.AssemblyAngularVelocity.Magnitude > 0.5 }
                    end end end
            local mnx, mny, mnz, mxx, mxy, mxz = _huge, _huge, _huge, -_huge, -_huge, -_huge
            local nC, isSpin, _pparts = 0, false, {}
            local _PCAP, _slabOff = tonumber(_G.Trx_ObstaclePartCap) or 40, (_G.Trx_SlabFilter == false)
            local _slabH, _slabTop = tonumber(_G.Trx_SlabMaxH) or 1.5, _gY + (tonumber(_G.Trx_SlabTopBand) or 1.2)
            local _slabGround = _gY <= (tonumber(_G.Trx_SlabGroundCeilY) or 2)
            for _, pp in ipairs(_praw) do
                if _slabOff or pp.spin or not (_slabGround and pp.ey <= _slabH and pp.y1 <= _slabTop) then
                    mnx=_min(mnx,pp.x0); mny=_min(mny,pp.y0); mnz=_min(mnz,pp.z0); mxx=_max(mxx,pp.x1); mxy=_max(mxy,pp.y1); mxz=_max(mxz,pp.z1)
                    if pp.spin then isSpin = true end
                    nC = nC + 1
                    if nC <= _PCAP then _pparts[nC] = pp end
                end end
            if nC == 0 then return end
            _emit(mn, mnx, mny, mnz, mxx, mxy, mxz, nil, isSpin, nameSpin, nC <= _PCAP and _pparts or nil)
        end
        local _containers = { Map = true, SummerMap = true, MapModels = true, Decorations = true }
        local function _scan(container, depth) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
            for _, child in ipairs(container:GetChildren()) do
                if not _excludedTop(child) then
                    local _m = child:IsA("Model")
                    if (child:IsA("Folder") or (_m and _containers[child.Name])) and depth < 4 then _scan(child, depth + 1)
                    elseif _m or child:IsA("BasePart") then _cluster(child) end
                end end end
        _scan(Workspace, 0)
        local _haz = _G.Trx_HazardNames or { "tradeplaza", "portal" }
        local _hazMemo = {}
        local function _isHaz(nm) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
            local v = _hazMemo[nm]
            if v ~= nil then return v end
            local l = nm:lower()
            v = false
            for _, k in ipairs(_haz) do if l:find(k, 1, true) then v = true; break end end
            _hazMemo[nm] = v
            return v
        end
        local _hseen, _ancC = {}, {}
        local function _ancHaz(node) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            if node == nil or node == Workspace then return false end
            local v = _ancC[node]
            if v == nil then v = _hseen[node] or _ancHaz(node.Parent); _ancC[node] = v end
            return v
        end
        for _, d in ipairs(Workspace:GetDescendants()) do
            if (d:IsA("Model") or d:IsA("BasePart")) and _isHaz(d.Name) and not _ancHaz(d.Parent) then
                _hseen[d] = true
                local mnx, mny, mnz, mxx, mxy, mxz = _huge, _huge, _huge, -_huge, -_huge, -_huge
                local nC = 0
                for _, p in ipairs(d:IsA("BasePart") and { d } or d:GetDescendants()) do
                    if p:IsA("BasePart") then
                        local q, hxp, hyp, hzp = _pbox(p)
                        if q then
                            mnx=_min(mnx,q.X-hxp); mny=_min(mny,q.Y-hyp); mnz=_min(mnz,q.Z-hzp); mxx=_max(mxx,q.X+hxp); mxy=_max(mxy,q.Y+hyp); mxz=_max(mxz,q.Z+hzp)
                            nC = nC + 1
                        end end end
                if nC > 0 then _emit(d.Name .. "*", mnx, mny, mnz, mxx, mxy, mxz, true) end
            end end
        if _G.Trx_ObstacleMemory ~= false then
            local _now, _mm = tick(), tonumber(_G.Trx_ObsMemMatch) or 10
            for _, o in ipairs(out) do
                if o.center then
                    local _hit
                    for _, m in ipairs(_obsMem) do
                        if m.name == o.name and _G.Trx_M2(m.center.X, m.center.Z, o.center.X, o.center.Z) <= _mm + _max(m.coreR or 0, o.coreR or 0) * 0.5 then _hit = m; break end
                    end
                    if _hit then
                        if (o.coreR or 0) > (_hit.coreR or 0) then
                            _hit.center, _hit.radius, _hit.coreR, _hit.hx, _hit.hz, _hit.pad, _hit.flat, _hit.wheel = o.center, o.radius, o.coreR, o.hx, o.hz, o.pad, o.flat, o.wheel
                        end
                        if (o.topY or -_huge) > (_hit.topY or -_huge) then _hit.topY = o.topY end
                        _hit.haz, _hit.seen = _hit.haz or o.haz, _now
                    else
                        _obsMem[#_obsMem + 1] = { name = o.name, center = o.center, radius = o.radius, coreR = o.coreR, hx = o.hx, hz = o.hz, pad = o.pad, topY = o.topY, haz = o.haz, wheel = o.wheel, flat = o.flat, seen = _now }
                    end end end
            local _meV, _seenMax = _hrp0 and _hrp0.Position, 0
            if _meV then
                for _, o in ipairs(out) do
                    local c = o.center
                    if c then local _sd = _G.Trx_M2(c.X, c.Z, _meV.X, _meV.Z); if _sd > _seenMax then _seenMax = _sd end end
                end end
            local _liveR = _max(tonumber(_G.Trx_ObsMemVerifyDist) or 60, _seenMax * (tonumber(_G.Trx_ObsMemLiveFrac) or 0.8))
            local _settling = (tick() - _obsDirtyAt) < (tonumber(_G.Trx_ObsSettleQuiet) or 1.0)
            local _memAdd = 0
            for _i = #_obsMem, 1, -1 do
                local m = _obsMem[_i]
                if m.seen ~= _now then
                    if not _settling and _meV and _G.Trx_M2(m.center.X, m.center.Z, _meV.X, _meV.Z) <= _liveR then
                        table.remove(_obsMem, _i)
                    elseif not _nearPlot(m.center.X, m.center.Z) then
                        out[#out + 1] = { center = m.center, radius = m.radius, coreR = m.coreR, hx = m.hx, hz = m.hz, pad = m.pad, topY = m.topY, name = (m.name or "?") .. "~", haz = m.haz, wheel = m.wheel, flat = m.flat, remembered = true }
                        _memAdd = _memAdd + 1
                    end end end
            while #_obsMem > (tonumber(_G.Trx_ObsMemMax) or 400) do table.remove(_obsMem, 1) end
            _G.Trx_ObsMemN, _G.Trx_ObsMemInjected = #_obsMem, _memAdd
        end
        return out
    end
    local _obsKey = destPlot or myPlot or "g"
    local _obsHit = _obsCache[_obsKey]
    local _cyberWheels
    if _obsHit and (tick() - _obsHit.at) < (_G.Trx_ObsCacheTTL or 12) and _obsDirtyAt <= _obsHit.at then
        _cyberWheels = _obsHit.wheels
    else
    _cyberWheels = (_G.Trx_ObstacleScan ~= false) and collectObstacles() or {}
    _obsCache[_obsKey] = { wheels = _cyberWheels, at = tick() }
    end
    if _G.Trx_LiftOverObstacles ~= false then
        local _cy = cruiseYFor(0)
        local _, _legExt = _charDims()
        local _wheelClr = math.max(tonumber(_G.Trx_LiftClearance)    or 7, _legExt + 1.5)
        local _flyClr   = math.max(tonumber(_G.Trx_FlyOverClearance) or 3, _legExt + 1.5)
        local _liftCap = tonumber(_G.Trx_LiftMaxUp) or (_cy < 5 and tonumber(_G.Trx_F1LiftMaxUp)) or 14
        local _noLift = _G.Trx_NoLiftNames or { "admin" }
        local _noLiftCeil = tonumber(_G.Trx_NoLiftMaxCruise)
        local function _forceDodge(w) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            if _noLiftCeil and _cy > _noLiftCeil then return false end
            local nm = (w.name or ""):lower()
            for _, k in ipairs(_noLift) do if nm:find(k, 1, true) then return true end end
            return false
        end
        local _lift = {}
        local _f1flat = (_G.Trx_F1FlatCruise ~= false) and _cy < 5
        for _, w in ipairs(_cyberWheels) do
            local _clr = w.wheel and _wheelClr or _flyClr
            if _f1flat then
                local _flyY = math.min(_cy, (fromPos and fromPos.Y) or _cy, (exactPos and exactPos.Y) or _cy)
                w.lifted = (w.topY and not w.haz and (w.topY <= _flyY - _legExt - 0.5)) or nil
            else
                local _canOver = (w.topY + _clr <= _cy + _liftCap)
                if _canOver and _G.Trx_ClimbAwareLift ~= false and not w.wheel and fromPos and w.center then
                    local _tgt = exactPos or targetBasePos
                    if _tgt then
                        local _span = 0.9 * math.max(Vector2.new(_tgt.X - fromPos.X, _tgt.Z - fromPos.Z).Magnitude, 1)
                        local _dO   = Vector2.new(w.center.X - fromPos.X, w.center.Z - fromPos.Z).Magnitude
                        local _flightY = fromPos.Y + (_cy - fromPos.Y) * math.clamp(_dO / _span, 0, 1)
                        if _flightY < w.topY + _clr then _canOver = false end
                    end end
                w.lifted = (w.topY and not w.haz and not _forceDodge(w) and (w.wheel or _canOver)) or nil
            end
            if w.lifted and not _f1flat then
                _lift[#_lift + 1] = { x = w.center.X, z = w.center.Z, r = w.radius, cr = w.coreR or w.radius, top = w.topY, liftY = w.topY + _clr }
            end end
        _G.Trx_FlightLiftObstacles = _lift
    else
        for _, w in ipairs(_cyberWheels) do w.lifted = nil end
        _G.Trx_FlightLiftObstacles = nil
    end
    if _G.Trx_ObstacleScan ~= false then
        local _obs = {}
        for _, w in ipairs(_cyberWheels) do
            if not w.lifted then _obs[#_obs + 1] = { x = w.center.X, z = w.center.Z, r = w.radius,
                                                     cr = (w.coreR or 0) + 2, strict = w.haz or nil } end
        end
        _G.Trx_FlightObstacles = _obs
    else
        _G.Trx_FlightObstacles = nil
    end
    local function _sweepHitsWheel(px, py, pz, dx, dy, dz) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
        local segLen2 = dx * dx + dy * dy + dz * dz
        if segLen2 <= 0.01 then return false end
        for _, w in ipairs(_cyberWheels) do
            local t = ((w.center.X - px) * dx + (w.center.Y - py) * dy + (w.center.Z - pz) * dz) / segLen2
            if t < 0 then t = 0 elseif t > 1 then t = 1 end
            local ox = px + dx * t - w.center.X
            local oy = w.flat and 0 or (py + dy * t - w.center.Y)
            local oz = pz + dz * t - w.center.Z
            if (ox * ox + oy * oy + oz * oz) < (w.radius * w.radius) then return true end
        end
        return false
    end
    local function wheelDetour(dst, cruiseY) LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if #_cyberWheels == 0 then return nil end
        local origin = Vector3.new(fromPos.X, cruiseY, fromPos.Z)
        local d = Vector3.new(dst.X - origin.X, 0, dst.Z - origin.Z)
        local segLen2 = d.X * d.X + d.Z * d.Z
        if segLen2 < 4 then return nil end
        local _best, _bestT
        for _, w in ipairs(_cyberWheels) do
            local t = ((w.center.X - origin.X) * d.X + (w.center.Z - origin.Z) * d.Z) / segLen2
            if t > 0.02 and t < 0.98 then
                local ox = (origin.X + d.X * t) - w.center.X
                local oz = (origin.Z + d.Z * t) - w.center.Z
                local distXZ = math.sqrt(ox * ox + oz * oz)
                if distXZ < w.radius and (not _bestT or t < _bestT) then _bestT = t; _best = { w = w, ox = ox, oz = oz, dist = distXZ } end
            end end
        if not _best then return nil end
        local w = _best.w
        local sx, sz
        if _best.dist > 0.1 then
            sx, sz = _best.ox / _best.dist, _best.oz / _best.dist
        else
            local pm = math.sqrt(d.X * d.X + d.Z * d.Z)
            sx, sz = -d.Z / pm, d.X / pm
        end
        local clr = w.radius + (_G.Trx_WheelDetourPad or 6)
        return Vector3.new(w.center.X + sx * clr, cruiseY, w.center.Z + sz * clr)
    end
    local function baseDetour(dst, cruiseY) LPH_ATTRIBUTES(ERROR_HANDLING(false))
        local _dsN = destPlot and destPlot.Name
        local m = _G.Trx_BaseLineMargin or 7
        local function _crossAny(ax,az,bx,bz) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            for _, f in ipairs(_G.Trx_BaseFootprints or {}) do
                if f.minX and f.plot ~= _dsN
                   and not (fromPos.X >= f.minX - m and fromPos.X <= f.maxX + m and fromPos.Z >= f.minZ - m and fromPos.Z <= f.maxZ + m) then
                    if _segAABB(ax,az,bx,bz, f.minX-m, f.minZ-m, f.maxX+m, f.maxZ+m) then return f end
                end end
            return nil
        end
        local ax,az,bx,bz = fromPos.X, fromPos.Z, dst.X, dst.Z
        local f = _crossAny(ax,az,bx,bz)
        if not f then return nil end
        local cx,cz = (f.minX+f.maxX)*0.5, (f.minZ+f.maxZ)*0.5
        local reach = math.max(f.maxX-f.minX, f.maxZ-f.minZ)*0.5 + (_G.Trx_BaseDetourClear or 16)
        local dx,dz = bx-ax, bz-az
        local Llen = math.sqrt(dx*dx + dz*dz); if Llen < 1 then return nil end
        local px,pz = -dz/Llen, dx/Llen
        for _, s in ipairs({ 1, -1 }) do
            local ox,oz = cx + px*s*reach, cz + pz*s*reach
            if not _crossAny(ax,az,ox,oz) and not _crossAny(ox,oz,bx,bz) then return Vector3.new(ox, cruiseY, oz) end
        end
        return nil
    end
    _baseAvoidRoute = function(dst, cruiseY) LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
