        local function _inM(f, x, z, m) LPH_ATTRIBUTES(ERROR_HANDLING(false))
return x >= f.minX - m and x <= f.maxX + m and z >= f.minZ - m and z <= f.maxZ + m end
        local boxes = {}
        for _, f in ipairs(_G.Trx_BaseFootprints or {}) do
            if f.minX and f.plot ~= _dsN then
                local p = (not _inM(f, fx, fz, M) and not _inM(f, dxp, dzp, M)) and M
                       or ((not _inM(f, fx, fz, 0) and not _inM(f, dxp, dzp, 0)) and 1 or nil)
                if p then boxes[#boxes + 1] = { x0 = f.minX - p, z0 = f.minZ - p, x1 = f.maxX + p, z1 = f.maxZ + p, wall = true } end
            end end
        local _op, _skipFrac = _G.Trx_ObjAvoidPad or 2, tonumber(_G.Trx_ObstacleSkipCoreFrac) or 0.85
        local _flyHalf, _propBoxPad = tonumber(_G.Trx_FlyOverMaxHalf) or 6, tonumber(_G.Trx_PropBoxPad) or M
        local function _pushBox(bcx, bcz, brx, brz, hard, pad) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            local b = { x0 = bcx - brx, z0 = bcz - brz, x1 = bcx + brx, z1 = bcz + brz, hard = hard, cx = bcx, cz = bcz, rhx = brx - pad, rhz = brz - pad, pad = pad }
            boxes[#boxes + 1] = b; return b
