        local function _segBox(ax, az, bx, bz, b) LPH_ATTRIBUTES(ERROR_HANDLING(false))
return _segAABB(ax, az, bx, bz, b.x0, b.z0, b.x1, b.z1) end
        local baseCell, uwalls = math.max(tonumber(_G.Trx_GridCell) or 6, 1), {}
        local _aisleX, _dstF, _dstOpenFace, _stF, _stFace, _stWin, _dstWin = tonumber(_G.Trx_AisleX) or -410
        do
            local T, MU = math.max(tonumber(_G.Trx_BaseWallT) or (1.5 * baseCell), 1.5 * baseCell), tonumber(_G.Trx_DstExteriorBerth) or M
            local function _openFace(f, px, pz) LPH_ATTRIBUTES(ERROR_HANDLING(false))
                local dn, dp, zn, zp = px - f.minX, f.maxX - px, pz - f.minZ, f.maxZ - pz
                local m = math.min(dn, dp, zn, zp)
