            end
            local function _addU(f, face, wc) LPH_ATTRIBUTES(ERROR_HANDLING(false))
                local TT = math.min(T, 0.4 * math.min(f.maxX - f.minX, f.maxZ - f.minZ))
                local eW, eE = (face == "-X") and 0 or MU, (face == "+X") and 0 or MU
                local eN, eP = (face == "-Z") and 0 or MU, (face == "+Z") and 0 or MU
                if face ~= "-X" then uwalls[#uwalls + 1] = { x0 = f.minX - MU, z0 = f.minZ - eN, x1 = f.minX + TT, z1 = f.maxZ + eP } end
                if face ~= "+X" then uwalls[#uwalls + 1] = { x0 = f.maxX - TT, z0 = f.minZ - eN, x1 = f.maxX + MU, z1 = f.maxZ + eP } end
                if face ~= "-Z" then uwalls[#uwalls + 1] = { x0 = f.minX - eW, z0 = f.minZ - MU, x1 = f.maxX + eE, z1 = f.minZ + TT } end
                if face ~= "+Z" then uwalls[#uwalls + 1] = { x0 = f.minX - eW, z0 = f.maxZ - TT, x1 = f.maxX + eE, z1 = f.maxZ + MU } end
                local dh = tonumber(_G.Trx_DoorHalf) or 19
                local _xf, _neg = (face == "-X" or face == "+X"), (face == "-X" or face == "-Z")
                local a0, a1, n0, n1 = _xf and f.minZ or f.minX, _xf and f.maxZ or f.maxX, _xf and f.minX or f.minZ, _xf and f.maxX or f.maxZ
                wc = math.max(a0 + dh, math.min(wc or (a0 + a1) * 0.5, a1 - dh))
