            local o = {} for k = 2, #pts do o[#o + 1] = pts[k] end return o
        end
        if _G.Trx_GridAStar ~= false then
            local SQ2, CLR = 1.4142135623730951, math.max(tonumber(_G.Trx_PathClearance) or 4, 0)
            local basePad = tonumber(_G.Trx_GridPad) or 24
