                local cell, pCLR = baseCell, math.max(tonumber(_G.Trx_PropPullClearance) or 2, 0)
                if _G.Trx_PropSmooth == false then pCLR = CLR end
                local function _softProp(b) LPH_ATTRIBUTES(ERROR_HANDLING(false))
return b.cx ~= nil and not b.wall and not b.hard and not b.haz and not b.wheel end
                local function _mkClear(hardC, softC, core) LPH_ATTRIBUTES(ERROR_HANDLING(false))
                    local L = {}
