                        else local _c = _sp and softC or hardC; L[#L + 1] = { x0 = b.x0 - _c, z0 = b.z0 - _c, x1 = b.x1 + _c, z1 = b.z1 + _c } end
                    end
                    for _, b in ipairs(uwalls) do local _c = b.jamb and 0 or hardC; L[#L + 1] = { x0 = b.x0 - _c, z0 = b.z0 - _c, x1 = b.x1 + _c, z1 = b.z1 + _c } end
                    return function(ax, az, bx, bz) LPH_ATTRIBUTES(ERROR_HANDLING(false))
                        for _, b in ipairs(L) do if _segAABB(ax, az, bx, bz, b.x0, b.z0, b.x1, b.z1) then return false end end
                        return true
                    end end
                local _clearUC = (CLR > 0) and _mkClear(CLR, pCLR, false) or _clearW
                local PGAP = CLR + 2
                local function _portalPt(f, face, ax, az, win) LPH_ATTRIBUTES(ERROR_HANDLING(false))
                    if win then
                        if win.axis == "z" then az = math.clamp(az, win.c - win.h + 1.5, win.c + win.h - 1.5) else ax = math.clamp(ax, win.c - win.h + 1.5, win.c + win.h - 1.5) end
                    end
                    local cm0 = math.max(tonumber(_G.Trx_PortalCornerMargin) or 7, 0)
                    local function _cmFor(span) LPH_ATTRIBUTES(ERROR_HANDLING(false))
if _G.Trx_PortalClampGuard == false then return cm0 end return math.min(cm0, math.max(0, span * 0.5 - 0.5)) end
                    if face == "+X" then local cm=_cmFor(f.maxZ-f.minZ); return f.maxX + PGAP, math.clamp(az, f.minZ + cm, f.maxZ - cm)
                    elseif face == "-X" then local cm=_cmFor(f.maxZ-f.minZ); return f.minX - PGAP, math.clamp(az, f.minZ + cm, f.maxZ - cm)
                    elseif face == "+Z" then local cm=_cmFor(f.maxX-f.minX); return math.clamp(ax, f.minX + cm, f.maxX - cm), f.maxZ + PGAP
                    else local cm=_cmFor(f.maxX-f.minX); return math.clamp(ax, f.minX + cm, f.maxX - cm), f.minZ - PGAP end
                end
                local function _nearF(f, x, z) LPH_ATTRIBUTES(ERROR_HANDLING(false))
                    local _m = tonumber(_G.Trx_DstNearMargin) or 12
                    local _dxg, _dzg = math.max(f.minX - x, x - f.maxX, 0), math.max(f.minZ - z, z - f.maxZ, 0)
                    return (_dxg * _dxg + _dzg * _dzg) <= _m * _m
                end
