                    local tin = ((win and win.t) or 9) + 1.5
                    if face == "-X" then return Vector3.new(f.minX + tin, cruiseY, tpc) elseif face == "+X" then return Vector3.new(f.maxX - tin, cruiseY, tpc)
                    elseif face == "-Z" then return Vector3.new(tpc, cruiseY, f.minZ + tin) else return Vector3.new(tpc, cruiseY, f.maxZ - tin) end
                end
