                    local _bothSame = _stF and _dstF and _stF == _dstF
                    if _stF and _stFace and not _bothSame and _inM(_stF, fx, fz, 0)
                       and not (_dstF and _inM(_stF, dxp, dzp, 0)) then
                        local px, pz = _portalPt(_stF, _stFace, fx, fz, _stWin)
                        if _inB(px, pz) then
                            rfx, rfz = px, pz; sPortal = Vector3.new(px, cruiseY, pz)
                            local _tc = (_stWin and _stWin.axis == "z") and fz or fx
                            if _offWin(_stWin, _tc) then sAlign = _alignPt(_stF, _stFace, _stWin, (_stWin.axis == "z") and pz or px) end
                        end end
                    local _needDstPortal = true
                    if _G.Trx_PortalOnlyIfWalled == true and not isSecondFloor and _dstF and _dstF.plot then
