                if abLen2 > 0.01 then
                    local along = math.clamp((p - a):Dot(ab) / abLen2, 0, 1)
                    local closest = a + ab * along
                    local correction = closest - p
                    local correctionMag = correction.Magnitude

                    if correctionMag > 0.05 then
                        local correctionDir = correction.Unit
                        local strength = math.clamp(correctionMag * pathPull, 0, spd * 1.25)
                        local corrected = Vector3.new(
                            dir.X * spd + correctionDir.X * strength,
                            0,
                            dir.Z * spd + correctionDir.Z * strength
                        )
                        if corrected.Magnitude > 0.05 then
                            dir = Vector3.new(corrected.X, 0, corrected.Z).Unit
                            spd = math.max(spd, math.min(corrected.Magnitude, spd * 1.35))
                        end
                    end
                end
            end

            -- Re-estimate remaining travel time every 0.1s. Once the
            -- estimated arrival is 0.20s away, cap horizontal velocity at 270.
            local now = os.clock()
            if now >= nextEtaUpdate then
                etaSeconds = remaining / math.max(spd, 1)
                nextEtaUpdate = now + 0.1
                slowForArrival = etaSeconds <= 0.20
            end
            if slowForArrival then
                spd = math.min(spd, 270)
            end

            local yVel = 0
            local yGap = target.Y - hrp.Position.Y
            local yGain = tonumber(_G.Trx_CruiseYGain) or 20
            local yCap = tonumber(_G.trxClimb) or tonumber(_G.Trx_CruiseRiseCap) or 400
            yVel = math.clamp(yGap * yGain, -yCap, yCap)

            if allowJump and yGap > 5 and idx < n then
                local hum = hrp.Parent:FindFirstChildOfClass("Humanoid")
                if hum then
                    local state = hum:GetState()
                    if state ~= Enum.HumanoidStateType.Jumping
                       and state ~= Enum.HumanoidStateType.Freefall then
                        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
                        pcall(function() hum.Jump = true end)
                    end
                end
            end

            if dir.Magnitude > 0.05 then
                local fx, fy, fz = dir.X * spd, yVel, dir.Z * spd
                hrp.AssemblyLinearVelocity = Vector3.new(fx, fy, fz)
            else
                hrp.AssemblyLinearVelocity = Vector3.new(0, yVel, 0)
            end
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)

        local total = 0
        local prev = hrp.Position
        for _, wp in ipairs(waypoints) do
            total += (prev - wp).Magnitude
            prev = wp
        end
        local timeout = math.max(4, total / math.max(runSpeed, 60) + 3)
        while not done and hrp.Parent and os.clock() - started < timeout do
            task.wait(0.05)
        end

        finish()
        if hrp and hrp.Parent then
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
    end
end
