local function TrxPlayConfiguredSound()
    local raw = tostring(_G.TrxSoundId or "rbxassetid://7573066466")
    local digits = raw:match("%d+")
    if not digits then return end
    local snd = Instance.new("Sound")
    snd.SoundId = "rbxassetid://" .. digits
    snd.Volume = 1
    snd.Looped = false
    snd.Parent = game:GetService("SoundService")
    snd:Play()
    game:GetService("Debris"):AddItem(snd, 10)
end
