local _trxStartupOk, _trxStartupErr = pcall(function()
local _syncJobId = tostring(game.JobId)
if _G.__TRX_SYNC_JOB ~= _syncJobId then
	_G.__TRX_SYNC_JOB = _syncJobId
	_G.TrxPreloadedSynchronizer = nil
	_G.TrxSynchronizerReady = nil
end

local function _looksLikeSynchronizer(t)
	if type(t) ~= "table" then return false end
	if typeof(t) ~= "table" then return false end
	local getCh = rawget(t, "GetTableFromChannel")
	local getAll = rawget(t, "GetAllChannels")
	return type(getCh) == "function" and type(getAll) == "function"
end

local function _tryRequireSynchronizer()
	local pre = _G.TrxPreloadedSynchronizer
	if _looksLikeSynchronizer(pre) then
		return pre
	end
	return nil
end

if _looksLikeSynchronizer(_G.TrxPreloadedSynchronizer) then
	_G.TrxSynchronizerReady = true
else
	task.spawn(function()
		task.wait(1.5)
		if type(getgc) ~= "function" then
			return
		end
		local function steal(deep)
			local found
			do
				local okGc, gcObjects = pcall(getgc, deep)
				if not okGc or type(gcObjects) ~= "table" then return false end
				for _, v in gcObjects do
					if type(v) == "table" and _looksLikeSynchronizer(v) then
						found = v
						break
					end
				end
			end
			if found then
				_G.TrxPreloadedSynchronizer = found
				_G.TrxSynchronizerReady = true
				return true
			end
			return false
		end
		if steal(false) then
			return
		end
		task.wait(1)
		steal(true)
	end)
end

_G.__trxBootAt = os.clock()
_G.__trxCoreReady = false
_G.__trxUiReady = false
_G.__trxRestReady = false
_G.__trxPhase = "boot"
_G.TrxUiRevealDelay = tonumber(_G.TrxUiRevealDelay) or 2.0
_G.TrxRestDelay = tonumber(_G.TrxRestDelay) or 3.5
local _trxAfterQueue = {}
local function _trxAfter(sec, fn)
	if type(fn) ~= "function" then return end
	local function go()
		local t0 = _G.__trxPhaseAt or os.clock()
		local wait = (tonumber(sec) or 0) - (os.clock() - t0)
		if wait <= 0 then
			task.spawn(fn)
		else
			task.delay(wait, fn)
		end
	end
	if _G.__trxPhaseAt then
		go()
	else
		_trxAfterQueue[#_trxAfterQueue + 1] = go
	end
end
local function _trxMarkCoreReady()
	if _G.__trxPhaseAt then return end
	_G.__trxPhaseAt = os.clock()
	_G.__trxCoreReady = true
	_G.__trxPhase = "core"
	for i = 1, #_trxAfterQueue do
		_trxAfterQueue[i]()
	end
	table.clear(_trxAfterQueue)
end
_G.TrxAfterBoot = _trxAfter
_G.TrxMarkCoreReady = _trxMarkCoreReady
_G.__TrxMarkCoreReady = function(reason)
	_trxMarkCoreReady()
end
_G.__TrxMarkUiReady = function(reason)
	if _G.__trxUiReady then return end
	_G.__trxUiReady = true
	_G.__trxPhase = "ui"
	local restDelay = tonumber(_G.TrxRestDelay) or 3.5
	task.delay(math.max(1.5, restDelay), function()
		if _G.__trxRestReady then return end
		if not _G.__trxUiReady then return end
		_G.__trxRestReady = true
		_G.__trxPhase = "rest"
	end)
end
_G.TrxAfterUiLoad = function(fn)
	if type(fn) ~= "function" then return end
	task.spawn(function()
		while not _G.__trxUiReady do
			task.wait(0.05)
		end
		fn()
	end)
end

