function _G.Trx_Step() end

local function TrxSetTPMode(mode, enabled)
    enabled = enabled == true
    if mode == "normal" then
        _G.TrxNormalTP = enabled
        if enabled then _G.TrxFlashTP = false end
    elseif mode == "flash" then
        _G.TrxFlashTP = enabled
        if enabled then _G.TrxNormalTP = false end
    end
end

_G.Trx_SeqT0 = _G.Trx_SeqT0 or os.clock()
_G.Trx_SeqLog = _G.Trx_SeqLog or {}
_G.Trx_SeqDone = _G.Trx_SeqDone or false
if type(_G.Trx_Step) ~= "function" then
	function _G.Trx_Step(nom, detail)
		local L = _G.Trx_SeqLog
		if #L > 120 then return end
		L[#L + 1] = {
			ms = math.floor((os.clock() - _G.Trx_SeqT0) * 1000),
			nom = nom,
			det = detail,
		}
	end
end

local function _syncBabySharkTpGlobals()
	if _G.TrxAutoTP ~= nil then
		_G.trxAutoTP = (_G.TrxAutoTP ~= false)
	end
	if _G.TrxVoidY ~= nil then _G.trxVoidY = _G.TrxVoidY end
