_G.TrxExecAJ = function()
	local code
	if type(readfile) == "function" and type(isfile) == "function" then
		local okExist, exists = pcall(isfile, "trx_custom_script.txt")
		if okExist and exists then
			local okRead, content = pcall(readfile, "trx_custom_script.txt")
			if okRead and type(content) == "string" then
				code = content
			end
		end
	end
	if not code or code == "" then
		warn("[TrxExecAJ] no script saved — set one in the EXE AJ panel first")
		return
	end
	local fn, err = loadstring(code)
	if not fn then
		warn("[TrxExecAJ] syntax error: " .. tostring(err))
		return
	end
	local ok, execErr = pcall(fn)
	if not ok then
		warn("[TrxExecAJ] runtime error: " .. tostring(execErr))
	end
end

