local BOOT_T0, BOOT_BURST, BOOT_GAP = os.clock(), 3.0, 0.10
local MAX_DEEP, DEEP_GAP = 3, 1.5

local RS_SYNC = game:GetService("ReplicatedStorage")

-- Restrict Synchronizer discovery to plots inside the two supplied CFrame corners.
-- The corners are treated as an axis-aligned 3D bounding box.
local TRX_SYNC_MIN = Vector3.new(-528.679, -8.900, -133.752)
local TRX_SYNC_MAX = Vector3.new(-292.932, 69.359, 254.126)
local _trxSyncBoundsCache, _trxSyncBoundsCacheAt = nil, 0
local function _trxSyncPlotNamesInBounds(forceRefresh)
    local now = os.clock()
    if not forceRefresh and _trxSyncBoundsCache and (now - _trxSyncBoundsCacheAt) < 1 then
        return _trxSyncBoundsCache
    end
    local allowed = {}
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return allowed end
    for _, plot in ipairs(plots:GetChildren()) do
        local pos
        pcall(function()
            if plot:IsA("Model") or plot:IsA("BasePart") then
                pos = plot:GetPivot().Position
            end
        end)
        if not pos then
            pcall(function()
                local part = plot:FindFirstChildWhichIsA("BasePart", true)
                if part then pos = part.Position end
            end)
        end
        if pos and pos.X >= TRX_SYNC_MIN.X and pos.X <= TRX_SYNC_MAX.X
            and pos.Y >= TRX_SYNC_MIN.Y and pos.Y <= TRX_SYNC_MAX.Y
            and pos.Z >= TRX_SYNC_MIN.Z and pos.Z <= TRX_SYNC_MAX.Z then
            allowed[plot.Name] = true
        end
    end
    _trxSyncBoundsCache = allowed
    _trxSyncBoundsCacheAt = now
    return allowed
end
local _mask_sc
local function _getMask()
    if _mask_sc and _mask_sc.Parent then return _mask_sc end
    local c = RS_SYNC:FindFirstChild("Controllers")
    _mask_sc = c and c:FindFirstChild("PlotController")
    return _mask_sc
end
local secure_call = _G.secure_call
if type(secure_call) ~= "function" then
    local LAYERS = 2
    local TEMPLATE do
        local lines = {
            "return function(__renv, __func, ...)",
            "\tsetfenv(0, __renv)",
            ("\tlocal function l%d(...) return __func(...) end"):format(LAYERS),
        }
        for c = LAYERS - 1, 1, -1 do
            lines[#lines + 1] = ("\tlocal function l%d(...) return l%d(...) end"):format(c, c + 1)
        end
        lines[#lines + 1] = "\treturn l1(...)"
        lines[#lines + 1] = "end"
        TEMPLATE = table.concat(lines, string.char(10))
    end
    local _gti = getthreadidentity or get_thread_identity or getidentity
    local _sti = setthreadidentity or set_thread_identity or setidentity
    local _sentinel
    secure_call = function(func, mask, ...)
        if type(func) ~= "function" or typeof(mask) ~= "Instance" then return nil end
        if not (_gti and _sti and getrenv and loadstring and setfenv) then return nil end
        local renv = getrenv()
        if not _sentinel then
            local ok, env = pcall(getsenv, mask)
            if not ok or type(env) ~= "table" then
                env = setmetatable({ script = mask, _G = {}, shared = {} }, { __index = renv, __newindex = renv })
            end
            local loader = loadstring(TEMPLATE, "=" .. mask:GetFullName())
            if not loader then return nil end
            setfenv(loader, env)
            _sentinel = loader()
        end
        local level = _gti()
        local changed = {}
        local okU, snap = pcall(debug.getupvalues, func)
        if okU and type(snap) == "table" then
            for i, v in pairs(snap) do
                if typeof(v) == "Instance" and v:IsA("LuaSourceContainer") then
                    if pcall(debug.setupvalue, func, i, mask) then changed[i] = v end
                end
            end
        end
        _sti(2)
        local co, args = coroutine.create(_sentinel), table.pack(renv, func, ...)
        local response, err
        while true do
            local r = table.pack(coroutine.resume(co, table.unpack(args, 1, args.n)))
            if not r[1] then err = r[2] break end
            if coroutine.status(co) == "dead" then response = table.pack(table.unpack(r, 2, r.n)) break end
            args = table.pack(coroutine.yield(table.unpack(r, 2, r.n)))
        end
        _sti(level)
        for i, orig in pairs(changed) do pcall(debug.setupvalue, func, i, orig) end
        if err or not response then return nil end
        return table.unpack(response, 1, response.n)
    end
    _G.secure_call = secure_call
end
local _syncMod_sc, _nextTry_sc = nil, 0
local function _getSyncMod()
    if _syncMod_sc then return _syncMod_sc end
    local p = RS_SYNC:FindFirstChild("Packages")
    local m = p and p:FindFirstChild("Synchronizer")
    if not m then return nil end
    local ok, mod = pcall(require, m)
    if ok and type(mod) == "table" then _syncMod_sc = mod end
    return _syncMod_sc
end
_G.__secureChans = function()
    if os.clock() < _nextTry_sc then return _xchan end
    local sync = _getSyncMod()
    if not sync then _nextTry_sc = os.clock() + 0.1; return _xchan end
    if type(sync.GetAllChannels) ~= "function" then _nextTry_sc = os.clock() + 0.1; return _xchan end
    local mask = _getMask()
    if not mask then _nextTry_sc = os.clock() + 0.1; return _xchan end
    local ok, reg = pcall(secure_call, sync.GetAllChannels, mask)
    if ok and type(reg) == "table" then
        _xchan = reg; _nextTry_sc = os.clock() + 1.5
        _G.TrxSyncDiag = "GetAllChannels (secure_call) - undetect/instant"
    else
        _nextTry_sc = os.clock() + 0.1
    end
    return _xchan
end

local function _retryGap()
    if (os.clock() - BOOT_T0) < BOOT_BURST then return BOOT_GAP end
    return RETRY_GAP
end

local function _channelCount(t)
    if type(t) ~= "table" then return 0 end
    local allowed = _trxSyncPlotNamesInBounds()
    local ok, hits = pcall(function()
        local h, n = 0, 0
        for k, v in next, t do
            if type(k) == "string" and allowed[k] then
                n = n + 1
                if type(v) == "table" and type(rawget(v, "CacheTable")) == "table" then
                    h = h + 1
                end
                if n >= 50 then break end
            end
        end
        return h
    end)
    return (ok and hits) or 0
end

local function _trxSyncFilterChannels(t)
    if type(t) ~= "table" then return nil end
    local allowed = _trxSyncPlotNamesInBounds()
    local filtered = {}
    for k, v in next, t do
        if type(k) == "string" and allowed[k]
            and type(v) == "table" and type(rawget(v, "CacheTable")) == "table" then
            filtered[k] = v
        end
    end
    return filtered
end

local function _module()
    if _mod then return _mod end
    local ok, m = pcall(function()
        return require(game:GetService("ReplicatedStorage").Packages.Synchronizer)
    end)
    if ok and type(m) == "table" then _mod = m; return _mod end
    local ok2, m2 = pcall(function()
        local pkgs = game:GetService("ReplicatedStorage"):FindFirstChild("Packages")
        local sync = pkgs and pkgs:FindFirstChild("Synchronizer")
        if not sync then return nil end
        return require(sync)
    end)
    if ok2 and type(m2) == "table" then _mod = m2 end
    return _mod
end

local function _probe(mod)
    local gu = (debug and debug.getupvalue) or getupvalue
    if type(gu) ~= "function" then return nil, 0, nil end
    local best, bestN, where = nil, 0, nil
    local function consider(t, tag)
        local n = _channelCount(t)
        if n > bestN then best, bestN, where = t, n, tag end
    end
    local cands = {
        { mod.Get, 10, 4, "Get/10/4" },
        { mod.GetAllChannels, 10, 1, "GetAll/10/1" },
        { mod.Wait, 10, 1, "Wait/10/1" },
    }
    for _, c in ipairs(cands) do
        if type(c[1]) == "function" then
            local o, u = pcall(gu, c[1], c[2])
            if o and type(u) == "table" then
                consider(rawget(u, c[3]), c[4])
                if bestN > 0 then return best, bestN, where end
            end
        end
    end
    for _, fn in ipairs({ mod.Get, mod.GetAllChannels, mod.Wait, mod.WaitAndCall, mod.GetTableFromChannel }) do
        if type(fn) == "function" then
            for i = 8, 12 do
                local o, u = pcall(gu, fn, i)
                if o and type(u) == "table" then
                    consider(u, "up" .. i)
                    for j = 1, 4 do consider(rawget(u, j), "up" .. i .. "/" .. j) end
                    if bestN > 0 then return best, bestN, where end
                end
            end
        end
    end
    local ok, up = pcall(gu, mod.Get, 9)
    if ok and type(up) == "table" then
        consider(rawget(up, 3), "Get/9/3")
        if bestN > 0 then return best, bestN, where end
        consider(up, "Get/9")
        if bestN > 0 then return best, bestN, where end
    end
    return best, bestN, where
end

local function _deepScan(mod)
    local gu = (debug and debug.getupvalue) or getupvalue
    if type(gu) ~= "function" then return nil, 0, nil end
    local best, bestN, where = nil, 0, nil
    local function consider(t, tag)
        local n = _channelCount(t)
        if n > bestN then best, bestN, where = t, n, tag end
    end
    for fname, fn in next, mod do
        if type(fn) == "function" then
            for i = 1, 24 do
                local o, u = pcall(gu, fn, i)
                if not o then break end
                if type(u) == "table" then
                    consider(u, tostring(fname) .. "/" .. i)
                    for j = 1, 4 do
                        consider(rawget(u, j), tostring(fname) .. "/" .. i .. "/" .. j)
                    end
                end
            end
        end
    end
    return best, bestN, where
end

local _gcFound, _gcFoundN, _gcState = nil, 0, "idle"

local function _gcScanOnce()
    if type(getgc) ~= "function" then return end
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return end
    local live = _trxSyncPlotNamesInBounds()
    local nLive = 0
    for _ in pairs(live) do nLive = nLive + 1 end
    if nLive == 0 then return end

    local best, bestN = nil, 0
    pcall(function()
        local gc = getgc(true)
        for i = 1, #gc do
            local t = gc[i]
            if type(t) == "table" then
                pcall(function()
                    local pk = 0
                    for k in next, t do
                        if type(k) == "string" and live[k] then pk = pk + 1; if pk >= 2 then break end end
                    end
                    if pk < 2 then return end
                    local hits, seen = 0, 0
                    for k, v in next, t do
                        seen = seen + 1
                        if type(k) == "string" and live[k]
                            and type(v) == "table" and type(rawget(v, "CacheTable")) == "table" then
                            hits = hits + 1
                        end
                        if seen >= 64 then break end
                    end
                    if hits > bestN and hits >= 2 then best, bestN = t, hits end
                end)
                if bestN >= nLive then break end
            end
        end
    end)
    if best and bestN > _gcFoundN then _gcFound, _gcFoundN = best, bestN end
end

local _gcLastScan = 0
local _gcRescans = 0
local function _gcChans()
    if _gcFound then
        local _pl = workspace:FindFirstChild("Plots")
        local _nLive = _pl and #_pl:GetChildren() or 0
        if _G.TrxSyncRescan == true and _gcFoundN < _nLive
            and _gcRescans < (tonumber(_G.TrxSyncMaxRescan) or 20)
            and (os.clock() - _gcLastScan) >= (tonumber(_G.TrxSyncRescanGap) or 3) then
            _gcLastScan = os.clock()
            _gcRescans = _gcRescans + 1
            _gcScanOnce()
        end
        return _gcFound, _gcFoundN, "getgc/plot-key+CacheTable"
    end
    if os.clock() - _gcLastScan < (tonumber(_G.TrxSyncScanGap) or 0.2) then return nil, 0, nil end
    _gcLastScan = os.clock()
    _gcScanOnce()
    if _gcFound then return _gcFound, _gcFoundN, "getgc/plot-key+CacheTable" end
    return nil, 0, nil
end

local function _apiChans(mod)
    if type(mod) ~= "table" then return nil, 0, nil end
    local fn = rawget(mod, "GetAllChannels")
    if type(fn) ~= "function" then return nil, 0, nil end
    local function _accept(reg, tag)
        if type(reg) ~= "table" then return nil, 0, nil end
        local n = _channelCount(reg)
        if n > 0 then return reg, n, tag end
        return nil, 0, nil
    end
    local mask = _getMask()
    if _G.TrxAllowSecureSyncCall and mask and type(secure_call) == "function" then
        for _, form in ipairs({ "self", "plain" }) do
            local ok, reg = pcall(function()
                if form == "self" then return secure_call(fn, mask, mod) end
                return secure_call(fn, mask)
            end)
            if ok then
                local r, n, t = _accept(reg, "GetAllChannels/secure_call(" .. form .. ")")
                if r then return r, n, t end
            end
        end
    end
    if _G.TrxAllowRawSyncCall then
        for _, form in ipairs({ "self", "plain" }) do
            local ok, reg = pcall(function()
                if form == "self" then return fn(mod) end
                return fn()
            end)
            if ok then
                local r, n, t = _accept(reg, "GetAllChannels/RAW(" .. form .. ")")
                if r then return r, n, t end
            end
        end
    end
    return nil, 0, nil
end

local _xchan2, _nextTry2, _attempts2 = nil, 0, 0
local _xchan2Until = 0
local function _chans()
    if _xchan2 then
        local now = os.clock()
        if now < _xchan2Until then return _xchan2 end
        if _channelCount(_xchan2) > 0 then _xchan2Until = now + 2 return _xchan2 end
    end
    if os.clock() < _nextTry2 then return _xchan2 end
    _attempts2 = _attempts2 + 1

    local best, n, where = _gcChans()

    if (not best or n == 0) and _attempts2 <= 400
        and (_G.TrxAllowUpvalueProbe or _G.TrxAllowSecureSyncCall or _G.TrxAllowRawSyncCall) then
        local mod = _getSyncMod()
        if mod then
            if _G.TrxAllowUpvalueProbe then
                best, n, where = _probe(mod)
                if (not best or n == 0) and os.clock() - _lastDeep > 1 then
                    _lastDeep = os.clock()
                    _deepScans = _deepScans + 1
                    best, n, where = _deepScan(mod)
                end
            end
            if not best or n == 0 then best, n, where = _apiChans(mod) end
        end
    end
    if best and n > 0 then
        _xchan2 = _trxSyncFilterChannels(best) or {}
        _G.TrxSyncDiag = string.format("bounded sync via %s - %d channels", tostring(where), n)
        return _xchan2
    end
    _nextTry2 = os.clock() + 0.1
    return _xchan2
end
_G.__secureChans = _chans

_G.TrxSyncAll=function()
    if _G.MynxxSyncAll then
        local r = _G.MynxxSyncAll()
        if r then return r end
    end
    return _chans()
end
_G.TrxSyncGet=function(idx)
    if _G.MynxxSyncGet then
        local r = _G.MynxxSyncGet(idx)
        if r then return r end
    end
    local t=_chans()
    if not t or idx==nil then return nil end
    local ok,cd=pcall(rawget,t,idx)
    if ok and type(cd)=="table" then return cd end
    local ok2,cd2=pcall(function() return t[idx] end)
    if ok2 and type(cd2)=="table" then return cd2 end
    return nil
end
_G.sProp=function(ch,key)
if type(ch)~="table" or key==nil then return nil end
local ct=rawget(ch,"CacheTable")
if type(ct)~="table" then
local okC,c2=pcall(function() return ch.CacheTable end)
if okC and type(c2)=="table" then ct=c2 end
end
if type(ct)~="table" then return nil end
local v=rawget(ct,key)
if v~=nil then return v end
local okV,v2=pcall(function() return ct[key] end)
if okV then return v2 end
return nil
end
_G._trxRawCT=function(plotName)
    if _G._mynxxRawCT then
        local r = _G._mynxxRawCT(plotName)
        if r then return r end
    end
    local c=_G.TrxSyncGet(plotName)
    if not c then return nil end
    return rawget(c,"CacheTable")
end
local _AD,_MD,_TD
local function _data()
if _AD then return true end
local ok=pcall(function()
local d=game:GetService("ReplicatedStorage"):WaitForChild("Datas")
_AD=require(d:WaitForChild("Animals"))
_MD=require(d:WaitForChild("Mutations"))
_TD=require(d:WaitForChild("Traits"))
end)
return ok and _AD~=nil
end
_G._trxGen=function(index,mutation,traits)
if not _data() then return 0 end
local info=_AD[index]
if not info or not info.Generation then return 0 end
local mult=1
if mutation and mutation~="None" and mutation~="" then
local m=_MD[mutation]
if m and m.Modifier then mult=mult+m.Modifier end
end
if type(traits)=="table" then
for _,tr in ipairs(traits)do
local t=_TD[tr]
if t and t.MultiplierModifier then mult=mult+t.MultiplierModifier end
end
end
return info.Generation*mult
end
_G._trxAnimShim=setmetatable({GetGeneration=function(_,index,mutation,traits)return _G._trxGen(index,mutation,traits)end},{
__index=function(_,k)
local ok,real=pcall(function()return require(game:GetService("ReplicatedStorage"):WaitForChild("Shared"):WaitForChild("Animals"))end)
if ok and type(real)=="table" then return rawget(real,k) end
return nil
end})
_G.Trx_GetPlotChannel=function(plotName)
    if _G.Mynxx_GetPlotChannel then
        local r = _G.Mynxx_GetPlotChannel(plotName)
        if r then return r end
    end
    return _G.TrxSyncGet(plotName)
end
_G.Trx_GetAllPlots=function()
    if _G.Mynxx_GetAllPlots then
        local r = _G.Mynxx_GetAllPlots()
        if r and next(r) then return r end
    end
    return _G.TrxSyncAll() or {}
end
_G.Trx_GetPlotAnimalList=function(plotName)
local ct=_G._trxRawCT(plotName)
local al=ct and ct.AnimalList
return type(al)=="table" and al or nil
end
-- Rose-compatible lazy Synchronizer facade backed by Trx channel discovery.
-- It preserves the existing scanner and the public Trx sync API used by TP/Camp.
do
    local proxy = _G.TrxSynchronizerProxy
    if type(proxy) ~= "table" then
        proxy = setmetatable({}, {
            __index = function(_, key)
                if key == "Get" then
                    return function(_, name) return _G.TrxSyncGet and _G.TrxSyncGet(name) or nil end
                elseif key == "GetAllChannels" then
                    return function() return (_G.TrxSyncAll and _G.TrxSyncAll()) or {} end
                elseif key == "GetTableFromChannel" then
                    return function(_, channel)
                        if type(channel) ~= "table" then return nil end
                        local ct = rawget(channel, "CacheTable")
                        if type(ct) == "table" then return ct end
                        local ok, value = pcall(function() return channel.CacheTable end)
                        return ok and type(value) == "table" and value or nil
                    end
                end
                local real = _G.TrxPreloadedSynchronizer or _G.TrxSyncMod
                local value = type(real) == "table" and real[key] or nil
                if type(value) == "function" then
                    return function(a, ...)
                        if rawequal(a, proxy) then return value(real, ...) end
                        return value(a, ...)
                    end
                end
                return value
            end,
            __newindex = function(_, key, value)
                local real = _G.TrxPreloadedSynchronizer or _G.TrxSyncMod
                if type(real) == "table" then pcall(function() real[key] = value end) end
            end,
        })
        _G.TrxSynchronizerProxy = proxy
    end
    _G.TrxSynchronizer = proxy
    _G.TrxGetSynchronizerProxy = function() return proxy end
end
end

_G.TrxSyncAll  = _G.TrxSyncAll
_G.TrxSyncGet  = _G.TrxSyncGet
_G.TrxRawCT    = _G._trxRawCT
_G.TrxGen      = _G._trxGen
_G.TrxAnimShim = _G._trxAnimShim
_G.stealthGet    = function(n) return _G.TrxSyncGet(n) end
_G.SyncInt       = {_cache={},_data=nil}

task.spawn(function() for _=1,150 do if _G.TrxSyncAll() then break end task.wait(0.04) end end)

_G.TrxGetSyncData = _G.TrxGetSyncData or function(plot)
    local plotName = type(plot) == "string" and plot or (plot and plot.Name)
    if not plotName then return nil end
    local Pkgs = game:GetService("ReplicatedStorage"):FindFirstChild("Packages")
    local Sync = Pkgs and Pkgs:FindFirstChild("Synchronizer")
    if not Sync then return nil end
    local okMod, mod = pcall(require, Sync)
    if not okMod or type(mod) ~= "table" then return nil end

    local okT, data = pcall(function() return _G.TrxRawCT(plotName) end)
    if okT and type(data) == "table" then return data end

    local okC, ch = pcall(function() return _G.TrxSyncGet(plotName) end)
    if okC and ch then
        local synth = { __channel = ch }
        pcall(function() local ct = rawget(ch, "CacheTable"); if type(ct)=="table" then synth.AnimalList = ct.AnimalList; synth.Owner = ct.Owner end end)
        return synth
    end
    return nil
end

_G.TrxGetRemote = function(name, kind)
	if type(_G.__secureGetRemote) == "function" then
		return _G.__secureGetRemote(kind or "RemoteEvent", name)
	end
	if type(_G.XenGetRemote) == "function" then
		return _G.XenGetRemote(name)
	end
	return nil
end
task.spawn(function()
	local plots
	local t0 = os.clock()
	repeat
		plots = workspace:FindFirstChild("Plots")
		if not plots then RunService.Heartbeat:Wait() end
	until plots or (os.clock() - t0) > 25
	if not plots then return end
	local done = {}
	local _lastPlotWarm = 0
	local conn
	conn = RunService.Heartbeat:Connect(function()
		local now = os.clock()
		if now - _lastPlotWarm < 1 then return end
		_lastPlotWarm = now
		_G.TrxSyncAll()
		local kids = plots:GetChildren()
		local pending = 0
		for _, plot in ipairs(kids) do
			if not done[plot.Name] then
				pending = pending + 1
				local ch
				if _G.TrxSyncGet then
					local ord
					ord = plot:GetAttribute("Order")
					if ord ~= nil then ch = _G.TrxSyncGet("Plot" .. tostring(ord)) end
					if not ch then ch = _G.TrxSyncGet(plot.Name) end
				end
								if ch then
					if ch.Get then
						pcall(function() ch:Get("AnimalList") end)
						pcall(function() ch:Get("Owner") end)
					end
					local al = _G.sProp and _G.sProp(ch, "AnimalList")
					if al ~= nil then done[plot.Name] = true end
				end
			end
		end
		if #kids > 0 and pending == 0 and conn then
			conn:Disconnect()
			conn = nil
		end
	end)
end)

do
    -- Keep synchronization refreshing once per second for the lifetime of this hub.
    -- Re-execution replaces the token, preventing duplicate pulse loops.
    local pulseToken = {}
    _G.__TRX_SYNC_PULSE_TOKEN = pulseToken

    task.spawn(function()
        while _G.__TRX_SYNC_PULSE_TOKEN == pulseToken do
            local startedAt = os.clock()

            if type(_G.Trx_MaskNow) == "function" then
                pcall(_G.Trx_MaskNow)
            end
            if type(_G.TrxSyncAll) == "function" then
                pcall(_G.TrxSyncAll)
            end

            task.wait(math.max(0.05, 1 - (os.clock() - startedAt)))
        end
    end)
end

do
	local _AD,_MD,_TD
	local _data = (function()
		if _AD and _MD and _TD then return true end
		do
			local d = RS:FindFirstChild("Datas")
			if not d then return false end
			local a = d:FindFirstChild("Animals")
			local m = d:FindFirstChild("Mutations")
			local t = d:FindFirstChild("Traits")
			if not a or not m or not t then return false end
			if not _AD then
				local ok, mod = pcall(require, a)
				if ok and type(mod) == "table" then _AD = mod end
			end
			if not _MD then
				local ok, mod = pcall(require, m)
				if ok and type(mod) == "table" then _MD = mod end
			end
			if not _TD then
				local ok, mod = pcall(require, t)
				if ok and type(mod) == "table" then _TD = mod end
			end
		end
		return _AD ~= nil and _MD ~= nil and _TD ~= nil
	end)
	_G.TrxGenReady = function()
		return _data() == true
	end
	_G.TrxGen = function(index, mutation, traits)
		if not _data() then return 0 end
		local info = _AD[index]
		if not info or not info.Generation then return 0 end
		local mult = 1
		if mutation and mutation ~= "None" and mutation ~= "" then
			local m = _MD[mutation]
			if m and m.Modifier then mult = mult + m.Modifier end
		end
		if type(traits) == "table" then
			for _, tr in ipairs(traits) do
				local t = _TD[tr]
				if t and t.MultiplierModifier then mult = mult + t.MultiplierModifier end
			end
		end
		return info.Generation * mult
	end
	_G.TrxAnimShim = setmetatable({
		GetGeneration = (function(_, index, mutation, traits)
			return _G.TrxGen(index, mutation, traits)
		end),
	}, {
		__index = (function(_, k)
			local sh = RS:FindFirstChild("Shared")
			local an = sh and sh:FindFirstChild("Animals")
			local ok, real = pcall(function()
				return an and require(an) or nil
			end)
			if ok and type(real) == "table" then return rawget(real, k) end
			return nil
		end),
	})
	task.spawn(function()
		local d = RS:WaitForChild("Datas", 90)
		if not d then return end
		d:WaitForChild("Animals", 30)
		d:WaitForChild("Mutations", 30)
		d:WaitForChild("Traits", 30)
		_data()
		_G.__trxDatasReady = true
		_G.__trxForceListRefresh = true
		if type(_G.TrxBustScanCache) == "function" then
			_G.TrxBustScanCache()
		end
		if type(_G.TrxForceResortList) == "function" then
			_G.TrxForceResortList()
		elseif type(_G.TrxRunSyncScanner) == "function" then
			_G.TrxRunSyncScanner(true)
		end
	end)
end

local AnimalsData, AnimalsShared, NumberUtils
local MutationsData, TraitsData, SyncMod

local function safeRequire(path)
	if not path then return nil end
	local ok, res = pcall(require, path)
	if ok then return res end
	return nil
end

local loadModules = (function()
	if AnimalsData then return true end
	local datas = RS:FindFirstChild("Datas")
	local animals = datas and datas:FindFirstChild("Animals")
	local utils = RS:FindFirstChild("Utils")
	local numberUtils = utils and utils:FindFirstChild("NumberUtils")
	if not animals or not numberUtils then return false end
	AnimalsData = safeRequire(animals)
	AnimalsShared = _G.TrxAnimShim
	NumberUtils = safeRequire(numberUtils)
	MutationsData = MutationsData or safeRequire(datas and datas:FindFirstChild("Mutations"))
	TraitsData = TraitsData or safeRequire(datas and datas:FindFirstChild("Traits"))
	return AnimalsData ~= nil
end)

do
	local pkg = RS:FindFirstChild("Packages")
	local datas = RS:FindFirstChild("Datas")
	local utils = RS:FindFirstChild("Utils")
	SyncMod = _G.TrxPreloadedSynchronizer or _tryRequireSynchronizer()
	AnimalsData = AnimalsData or safeRequire(datas and datas:FindFirstChild("Animals"))
	MutationsData = MutationsData or safeRequire(datas and datas:FindFirstChild("Mutations"))
	TraitsData = TraitsData or safeRequire(datas and datas:FindFirstChild("Traits"))
	NumberUtils = NumberUtils or safeRequire(utils and utils:FindFirstChild("NumberUtils"))
	AnimalsShared = _G.TrxAnimShim
	_G.TrxSyncMod = SyncMod
end

local function getSyncChannel(name)
	if type(name) ~= "string" or name == "" then return nil end
	if type(_G.MynxxSyncGet) == "function" then
		local ch = _G.MynxxSyncGet(name)
		if type(ch) == "table" then return ch end
	end
	if type(_G.TrxSyncGet) == "function" then
		local ch = _G.TrxSyncGet(name)
		if type(ch) == "table" then return ch end
		local pl = workspace:FindFirstChild("Plots")
		local plot = pl and pl:FindFirstChild(name)
		if plot then
			local ord
			pcall(function() ord = plot:GetAttribute("Order") end)
			if ord ~= nil then
				ch = _G.TrxSyncGet("Plot" .. tostring(ord))
				if type(ch) == "table" then return ch end
			end
		end
	end
	if type(_G.Trx_GetPlotChannel) == "function" then
		local t = _G.Trx_GetPlotChannel(name)
		if type(t) == "table" then return t end
	end
	return nil
end
_G.TrxGetSyncChannel = getSyncChannel

local GRAPPLE_ARG = 0.8

local CARPET_SPEED = 280
local INBASE_SPEED = 450
local SKY_CLONE_WAIT = 0.3
local CARPET_NAMES = { "Flying Carpet", "Waverider", "Santa's Sleigh", "Witch's Broom", "Cupid's Wings", "Skeleton Dragon" }
local TP_ITEM_NAMES = { "Flying Carpet", "Waverider", "Santa's Sleigh", "Witch's Broom", "Cupid's Wings", "Skeleton Dragon" }
local function findTool(name)
	local char = LP.Character
	local bp = LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack")
	local sg = LP:FindFirstChild("StarterGear")
	local t = (char and char:FindFirstChild(name)) or (bp and bp:FindFirstChild(name)) or (sg and sg:FindFirstChild(name))
	return t
end

local function _pokePlayerTools()
	local bp = LP:FindFirstChild("Backpack")
		if bp then
			bp:GetChildren()
			bp:FindFirstChild("Grapple Hook")
		end
		local sg = LP:FindFirstChild("StarterGear")
		if sg then sg:GetChildren() end
		local char = LP.Character
		if char then char:FindFirstChild("Grapple Hook") end

end

local function _streamPlayerNow()
	do
		local char = LP.Character
		local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
		if not hrp then return end
		pcall(function() LP:RequestStreamAroundAsync(hrp.Position) end)
	end
end

local function _waitGrapple(timeout)
	timeout = tonumber(timeout) or 5
	_pokePlayerTools()
	local found = findTool("Grapple Hook")
	if found then return found end

	local done, tool = false, nil
	local conns = {}
	local function take(inst)
		if done or not inst then return end
		if inst.Name == "Grapple Hook" and (inst:IsA("Tool") or inst:IsA("HopperBin")) then
			tool = inst
			done = true
		end
	end
	local function watch(folder)
		if not folder then return end
		local ex = folder:FindFirstChild("Grapple Hook")
		if ex then
			take(ex)
			return
		end
		conns[#conns + 1] = folder.ChildAdded:Connect(take)
		task.spawn(function()
			local w = folder:WaitForChild("Grapple Hook", timeout)
			take(w)
		end)
	end

	local bp = LP:FindFirstChild("Backpack")
	if bp then
		watch(bp)
	else
		task.spawn(function()
			local got = LP:WaitForChild("Backpack", timeout)
			watch(got)
		end)
	end
	watch(LP.Character)
	watch(LP:FindFirstChild("StarterGear"))
	conns[#conns + 1] = LP.CharacterAdded:Connect(function(c)
		watch(c)
		task.spawn(_streamPlayerNow)
	end)

	local t0 = os.clock()
	while not done and os.clock() - t0 < timeout do
		_pokePlayerTools()
		local f = findTool("Grapple Hook")
		if f then
			take(f)
			break
		end
		RunService.Heartbeat:Wait()
	end
	for _, c in ipairs(conns) do
		pcall(function() c:Disconnect() end)
	end
	return tool or findTool("Grapple Hook")
end

-- Auto Buy carpet lock: after the carpet is unequipped, wait before restoring it.
-- Explicit TP operations may bypass this delay when they need the carpet immediately.
local TRX_CARPET_REEQUIP_DELAY = 1.6
local _trxCarpetTPBusy = false -- shared with the dedicated Carpet TP worker below
local _trxCarpetReequipUntil = 0
local _trxCarpetReequipToken = 0
local _trxCarpetLastEquipAttempt = 0
local _trxCarpetToolWatcherCharacter
local equipCarpet
local function _trxIsCarpetTool(tool)
	if not tool or not tool:IsA("Tool") then return false end
	for _, name in ipairs(CARPET_NAMES) do
		if tool.Name == name then return true end
	end
	return false
end
local function _trxWatchCarpetToolSwitches(character)
	if not character or _trxCarpetToolWatcherCharacter == character then return end
	_trxCarpetToolWatcherCharacter = character
	local function scheduleCarpetReequip()
		_trxCarpetReequipToken = _trxCarpetReequipToken + 1
		local token = _trxCarpetReequipToken
		_trxCarpetReequipUntil = os.clock() + TRX_CARPET_REEQUIP_DELAY
		task.delay(TRX_CARPET_REEQUIP_DELAY, function()
			if token ~= _trxCarpetReequipToken then return end
			if _G.TrxFlashEquipLock == true or _trxCarpetTPBusy == true then return end
			if _G.TrxAutoBuy ~= true or LP.Character ~= character then return end
			-- Only restore it if the player still has another tool equipped.
			for _, equipped in ipairs(character:GetChildren()) do
				if equipped:IsA("Tool") and not _trxIsCarpetTool(equipped) then
					pcall(equipCarpet)
					break
				end
			end
		end)
	end
	character.ChildAdded:Connect(function(child)
		if not child:IsA("Tool") then return end
		if _trxIsCarpetTool(child) then
			_trxCarpetReequipToken = _trxCarpetReequipToken + 1
			_trxCarpetReequipUntil = 0
			return
		end
		-- Switching to another tool also starts the same 1.6 second delay.
		scheduleCarpetReequip()
	end)
	character.ChildRemoved:Connect(function(child)
		if child:IsA("Tool") and _trxIsCarpetTool(child) then
			-- Unequipping the carpet (including putting it back in the Backpack)
			-- starts a single cooldown instead of allowing the Heartbeat lock to spam it.
			scheduleCarpetReequip()
		end
	end)
end
equipCarpet = function()
	if _G.TrxFlashEquipLock == true then return nil end
	-- When Auto Buy is off, don't background-equip Carpet. Allow explicit TP/movement
	-- and Carpet Speed operations to equip it when they actually need it.
	local movementBusy = false
	if type(_G.TrxIsMovementBusy) == "function" then
		local ok, result = pcall(_G.TrxIsMovementBusy)
		movementBusy = ok and result == true
	end
	local tpBusy = movementBusy or _G.TrxIsTeleporting == true or _G.trxIsTeleporting == true
		or _G.__TrxManualTPActive == true or _G.__TrxCampTPActive == true
	if _G.TrxAutoBuy ~= true and not tpBusy and _trxCarpetTPBusy ~= true and _G.TrxCarpetSpeed ~= true then
		return nil
	end
	if os.clock() < _trxCarpetReequipUntil and _trxCarpetTPBusy ~= true and _G.TrxCarpetEquipImmediate ~= true then
		return nil
	end
	local char = LP.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not hum then return nil end
	for _, n in ipairs(CARPET_NAMES) do
		local t = findTool(n)
		if t and t:IsA("Tool") then
			if t.Parent ~= char then pcall(function() hum:EquipTool(t) end) end
			return n
		end
	end
	return nil
end
if LP.Character then _trxWatchCarpetToolSwitches(LP.Character) end
LP.CharacterAdded:Connect(function(character)
	_trxCarpetToolWatcherCharacter = nil
	_trxCarpetReequipUntil = 0
	_trxWatchCarpetToolSwitches(character)
end)
local function setCarpetTool(name)
	if type(name) ~= "string" or name == "" then return end
	_G.TrxCarpetTool = name
	for i = #CARPET_NAMES, 1, -1 do
		if CARPET_NAMES[i] == name then table.remove(CARPET_NAMES, i) end
	end
	table.insert(CARPET_NAMES, 1, name)
end
local function currentCarpetTool()
	if type(_G.TrxCarpetTool) == "string" and _G.TrxCarpetTool ~= "" then
		return _G.TrxCarpetTool
	end
	return CARPET_NAMES[1] or "Flying Carpet"
end
local function cycleCarpetTool()
	local cur = currentCarpetTool()
	local idx = 1
	for i, n in ipairs(TP_ITEM_NAMES) do
		if n == cur then idx = i; break end
	end
	local nxt = TP_ITEM_NAMES[(idx % #TP_ITEM_NAMES) + 1]
	setCarpetTool(nxt)
	return nxt
end
_G.TrxSetCarpetTool = setCarpetTool
_G.TrxCurrentCarpetTool = currentCarpetTool
_G.TrxCycleCarpetTool = cycleCarpetTool
if type(_G.TrxCarpetTool) == "string" and _G.TrxCarpetTool ~= "" then
	setCarpetTool(_G.TrxCarpetTool)
end

do
	local floatOn, floatConn = false, nil
	local floatPad = nil
	local function removeFloat()
		if floatConn then floatConn:Disconnect(); floatConn = nil end
		if floatPad then floatPad:Destroy(); floatPad = nil end
		local e = workspace:FindFirstChild("TrxFloatPad")
		if e then e:Destroy() end
	end
	local function createFloat()
		removeFloat()
		local c = LP.Character
		local hrp = c and c:FindFirstChild("HumanoidRootPart")
		if not hrp then return end
		local p = Instance.new("Part")
		p.Name = "TrxFloatPad"
		p.Size = Vector3.new(7, 1, 7)
		p.Anchored = true
		p.CanCollide = true
		p.CanTouch = false
		p.CanQuery = false
		p.Transparency = 1
		p.CastShadow = false
		p.CFrame = CFrame.new(hrp.Position - Vector3.new(0, 3.35, 0))
		p.Parent = workspace
		floatPad = p
		floatConn = RunService.Heartbeat:Connect(function()
			if not floatOn then return end
			local ch = LP.Character
			local h = ch and ch:FindFirstChild("HumanoidRootPart")
			if h and floatPad and floatPad.Parent then
				floatPad.CFrame = CFrame.new(h.Position - Vector3.new(0, 3.35, 0))
			end
		end)
	end
	local function setFloat(on)
		floatOn = on and true or false
		_G.TrxFloat = floatOn
		if floatOn then createFloat() else removeFloat() end
		if type(_G.TrxPaintFloat) == "function" then pcall(_G.TrxPaintFloat) end
	end
	_G.TrxSetFloat = setFloat
	_G.toggleFloat = function() setFloat(not floatOn) end
	do
		LP.CharacterAdded:Connect(function()
			task.wait(0.5)
			if floatOn then removeFloat(); createFloat() end
		end)
	end

	local infOn, infConn, infJumpConn, lastJump = false, nil, nil, 0
	local function setInfJump(on)
		infOn = on and true or false
		_G.TrxInfJump = infOn
		_G.InfiniteJumpEnabled = infOn
		if infConn then infConn:Disconnect(); infConn = nil end
		if infJumpConn then infJumpConn:Disconnect(); infJumpConn = nil end
		if type(_G.TrxPaintInfJump) == "function" then _G.TrxPaintInfJump() end
		if not infOn then return end
		local function doInfJump()
			local now = tick()
			if now - lastJump < 0.1 then return end
			local c = LP.Character
			if not c then return end
			local hrp = c:FindFirstChild("HumanoidRootPart")
			local hum = c:FindFirstChildOfClass("Humanoid")
			if not hrp or not hum or hum.Health <= 0 then return end
			lastJump = now
			hrp.AssemblyLinearVelocity =
				Vector3.new(hrp.AssemblyLinearVelocity.X, 55, hrp.AssemblyLinearVelocity.Z)
		end
		infConn = RunService.Heartbeat:Connect(function()
			if not infOn then return end
			if not UIS:IsKeyDown(Enum.KeyCode.Space) then return end
			doInfJump()
		end)
		infJumpConn = UIS.JumpRequest:Connect(function()
			if not infOn then return end
			doInfJump()
		end)
	end
	_G.TrxSetInfJump = setInfJump
	_G.setInfiniteJump = setInfJump
	_G.toggleInfJump = function() setInfJump(not infOn) end
	if _G.TrxInfJump == true then
		task.defer(function() setInfJump(true) end)
	end

	local carpetOn, carpetConn = false, nil
	local function setCarpetSpeed(on)
		carpetOn = on and true or false
		_G.TrxCarpetSpeed = carpetOn
		if carpetConn then carpetConn:Disconnect(); carpetConn = nil end
		if type(_G.TrxPaintCarpetSpeed) == "function" then _G.TrxPaintCarpetSpeed() end
		if not carpetOn then return end
		carpetConn = RunService.Heartbeat:Connect(function()
			local c = LP.Character
			if not c then return end
			local hum = c:FindFirstChildOfClass("Humanoid")
			local hrp = c:FindFirstChild("HumanoidRootPart")
			if not hum or not hrp then return end
			if LP:GetAttribute("Stealing") then
				setCarpetSpeed(false)
				return
			end
			local name = equipCarpet()
			if name and c:FindFirstChild(name) then
				local md = hum.MoveDirection
				local spd = 140
				if md.Magnitude > 0 then
					hrp.AssemblyLinearVelocity = Vector3.new(md.X * spd, hrp.AssemblyLinearVelocity.Y, md.Z * spd)
				else
					hrp.AssemblyLinearVelocity = Vector3.new(0, hrp.AssemblyLinearVelocity.Y, 0)
				end
			end
		end)
	end
	_G.TrxSetCarpetSpeed = setCarpetSpeed
	_G.toggleCarpetSpeed = function() setCarpetSpeed(not carpetOn) end
	if _G.TrxCarpetSpeed == true then
		task.defer(function() setCarpetSpeed(true) end)
	end

	LP:GetAttributeChangedSignal("Stealing"):Connect(function()
		if LP:GetAttribute("Stealing") then
			if floatOn then setFloat(false) end
			if carpetOn then setCarpetSpeed(false) end
		end
	end)
end

do
	local autoBuyActive = false
	local autoBuyRing = nil
	local conveyorAnimals = {}
	local DETECT_RADIUS = 17
	local HOVER_HEIGHT = 3
	local RING_COLOR = Color3.fromRGB(186, 150, 255)
	local carpetLockConn = nil
	local purchaseRemote = nil
	local conveyorWatchConn = nil
	local lockedEntry = nil

	local function buyRange()
		return tonumber(_G.TrxAutoBuyRange) or DETECT_RADIUS
	end

	local function snapToBuyTarget(hrp, part)
		if not hrp or not part or not part.Parent then return end
		local pos = part.Position + Vector3.new(0, HOVER_HEIGHT, 0)
		hrp.AssemblyLinearVelocity = Vector3.zero
		hrp.AssemblyAngularVelocity = Vector3.zero
		hrp.CFrame = CFrame.new(pos) * (hrp.CFrame - hrp.CFrame.Position)
	end

	local function createAutoBuyRing()
		local existing = workspace:FindFirstChild("TrxAutoBuyRing")
		if existing then existing:Destroy() end
		local r = Instance.new("Part")
		r.Name = "TrxAutoBuyRing"
		r.Shape = Enum.PartType.Cylinder
		r.Anchored = true
		r.CanCollide = false
		r.CanTouch = false
		r.CanQuery = false
		r.CastShadow = false
		r.Material = Enum.Material.Neon
		r.Transparency = 0.5
		r.Color = RING_COLOR
		local range = buyRange()
		r.Size = Vector3.new(0.5, range * 2, range * 2)
		r.Parent = workspace
		autoBuyRing = r
	end
	local function destroyAutoBuyRing()
		if autoBuyRing then autoBuyRing:Destroy(); autoBuyRing = nil end
		local e = workspace:FindFirstChild("TrxAutoBuyRing")
		if e then e:Destroy() end
	end

	local _abRingFrame = 0
	RunService.Heartbeat:Connect(function()
		if not autoBuyActive then return end
		_abRingFrame = _abRingFrame + 1
		if _abRingFrame < 3 then return end
		_abRingFrame = 0
		local char = LP.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		if not hrp or not autoBuyRing then return end
		local range = buyRange()
		autoBuyRing.Size = Vector3.new(0.5, range * 2, range * 2)
		autoBuyRing.CFrame = (hrp.CFrame * CFrame.Angles(0, 0, math.rad(90))) + Vector3.new(0, -2.5, 0)
	end)

	local function scanConveyor()
		local results = {}

		local root = workspace
		for _, obj in ipairs(root:GetDescendants()) do
			if not (obj:IsA("ProximityPrompt") and obj.Enabled) then continue end
			local txt = obj.ActionText or ""
			if not (txt == "Purchase" or txt:lower():find("purchase") or txt:lower():find("comprar")) then continue end
			local part = obj.Parent
			if not part then continue end
			local realPart = (part:IsA("Attachment") and part.Parent) or part
			if not (realPart and realPart:IsA("BasePart")) then continue end
			local model, cur = nil, realPart
			for _ = 1, 8 do
				if cur and cur:IsA("Model") then model = cur; break end
				cur = cur and cur.Parent
			end
			results[#results + 1] = {
				name = (model and model.Name ~= "" and model.Name) or "Brainrot",
				prompt = obj,
				part = realPart,
				model = model,
			}
		end
		return results
	end
	local function refreshConveyor()
		local found = scanConveyor()
		if not found then return end
		conveyorAnimals = found
	end
	_G.refreshConveyor = refreshConveyor

		local function resolvePurchaseRemote()
		if purchaseRemote and purchaseRemote.Parent then return purchaseRemote end
		if type(_G.TrxGetRemote) == "function" then
			local r = _G.TrxGetRemote("BuyAnimal") or _G.TrxGetRemote("Purchase") or _G.TrxGetRemote("Buy")
			if r then purchaseRemote = r; return purchaseRemote end
		end
		if type(_G.__secureGetRemote) == "function" then
			local r = _G.__secureGetRemote("RemoteEvent", "BuyAnimal")
				or _G.__secureGetRemote("RemoteEvent", "Purchase")
			if r then purchaseRemote = r; return purchaseRemote end
		end
		return purchaseRemote
	end

local function primePrompt(prompt)
		if not prompt or prompt:GetAttribute("TrxPrimed") then return end
		do
			prompt.HoldDuration = 0
			prompt.RequiresLineOfSight = false
			prompt:SetAttribute("TrxPrimed", true)
		end
	end

	local lastPromptFire = setmetatable({}, {__mode = "k"})
	local function firePurchaseNatural(prompt)
		if not prompt or not prompt.Parent or not prompt.Enabled then return end
		primePrompt(prompt)
		local fireFn = fireproximityprompt or _G.__TrxFirePrompt
		local now = os.clock()
		if lastPromptFire[prompt] and now - lastPromptFire[prompt] < 0.03 then return end
		lastPromptFire[prompt] = now
				if type(fireFn) == "function" then
			pcall(function() fireFn(prompt, 0) end)
		else
			do
				prompt:InputHoldBegin()
				prompt:InputHoldEnd()
			end
		end
	end

	local function entryAlive(entry)
		if type(entry) ~= "table" then return false end
		local pr, part = entry.prompt, entry.part
		if not (part and part.Parent) then return false end
		if entry.model and not entry.model.Parent then return false end
		if not (pr and pr.Parent) then return false end
		return true
	end

	local skipUntil = setmetatable({}, {__mode = "k"})
	local function entrySelectable(entry, now)
		if not entryAlive(entry) then return false end
		if not entry.prompt.Enabled then return false end
		local until_ = skipUntil[entry.prompt]
		return not (until_ and now < until_)
	end

	local function releaseLock(now, park)
		if park and lockedEntry and lockedEntry.prompt then
			skipUntil[lockedEntry.prompt] = now + (tonumber(_G.TrxAutoBuySkipTime) or 1.5)
		end
		lockedEntry = nil
	end

	local function pickBuyEntry(hrp, now)
		if not hrp then return nil end
		if entryAlive(lockedEntry) then
			return lockedEntry
		else
			lockedEntry = nil
		end

		local radius = buyRange()
		local best, bestDist = nil, math.huge
		for _, entry in ipairs(conveyorAnimals) do
			if entrySelectable(entry, now) then
				local d = (hrp.Position - entry.part.Position).Magnitude
				if d <= radius and d < bestDist then
					bestDist = d
					best = entry
				end
			end
		end
		lockedEntry = best
		return best
	end

		local function fireAllPurchasesInRange(hrp, primary)
		if not hrp then return end
		if primary and entryAlive(primary) then
			firePurchaseNatural(primary.prompt)
		end
	end

	local _abLastScan = 0
	local _abLastFire = 0

		local function _tpBusy()
		return _G.TrxIsTeleporting == true
			or _G.trxIsTeleporting == true
			or _G.__TrxManualTPActive == true
			or (type(_G.TrxIsMovementBusy) == "function" and _G.TrxIsMovementBusy())
	end

	local _trxPlayerCoordsLastUpdate = 0
	_G.TrxPlayerPositionCache = _G.TrxPlayerPositionCache or {}
	local function updateTrxPlayerPositionCache(now)
		if now - _trxPlayerCoordsLastUpdate < 0.5 then return end
		_trxPlayerCoordsLastUpdate = now
		local cache = {}
		for _, player in ipairs(Players:GetPlayers()) do
			local character = player.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root then cache[player.UserId] = { name = player.Name, position = root.Position, updatedAt = now } end
		end
		_G.TrxPlayerPositionCache = cache
		_G.TrxPlayerPositionCacheAt = now
	end

	local function trackAutoBuy()
		if not autoBuyActive then return end
		if _tpBusy() then return end
		local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
		if not hrp then return end
		if entryAlive(lockedEntry) then
			snapToBuyTarget(hrp, lockedEntry.part)
		end
	end

	local function tickAutoBuy()
		if not autoBuyActive then return end
		local now = os.clock()
		updateTrxPlayerPositionCache(now)
		if _tpBusy() then return end
		local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
		if not hrp then return end
		local now = os.clock()

		if now - _abLastScan >= (tonumber(_G.TrxAutoBuyScanInterval) or 0.35) then
			_abLastScan = now
			refreshConveyor()
		end
		local near = pickBuyEntry(hrp, now)
		if near and near.part then
			snapToBuyTarget(hrp, near.part)
		end
		if now - _abLastFire >= (tonumber(_G.TrxAutoBuyFireInterval) or 0.02) then
			_abLastFire = now
			fireAllPurchasesInRange(hrp, near)
		end
	end

	local function startCarpetLock()
		if carpetLockConn then carpetLockConn:Disconnect(); carpetLockConn = nil end
		local lastEquipAt = 0
		carpetLockConn = RunService.Heartbeat:Connect(function()
			if not autoBuyActive then return end
			local now = os.clock()
			-- Check periodically, but never fight a manual unequip during its 1.6s cooldown.
			if now - lastEquipAt < 0.5 then return end
			if now < _trxCarpetReequipUntil or _G.TrxFlashEquipLock == true then return end
			lastEquipAt = now

			-- Equip only the selected carpet. A failed attempt is retried at most twice per second.
			local selectedName = currentCarpetTool()
			local tool = findTool(selectedName)
			local char = LP.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if tool and tool:IsA("Tool") and hum and tool.Parent ~= char then
				pcall(function() hum:EquipTool(tool) end)
			end
		end)
	end
	local function stopCarpetLock()
		if carpetLockConn then carpetLockConn:Disconnect(); carpetLockConn = nil end
	end

	local function startConveyorWatch()
		if conveyorWatchConn then return end
		conveyorWatchConn = workspace.DescendantAdded:Connect(function(obj)
			if not autoBuyActive then return end
			if not obj:IsA("ProximityPrompt") then return end
			local txt = obj.ActionText or ""
			if txt == "Purchase" or txt:lower():find("purchase") or txt:lower():find("comprar") then
				refreshConveyor()
			end
		end)
	end

	local function stopConveyorWatch()
		if conveyorWatchConn then
			conveyorWatchConn:Disconnect()
			conveyorWatchConn = nil
		end
	end
	task.spawn(function()
		local function norm(s)
			return tostring(s or ""):lower():gsub("[%s%-_'%.:+]", "")
		end

		local function matches(a, b)
			if a == "" or b == "" then return false end
			if a == b then return true end
			if #a >= 4 and string.find(a, b, 1, true) then return true end
			if #b >= 4 and string.find(b, a, 1, true) then return true end
			return false
		end

		local function myPlot()
			local plots = workspace:FindFirstChild("Plots")
			if not plots then return nil end
			for _, plot in ipairs(plots:GetChildren()) do
				local sign = plot:FindFirstChild("PlotSign")
				if sign then
					local yb = sign:FindFirstChild("YourBase")
					if yb and yb:IsA("BillboardGui") and yb.Enabled then return plot end
				end
			end
			return nil
		end

		local function promptObjectText(att)
			if not att then return nil end
			for _, p in ipairs(att:GetChildren()) do
				if p:IsA("ProximityPrompt") then
					local ot = tostring(p.ObjectText or "")
					if ot ~= "" then return ot end
				end
			end
			return nil
		end

		local function scanConveyor()
			local out = {}
			for _, obj in ipairs(workspace:GetDescendants()) do
				if not (obj:IsA("ProximityPrompt") and obj.Enabled) then continue end
				local txt = obj.ActionText or ""
				if txt == "Purchase" or txt:lower():find("purchase") or txt:lower():find("comprar") then
					local part = obj.Parent
					local realPart = (part and part:IsA("Attachment") and part.Parent) or part
					if realPart and realPart:IsA("BasePart") then
						local ot = tostring(obj.ObjectText or "")
						local model, cur = nil, realPart
						for _ = 1, 8 do
							if cur and cur:IsA("Model") then model = cur; break end
							cur = cur and cur.Parent
						end
						local name = ot ~= "" and ot or (model and model.Name) or "Brainrot"
						out[#out + 1] = { name = name, part = realPart }
					end
				end
			end
			return out
		end

		local function scanBase()
			local out = {}
			local plot = myPlot()
			if not plot then return out, plot end
			local podiums = plot:FindFirstChild("AnimalPodiums")
			if not podiums then return out, plot end
			for _, podium in ipairs(podiums:GetChildren()) do
				if not tonumber(podium.Name) then continue end
				local name
				local base = podium:FindFirstChild("Base")
				local sp = base and base:FindFirstChild("Spawn")
				local att = sp and sp:FindFirstChild("PromptAttachment")
				local ot = promptObjectText(att)
				if ot then
					name = ot
				else
					for _, ch in ipairs(podium:GetChildren()) do
						if ch:IsA("Model") and ch:FindFirstChildOfClass("Humanoid") then
							name = ch.Name
							break
						end
					end
				end
				if name and name ~= "" then
					out[#out+1] = norm(name)
				end
			end
			return out, plot
		end

		local bought, baseline = {}, {}
		local wasOn = false
		local armed = false
		local lastDbg = 0

		while true do
			task.wait(0.1)
			local onNow = (_G.TrxAutoBuy == true)

			if onNow and not wasOn then
				bought = {}
				baseline = {}
				armed = false
			elseif (not onNow) and wasOn then
				bought, baseline = {}, {}
				armed = false
			end
			wasOn = onNow

			if onNow and not armed then
				local bl, plot = scanBase()
				if plot then
					baseline = {}
					for _, n in ipairs(bl) do baseline[n] = (baseline[n] or 0) + 1 end
					armed = true
					warn("[BaseWatcher] armed (baseline: " .. tostring(#bl) .. " pets)")
				end
			end

			if onNow and armed then
				local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
				for _, e in ipairs(scanConveyor()) do
					if hrp and (hrp.Position - e.part.Position).Magnitude <= 30 then
						bought[norm(e.name)] = true
					end
				end

				local nowList = scanBase()
				local counts = {}
				for _, n in ipairs(nowList) do counts[n] = (counts[n] or 0) + 1 end

				local now = os.clock()
				if now - lastDbg > 2 then
					lastDbg = now
					local cl, bl, bgl = {}, {}, {}
					for k, v in pairs(counts) do cl[#cl+1] = k .. "=" .. v end
					for k, v in pairs(baseline) do bl[#bl+1] = k .. "=" .. v end
					for k in pairs(bought) do bgl[#bgl+1] = k end
					warn("[BaseWatcher] buying: " .. table.concat(bgl, ",")
						.. " || now: " .. table.concat(cl, ",")
						.. " || base: " .. table.concat(bl, ","))
				end

				for n, c in pairs(counts) do
					local before = baseline[n] or 0
					if c > before then
						for bk in pairs(bought) do
							if matches(bk, n) then
								warn("[BaseWatcher] KICK — " .. n)
								_G.TrxAutoBuy = false
								if type(_G.TrxPaintAutoBuy) == "function" then pcall(_G.TrxPaintAutoBuy) end
								task.defer(function()
									if type(_G.TrxDoKick) == "function" then pcall(_G.TrxDoKick, true) end
									pcall(function() LP:Kick("auto buy done") end)
									pcall(function() game:Shutdown() end)
								end)
								return
							end
						end
					end
				end
			end
		end
	end)
	RunService.Heartbeat:Connect(tickAutoBuy)
	RunService.RenderStepped:Connect(trackAutoBuy)

	local function setAutoBuy(on)
		if on ~= nil then
			autoBuyActive = on and true or false
		else
			autoBuyActive = not autoBuyActive
		end
		_G.TrxAutoBuy = autoBuyActive
		if autoBuyActive then
			createAutoBuyRing()
			refreshConveyor()
			resolvePurchaseRemote()
			startConveyorWatch()
			startCarpetLock()
		else
			lockedEntry = nil
			lockedSince = 0
			destroyAutoBuyRing()
			stopCarpetLock()
			stopConveyorWatch()
		end
		if type(_G.TrxPaintAutoBuy) == "function" then _G.TrxPaintAutoBuy() end
	end
	_G.TrxSetAutoBuy = setAutoBuy
	_G.toggleAutoBuy = function(v)
		if v == nil then setAutoBuy(not autoBuyActive) else setAutoBuy(v) end
	end
	if _G.TrxAutoBuy == true then
		task.defer(function() setAutoBuy(true) end)
	end
end
do
	local wsOn, wsConn = false, nil
	local DEFAULT_WS = 16
	local function wantSpeed()
		return math.clamp(tonumber(_G.TrxWalkSpeed) or DEFAULT_WS, 16, 100)
	end
	local function restoreDefault()
		do
			local c = LP.Character
			local hum = c and c:FindFirstChildOfClass("Humanoid")
			if hum then hum.WalkSpeed = DEFAULT_WS end
		end
	end
	local function setWalkSpeedOn(on)
		wsOn = on and true or false
		_G.TrxWalkSpeedOn = wsOn
		if wsConn then wsConn:Disconnect(); wsConn = nil end
		if type(_G.TrxPaintWalkSpeed) == "function" then _G.TrxPaintWalkSpeed() end
		if not wsOn then
			restoreDefault()
			return
		end
		wsConn = RunService.Heartbeat:Connect(function(dt)
			local c = LP.Character
			if not c then return end
			local hum = c:FindFirstChildOfClass("Humanoid")
			local hrp = c:FindFirstChild("HumanoidRootPart")
			if not hum or not hrp or hum.Health <= 0 then return end
			local want = wantSpeed()
			if hum.MoveDirection.Magnitude > 0 and want > hum.WalkSpeed then
				hrp.CFrame = hrp.CFrame + (hum.MoveDirection * (want - hum.WalkSpeed) * dt)
			end
		end)
	end
	_G.TrxSetWalkSpeed = setWalkSpeedOn
	_G.toggleWalkSpeed = function() setWalkSpeedOn(not wsOn) end
	do
		LP.CharacterAdded:Connect(function()
			task.wait(0.4)
			if wsOn then setWalkSpeedOn(true) end
		end)
	end
	if _G.TrxWalkSpeedOn == true then
		task.defer(function() setWalkSpeedOn(true) end)
	end
end

do
	local fovOn, fovConn = false, nil
	local MIN_FOV, MAX_FOV, DEFAULT_FOV = 70, 120, 70
	local function wantFov()
		return math.clamp(tonumber(_G.TrxFov) or DEFAULT_FOV, MIN_FOV, MAX_FOV)
	end
	local function applyFov()
		local cam = workspace.CurrentCamera
		if cam then cam.FieldOfView = wantFov() end
	end
	local function restoreDefault()
		local cam = workspace.CurrentCamera
		if cam then cam.FieldOfView = DEFAULT_FOV end
	end
	local function setFovOn(on)
		fovOn = on and true or false
		_G.TrxFovOn = fovOn
		if fovConn then fovConn:Disconnect(); fovConn = nil end
		if type(_G.TrxPaintFov) == "function" then _G.TrxPaintFov() end
		if not fovOn then
			restoreDefault()
			return
		end
		applyFov()
		fovConn = RunService.Heartbeat:Connect(applyFov)
	end
	_G.TrxSetFov = setFovOn
	_G.toggleFov = function() setFovOn(not fovOn) end
	do
		workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
			task.wait(0.05)
			if fovOn then applyFov() end
		end)
	end
	if _G.TrxFovOn == true then
		task.defer(function() setFovOn(true) end)
	end
end

do
	local dropBusy, flinging = false, false
	local function dropRoot(char)
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		return hum and hum.RootPart
	end
	local function flingBurst(duration)
		if flinging then return end
		flinging = true
		local t0 = os.clock()
		while flinging and (os.clock() - t0) < duration do
			RunService.Heartbeat:Wait()
			local char = LP.Character
			local root = dropRoot(char)
			if not (char and char.Parent and root and root.Parent) then break end
			local vel = root.AssemblyLinearVelocity
			if vel.Magnitude < 0.1 then vel = root.CFrame.LookVector * 80 end
			local boom = vel * 10000 + Vector3.new(0, 10000, 0)
			do
				root.Velocity = boom
				root.AssemblyLinearVelocity = boom
			end
			RunService.RenderStepped:Wait()
			if char and char.Parent and root and root.Parent then
				root.Velocity = vel
					root.AssemblyLinearVelocity = vel
			end
			RunService.Stepped:Wait()
			if char and char.Parent and root and root.Parent then
				local nudge = vel + Vector3.new(0, 0.1, 0)
				root.Velocity = nudge
					root.AssemblyLinearVelocity = nudge
			end
		end
		flinging = false
		local root = dropRoot(LP.Character)
		if root and root.Parent then
			root.Velocity = Vector3.zero
				root.AssemblyLinearVelocity = Vector3.zero
		end
	end
	_G.TrxDropBrainrotActive = function() return dropBusy == true end
	_G.TrxDropBrainrot = function()
		if dropBusy then return false end
		dropBusy = true
		_G.TrxDropRecToken = os.clock() + (tonumber(_G.TrxHitRecoveryDropTokenTail) or 2)
		local ok, err = pcall(function()
			if _G.invisibleStealEnabled == true and type(_G.toggleInvisibleSteal) == "function" then
				_G.toggleInvisibleSteal()
				task.wait(0.2)
			end
			flingBurst(0.3)
			task.wait(0.2)
		end)
		dropBusy = false
		_G.TrxDropRecToken = os.clock() + (tonumber(_G.TrxHitRecoveryDropTokenTail) or 2)
		if not ok then warn("[Trx Drop Brainrot] " .. tostring(err)) end
		return ok
	end
	do
		LP.CharacterAdded:Connect(function()
			flinging = false
			dropBusy = false
		end)
	end
end

do
	local espOn = false
	local espConns = {}
	local espHolders = {}
	local lineConn

	local function guiParent()
		local pg = LP:FindFirstChild("PlayerGui")
		if pg then return pg end
		if gethui then
			local h = gethui()
			if h then return h end
		end
		local cg = game:GetService("CoreGui")
		return cg or nil
	end

	local function clearHolder(plr)
		local h = espHolders[plr]
		if h then h:Destroy() end
		espHolders[plr] = nil
	end

	local function bestPetForOwner(ownerName)
		local list = _G.TrxStealPetList
		if type(list) ~= "table" or not ownerName then return nil end
		local best
		for _, pet in ipairs(list) do
			if pet and tostring(pet.owner or "") == ownerName then
				if not best or (tonumber(pet.mps) or 0) > (tonumber(best.mps) or 0) then
					best = pet
				end
			end
		end
		return best
	end

	local function makeEsp(plr)
		if not espOn or plr == LP then return end
		local char = plr.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		if not hrp then return end
		clearHolder(plr)
		local parent = guiParent()
		if not parent then return end
		local holder = Instance.new("ScreenGui")
		holder.Name = "TrxEspHL_" .. plr.Name
		holder.ResetOnSpawn = false
		holder.IgnoreGuiInset = true
		holder.Parent = parent
		local hl = Instance.new("Highlight")
		hl.Adornee = char
		hl.FillColor = Color3.fromRGB(255, 80, 80)
		hl.FillTransparency = 0.6
		hl.OutlineColor = Color3.fromRGB(255, 180, 180)
		hl.OutlineTransparency = 0
		hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		hl.Parent = holder
		local bb = Instance.new("BillboardGui")
		bb.Adornee = hrp
		bb.AlwaysOnTop = true
		bb.Size = UDim2.new(0, 180, 0, 44)
		bb.StudsOffset = Vector3.new(0, 3.2, 0)
		bb.Parent = holder
		local nameLbl = Instance.new("TextLabel")
		nameLbl.Size = UDim2.new(1, 0, 0.5, 0)
		nameLbl.BackgroundTransparency = 1
		nameLbl.Text = plr.Name
		nameLbl.Font = Enum.Font.GothamBold
		nameLbl.TextSize = 14
		nameLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
		nameLbl.TextStrokeTransparency = 0.3
		nameLbl.Parent = bb
		local petLbl = Instance.new("TextLabel")
		petLbl.Size = UDim2.new(1, 0, 0.5, 0)
		petLbl.Position = UDim2.new(0, 0, 0.5, 0)
		petLbl.BackgroundTransparency = 1
		petLbl.Text = ""
		petLbl.Font = Enum.Font.Gotham
		petLbl.TextSize = 11
		petLbl.TextColor3 = Color3.fromRGB(200, 255, 180)
		petLbl.TextStrokeTransparency = 0.4
		petLbl.Parent = bb
		espHolders[plr] = holder
		local last = 0
		local hb = RunService.Heartbeat:Connect(function()
			if not espOn or not plr.Parent then return end
			local now = os.clock()
			if now - last < 0.5 then return end
			last = now
			local pet = bestPetForOwner(plr.Name)
			petLbl.Text = pet and ((pet.name or "?") .. " " .. (pet.genText or "")) or ""
			if plr.Character then
				local nh = plr.Character:FindFirstChild("HumanoidRootPart")
				if nh then
					bb.Adornee = nh
					hl.Adornee = plr.Character
				end
			end
		end)
		espConns[#espConns + 1] = hb
		local ca = plr.CharacterAdded:Connect(function(newChar)
			if not espOn then return end
			clearHolder(plr)
			newChar:WaitForChild("HumanoidRootPart", 5)
			if espOn then makeEsp(plr) end
		end)
		espConns[#espConns + 1] = ca
	end

	local function setEspPlayer(on)
		on = on and true or false
		_G.TrxEspPlayer = on
		if on == espOn then return end
		if not on then
			espOn = false
			for _, c in ipairs(espConns) do
				pcall(function() c:Disconnect() end)
			end
			espConns = {}
			for plr in pairs(espHolders) do clearHolder(plr) end
			return
		end
		espOn = true
		for _, plr in ipairs(Players:GetPlayers()) do
			if plr ~= LP then makeEsp(plr) end
		end
		espConns[#espConns + 1] = Players.PlayerAdded:Connect(function(plr)
			if not espOn then return end
			task.wait(1)
			makeEsp(plr)
		end)
		espConns[#espConns + 1] = Players.PlayerRemoving:Connect(function(plr)
			clearHolder(plr)
		end)
	end
	_G.TrxSetEspPlayer = setEspPlayer

	local ATT0_BASE, ATT1_BASE = "TrxLineBase_A0", "TrxLineBase_A1"
	local ATT0_BR, ATT1_BR = "TrxLineBr_A0", "TrxLineBr_A1"

	local function getDummy(name)
		local d = workspace:FindFirstChild(name)
		if d and d:IsA("BasePart") then return d end
		d = Instance.new("Part")
		d.Name = name
		d.Anchored = true
		d.CanCollide = false
		d.CanQuery = false
		d.CanTouch = false
		d.CastShadow = false
		d.Transparency = 1
		d.Size = Vector3.new(0.2, 0.2, 0.2)
		d.Parent = workspace
		return d
	end

	local function getAtt(part, name, offset)
		if not part then return nil end
		local a = part:FindFirstChild(name)
		if not (a and a:IsA("Attachment")) then
			a = Instance.new("Attachment")
			a.Name = name
			a.Parent = part
		end
		a.Position = offset or Vector3.zero
		return a
	end

	local function makeBeam(parent, name, color)
		local old = parent and parent:FindFirstChild(name)
		if old then old:Destroy() end
		local b = Instance.new("Beam")
		b.Name = name
		b.FaceCamera = true
		b.LightEmission = 1
		b.LightInfluence = 0
		b.Color = ColorSequence.new(color)
		b.Transparency = NumberSequence.new(0)
		b.Width0 = 0.28
		b.Width1 = 0.28
		b.Segments = 6
		b.Enabled = false
		b.Parent = parent
		return b
	end

	local function hideBeam(b)
		if b then b.Enabled = false end
	end

	local function drawBodyLine(hrp, worldPos, livePart, pack)
		if not hrp or not worldPos then
			hideBeam(pack.beam)
			return
		end
		pack.att0 = getAtt(hrp, pack.att0Name, Vector3.zero)
		local target = livePart
		if not (target and target.Parent) then
			pack.dummy = getDummy(pack.dummyName)
			pack.dummy.CFrame = CFrame.new(worldPos)
			target = pack.dummy
		end
		pack.att1 = getAtt(target, pack.att1Name, pack.att1Off or Vector3.new(0, 2, 0))
		if not pack.beam or pack.beam.Parent ~= hrp then
			pack.beam = makeBeam(hrp, pack.beamName, pack.color)
		end
		pack.beam.Attachment0 = pack.att0
		pack.beam.Attachment1 = pack.att1
		pack.beam.Enabled = true
	end

	local packBase = {
		att0Name = ATT0_BASE, att1Name = ATT1_BASE, dummyName = "TrxLineToBaseAnchor",
		beamName = "TrxLineToBase", color = Color3.fromRGB(255, 255, 255),
		att1Off = Vector3.zero,
	}
	local packBr = {
		att0Name = ATT0_BR, att1Name = ATT1_BR, dummyName = "TrxLineToBrainrotAnchor",
		beamName = "TrxLineToBrainrot", color = Color3.fromRGB(186, 150, 255),
		att1Off = Vector3.new(0, 2.5, 0),
	}
	do
		for _, n in ipairs({ "TrxLineToBase", "TrxLineToBrainrot" }) do
			local o = workspace:FindFirstChild(n)
			if o and o:IsA("BasePart") then o:Destroy() end
		end
	end

	local function myBasePos()
		local plots = workspace:FindFirstChild("Plots")
		if not plots then return nil end
		for _, plot in ipairs(plots:GetChildren()) do
			local sign = plot:FindFirstChild("PlotSign")
			local yours = sign and sign:FindFirstChild("YourBase")
			if yours and yours.Enabled then
				local base = plot:FindFirstChild("Base") or plot:FindFirstChildWhichIsA("BasePart", true)
				if base then return base.Position end
				local cf = plot:GetPivot()
				if cf then return cf.Position end
			end
		end
		return nil
	end

	local function petWorldPos(pet)
		if type(pet) ~= "table" then return nil, nil end
		if pet.model and pet.model.Parent then
			local part = pet.model.PrimaryPart
				or pet.model:FindFirstChild("HumanoidRootPart")
				or pet.model:FindFirstChildWhichIsA("BasePart")
			if part then return part.Position, part end
			local cf = pet.model:GetPivot()
			if cf and cf.Position.Magnitude > 1 then return cf.Position, nil end
		end
		if typeof(pet.position) == "Vector3" and pet.position.Magnitude > 1 then
			return pet.position, nil
		end
		return nil, nil
	end

	local function petIsPriority(p)
		if type(p) ~= "table" then return false end
		local function norm(s)
			return tostring(s or ""):lower():gsub("[%s%-_'%.]", "")
		end
		local a, b = norm(p.name), norm(p.index)
		local lists = { _G.SHARED_PRIORITY_ITEMS, _G._stp_priorityCfg }
		for _, list in ipairs(lists) do
			if type(list) == "table" then
				for _, n in ipairs(list) do
					local nn = norm(n)
					if nn ~= "" and (nn == a or nn == b) then return true end
				end
			end
		end
		return false
	end

	local function priorityPet()
		local list = _G.TrxStealPetList
		local uid = _G.TrxManualStealUID or _G.TrxStealTargetUID
		if type(list) == "table" and uid then
			for _, p in ipairs(list) do
				if p and p.uid == uid then return p end
			end
		end
		local tgt = _G.TrxStealTarget
		if type(tgt) == "table" then return tgt end
		if type(list) ~= "table" then return nil end
		for _, p in ipairs(list) do
			if p and not p.mine and petIsPriority(p) then
				return p
			end
		end
		return nil
	end

	local function setLineToBase(on)
		_G.TrxLineToBase = on and true or false
		if not on then hideBeam(packBase.beam) end
	end
	local function setLineToBrainrot(on)
		_G.TrxLineToBrainrot = on and true or false
		if not on then hideBeam(packBr.beam) end
	end
	_G.TrxSetLineToBase = setLineToBase
	_G.TrxSetLineToBrainrot = setLineToBrainrot

	lineConn = RunService.RenderStepped:Connect(function()
		local wantBase = _G.TrxLineToBase == true
		local wantBr = _G.TrxLineToBrainrot == true
		local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
		if not hrp then
			hideBeam(packBase.beam)
			hideBeam(packBr.beam)
			return
		end
		if wantBase then
			drawBodyLine(hrp, myBasePos(), nil, packBase)
		else
			hideBeam(packBase.beam)
		end
		if wantBr then
			local pos, part = petWorldPos(priorityPet())
			drawBodyLine(hrp, pos, part, packBr)
		else
			hideBeam(packBr.beam)
		end
	end)

	local BR_ESP_MIN = 10000000
	local brEspOn = false
	local brEspEntries = {}
	local brEspConn
	local brEspAnchors

	local function clearBrEspEntry(uid)
		local e = brEspEntries[uid]
		if e then
			if e.folder then e.folder:Destroy() end
			brEspEntries[uid] = nil
		end
	end

	local function clearAllBrEsp()
		for uid in pairs(brEspEntries) do clearBrEspEntry(uid) end
		if brEspAnchors then
			brEspAnchors:Destroy()
			brEspAnchors = nil
		end
	end

	local function _brPetMps(pet)
		local m = tonumber(pet.mps) or tonumber(pet.genValue) or 0
		if m < BR_ESP_MIN then
			local ensureGen = _G.TrxEnsurePetGen
			if type(ensureGen) == "function" then
				local gm = ensureGen(pet)
				m = tonumber(gm) or m
			end
		end
		return m
	end

	local function _getOrCreateBrAnchor(uid, pos)
		if typeof(pos) ~= "Vector3" or pos.Magnitude <= 1 then return nil end
		if not brEspAnchors or not brEspAnchors.Parent then
			brEspAnchors = workspace:FindFirstChild("TrxBrEspAnchors")
			if not brEspAnchors then
				brEspAnchors = Instance.new("Folder")
				brEspAnchors.Name = "TrxBrEspAnchors"
				brEspAnchors.Parent = workspace
			end
		end
		local part = brEspAnchors:FindFirstChild(uid)
		if not part then
			part = Instance.new("Part")
			part.Name = uid
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.Transparency = 1
			part.Size = Vector3.new(0.4, 0.4, 0.4)
			part.Parent = brEspAnchors
		end
		part.CFrame = CFrame.new(pos + Vector3.new(0, 2.5, 0))
		return part
	end

	local function resolvePetModel(pet)
		if type(pet) ~= "table" then return nil, nil end
		local uid = pet.uid or (pet.plot and pet.slot and (tostring(pet.plot) .. "_" .. tostring(pet.slot)))
		local model = pet.model
		if not (model and model.Parent) and pet.plot and pet.slot then
			local plots = workspace:FindFirstChild("Plots")
			local plot = plots and plots:FindFirstChild(tostring(pet.plot))
			if plot then
				local findPodium = _findPodiumModel
				if type(findPodium) ~= "function" then
					local podiums = plot:FindFirstChild("AnimalPodiums")
					local podium = podiums and podiums:FindFirstChild(tostring(pet.slot))
					if podium then
						for _, child in ipairs(podium:GetChildren()) do
							if child:IsA("Model") and child:FindFirstChildOfClass("Humanoid") then
								if not Players:GetPlayerFromCharacter(child) then
									model = child
									break
								end
							end
						end
					end
				else
					model = select(1, findPodium(plot, tostring(pet.slot)))
				end
				if model then pet.model = model end
			end
		end
		if model and model.Parent then
			local part = model.PrimaryPart
				or model:FindFirstChild("HumanoidRootPart")
				or model:FindFirstChildWhichIsA("BasePart")
			if not part then
				part = model:FindFirstChildWhichIsA("BasePart", true)
			end
			if part then return model, part end
		end
		local pos = typeof(pet.position) == "Vector3" and pet.position
		if pos and pos.Magnitude > 1 and uid then
			local anchor = _getOrCreateBrAnchor(uid, pos)
			if anchor then return anchor, anchor end
		end
		return nil, nil
	end

	local function applyBrEsp(pet, isPri, isTop)
		local uid = pet.uid or (pet.plot and pet.slot and (tostring(pet.plot) .. "_" .. tostring(pet.slot)))
		if not uid then return end
		local model, part = resolvePetModel(pet)
		if not model or not part then return end

		local e = brEspEntries[uid]
		if e and e.model ~= model then
			clearBrEspEntry(uid)
			e = nil
		end

		if not e then
			local folder = Instance.new("Folder")
			folder.Name = "TrxBrEsp"
			folder.Parent = model

			local hl = Instance.new("Highlight")
			hl.Name = "BrEspHL"
			hl.Adornee = model
			hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			hl.Parent = folder

			local bb = Instance.new("BillboardGui")
			bb.Name = "BrEspBB"
			bb.Adornee = part
			bb.AlwaysOnTop = true
			bb.Size = UDim2.new(0, 210, 0, 58)
			bb.StudsOffset = Vector3.new(0, 4.8, 0)
			bb.Parent = folder

			local nameLbl = Instance.new("TextLabel")
			nameLbl.Name = "Name"
			nameLbl.Size = UDim2.new(1, 0, 0.48, 0)
			nameLbl.BackgroundTransparency = 1
			nameLbl.Font = Enum.Font.GothamBlack
			nameLbl.TextSize = 15
			nameLbl.TextStrokeTransparency = 0.15
			nameLbl.Parent = bb

			local genLbl = Instance.new("TextLabel")
			genLbl.Name = "Gen"
			genLbl.Size = UDim2.new(1, 0, 0.52, 0)
			genLbl.Position = UDim2.new(0, 0, 0.48, 0)
			genLbl.BackgroundTransparency = 1
			genLbl.Font = Enum.Font.GothamBold
			genLbl.TextSize = 14
			genLbl.TextColor3 = Color3.fromRGB(255, 220, 60)
			genLbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
			genLbl.TextStrokeTransparency = 0.2
			genLbl.Parent = bb

			e = { folder = folder, hl = hl, bb = bb, nameLbl = nameLbl, genLbl = genLbl, model = model }
			brEspEntries[uid] = e
		end

		local m = _brPetMps(pet)
		local txt = pet.genText
		if type(_G.TrxEnsurePetGen) == "function" then
			local gm, gt = _G.TrxEnsurePetGen(pet)
			m = tonumber(gm) or m
			txt = gt or txt
		end
		e.nameLbl.Text = pet.name or pet.index or "?"
		e.genLbl.Text = txt or ("$" .. tostring(math.floor(m + 0.5)) .. "/s")

		if isTop then
			e.hl.FillColor = Color3.fromRGB(255, 215, 0)
			e.hl.OutlineColor = Color3.fromRGB(255, 245, 120)
			e.hl.FillTransparency = 0.28
			e.hl.OutlineTransparency = 0
			e.nameLbl.TextColor3 = Color3.fromRGB(255, 230, 80)
		elseif isPri then
			e.hl.FillColor = Color3.fromRGB(255, 45, 210)
			e.hl.OutlineColor = Color3.fromRGB(255, 170, 240)
			e.hl.FillTransparency = 0.32
			e.hl.OutlineTransparency = 0
			e.nameLbl.TextColor3 = Color3.fromRGB(255, 70, 255)
		else
			e.hl.FillColor = Color3.fromRGB(0, 210, 255)
			e.hl.OutlineColor = Color3.fromRGB(160, 235, 255)
			e.hl.FillTransparency = 0.42
			e.hl.OutlineTransparency = 0.05
			e.nameLbl.TextColor3 = Color3.fromRGB(210, 245, 255)
		end
		e.bb.Adornee = part
		e.hl.Adornee = model
	end

	local function _collectBrEspPets()
		local byUid = {}
		local function add(pet)
			if type(pet) ~= "table" or pet.mine or not pet.plot or not pet.slot then return end
			local uid = pet.uid or (tostring(pet.plot) .. "_" .. tostring(pet.slot))
			pet.uid = uid
			if not byUid[uid] then byUid[uid] = pet end
		end
		local list = _G.TrxStealPetList
		if type(list) == "table" then
			for _, pet in ipairs(list) do add(pet) end
		end
		if next(byUid) == nil then
			local scanFn = _G.Trx_ScanAllPets
			if type(scanFn) == "function" then
				local pets = scanFn(true)
				if type(pets) == "table" then
					local buildList = _G.TrxBuildStealPetList
					if type(buildList) == "function" then
						pets = buildList(pets, _G.TrxStealMode)
					end
					for _, pet in ipairs(pets) do add(pet) end
				end
			end
		end
		local out = {}
		for _, pet in pairs(byUid) do out[#out + 1] = pet end
		return out
	end

	local function refreshBrEsp()
		if not brEspOn then return end
		local pets = _collectBrEspPets()
		if #pets == 0 then return end

		local topUid, topMps = nil, -1
		for _, pet in ipairs(pets) do
			local m = _brPetMps(pet)
			if m > topMps then
				topMps = m
				topUid = pet.uid
			end
		end

		local seen = {}
		for _, pet in ipairs(pets) do
			local m = _brPetMps(pet)
			local isPri = petIsPriority(pet)
			local isTop = topUid ~= nil and pet.uid == topUid and topMps > 0
			if isTop or m >= BR_ESP_MIN or isPri then
				local uid = pet.uid
				seen[uid] = true
				applyBrEsp(pet, isPri, isTop)
			end
		end
		for uid in pairs(brEspEntries) do
			if not seen[uid] then clearBrEspEntry(uid) end
		end
	end

	local function setBrainrotEsp(on)
		on = on and true or false
		_G.TrxBrainrotEsp = on
		if on == brEspOn then return end
		brEspOn = on
		if not on then
			if brEspConn then
				brEspConn:Disconnect()
				brEspConn = nil
			end
			clearAllBrEsp()
			return
		end
		local last = 0
		brEspConn = RunService.Heartbeat:Connect(function()
			local now = os.clock()
			if now - last < 0.35 then return end
			last = now
			refreshBrEsp()
		end)
		task.defer(refreshBrEsp)
	end
	_G.TrxSetBrainrotEsp = setBrainrotEsp

	if type(_G.TrxAfterCoreLoad) == "function" then
		_G.TrxAfterCoreLoad(function()
			if _G.TrxEspPlayer == true then pcall(setEspPlayer, true) end
			if _G.TrxBrainrotEsp == true then pcall(setBrainrotEsp, true) end
		end)
	else
		task.defer(function()
			if _G.TrxEspPlayer == true then pcall(setEspPlayer, true) end
			if _G.TrxBrainrotEsp == true then pcall(setBrainrotEsp, true) end
		end)
	end
end

