_G.trxBoostWindow = tonumber(_G.trxBoostWindow) or 20

if not f2UnderActive then
    f2UnderActive = function(y)
        local on = _G.Trx_F2StealBelow
        if on == nil then
            on = _G.TrxF2StealBelow or false
        end
        return on == true and y > 10 and y <= 22
    end
