if not getClosestBaseSign then
    local _signCache, _signCacheAt = nil, 0
    local function _rebuildSignCache()
        local out = {}
        for _, label in ipairs(Workspace:GetDescendants()) do
            if label.ClassName == "TextLabel" then
                local txt = label.Text
                if type(txt) == "string" and #txt >= 4
                   and txt:lower():find("base", 1, true) then
                    local gui = label:FindFirstAncestorWhichIsA("SurfaceGui")
                    if gui then
                        local part = gui.Adornee or gui.Parent
                        if part and part:IsA("BasePart") then out[#out + 1] = part end
                    end
                end
            end
        end
        _signCache, _signCacheAt = out, tick()
        return out
    end
    getClosestBaseSign = function(brainrotPart)
        if not brainrotPart or not brainrotPart:IsA("BasePart") then return nil end
        local list = _signCache
        if not list or #list == 0 or (tick() - _signCacheAt) > 15 then
            list = _rebuildSignCache()
        end
        local closest, closestDist = nil, math.huge
        for i = 1, #list do
            local part = list[i]
            if part.Parent then
                local dist = (part.Position - brainrotPart.Position).Magnitude
                if dist < closestDist then closestDist = dist closest = part end
            end
        end
        return closest
    end
end

if not getSignInwardDir then
    getSignInwardDir = function(signPart)
        if not (signPart and signPart:IsA("BasePart")) then return Vector3.new(1, 0, 0) end
        local outward
        local gui = signPart:FindFirstChildWhichIsA("SurfaceGui", true)
        if gui then
            outward = signPart.CFrame:VectorToWorldSpace(Vector3.FromNormalId(gui.Face))
        else
            local s, cf = signPart.Size, signPart.CFrame
            if s.Z <= s.X and s.Z <= s.Y then outward = cf.LookVector
            elseif s.X <= s.Y then outward = cf.RightVector
            else outward = cf.UpVector end
        end
        outward = Vector3.new(outward.X, 0, outward.Z)
        if outward.Magnitude < 0.01 then return Vector3.new(1, 0, 0) end
        return -outward.Unit
    end
end

if not isPlotUnlocked then
    isPlotUnlocked = function(plotName, skipChan)
        local ok, res = pcall(function()
            local plots = Workspace:FindFirstChild("Plots")
            if not plots then return false end
            local plot = plots:FindFirstChild(plotName)
            if not plot then return false end
            local laser = plot:FindFirstChild("LaserHitbox")
            laser = laser and (laser:FindFirstChild("Main") or laser:FindFirstChildWhichIsA("BasePart"))
            if not laser then return false end
            if laser.CanCollide then return false end
            local uf = plot:FindFirstChild("Unlock")
            if uf then
                for _, d in ipairs(uf:GetDescendants()) do
                    if d:IsA("ProximityPrompt") and d.Enabled then return false end
                end
            end
            return true
        end)
        return ok and res == true
    end
end

if not _G.Trx_IsBeingStolen then
    _G.Trx_IsBeingStolen = function(a, memo)
        if type(a) ~= "table" then return false end
        local plotName = a.plot
        local slot = a.slot
        if not plotName or not slot then return false end
        local ch = getPlotChannel and getPlotChannel(plotName)
        if not ch then return false end
        local al = _G.sProp and _G.sProp(ch, "AnimalList")
        if type(al) ~= "table" then return false end
        local e = al[slot] or al[tostring(slot)] or al[tonumber(slot)]
        if type(e) ~= "table" then return false end
        local s = e.Steal
        if type(s) ~= "number" then return false end
        if s == LocalPlayer.UserId then return false end
        for _, p in ipairs(Players:GetPlayers()) do
            if p.UserId == s then return p:GetAttribute("Stealing") == true end
        end
        return false
    end
end

if not _G.Trx_M2 then
    _G.Trx_M2 = function(ax, az, bx, bz)
        local dx, dz = ax - bx, az - bz
        return math.sqrt(dx * dx + dz * dz)
    end
end

if not _G.Trx_PetAlive then
