local _tpVizParts = {}
local _cloneVizParts = {}
local function _clearTpViz()
	_G.__tpVizGen = (_G.__tpVizGen or 0) + 1
	for _, p in ipairs(_tpVizParts) do
		if p and p.Parent then p:Destroy() end
	end
	table.clear(_tpVizParts)
end
local function _clearCloneViz()
	_G.__cloneVizGen = (_G.__cloneVizGen or 0) + 1
	for _, p in ipairs(_cloneVizParts) do
		if p and p.Parent then p:Destroy() end
	end
	table.clear(_cloneVizParts)
