end
local function _mkOrb(pos, color, name, bag)
	local p = Instance.new("Part")
	p.Name = name or "TrxPathOrb"
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	p.CastShadow = false
	p.Shape = Enum.PartType.Ball
	p.Material = Enum.Material.Neon
	p.Color = color
	p.Size = Vector3.new(1.35, 1.35, 1.35)
	p.Position = pos
	p.Parent = workspace
	bag[#bag + 1] = p
	return p
end
local function _mkSolidSeg(a, b, color, name, bag, thickness)
	local d = b - a
	local mag = d.Magnitude
	if mag < 0.05 then return end
	local p = Instance.new("Part")
	p.Name = name or "TrxPathSeg"
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	p.CastShadow = false
	p.Material = Enum.Material.Neon
	p.Color = color
	p.Size = Vector3.new(thickness or 0.32, thickness or 0.32, mag)
	p.CFrame = CFrame.new((a + b) / 2, b)
	p.Parent = workspace
	bag[#bag + 1] = p
end
local function _mkDashedSeg(a, b, color, name, bag, thickness)
	local d = b - a
	local mag = d.Magnitude
	if mag < 0.05 then return end
	local dir = d.Unit
	local dashLen = 2.2
	local gapLen = 1.4
	local t = 0
	while t < mag do
		local a0 = a + dir * t
		local a1 = a + dir * math.min(t + dashLen, mag)
		_mkSolidSeg(a0, a1, color, name, bag, thickness or 0.28)
		t = t + dashLen + gapLen
	end
end
local function _vizTpPath(fromPos, waypoints)
	if _G.TrxShowTPPath == false then return end
	if not fromPos or not waypoints or #waypoints == 0 then return end
	_clearTpViz()
	local LINE = Color3.fromRGB(40, 140, 255)
	local ORB = Color3.fromRGB(80, 180, 255)
	local endPos = waypoints[#waypoints]
	local prev = fromPos
	for _, wp in ipairs(waypoints) do
		_mkSolidSeg(prev, wp, LINE, "TrxTpPath", _tpVizParts, 0.34)
		prev = wp
	end
	_mkOrb(fromPos, ORB, "TrxTpOrbStart", _tpVizParts)
	_mkOrb(endPos, ORB, "TrxTpOrbEnd", _tpVizParts)
end
local function _vizClonePath(fromPos, toPos)
	if _G.TrxShowTPPath == false then return end
	if not fromPos or not toPos then return end
	if (toPos - fromPos).Magnitude < 0.5 then return end
	_clearCloneViz()
	local LINE = Color3.fromRGB(255, 255, 255)
	local ORB = Color3.fromRGB(240, 240, 255)
	_mkDashedSeg(fromPos, toPos, LINE, "TrxClonePath", _cloneVizParts, 0.28)
	_mkOrb(fromPos, ORB, "TrxCloneOrbStart", _cloneVizParts)
	_mkOrb(toPos, ORB, "TrxCloneOrbEnd", _cloneVizParts)
end
_G.TrxVizClonePath = _vizClonePath

