                        end
                    end
                end
            end
        end
    end

	local _route = _roseRoute or computeRoute(hrp.Position, destPos, facingDir, nil, true)
	if type(_route) ~= "table" or #_route == 0 then _route = { destPos } end
	-- Always preserve the adjusted clone coordinate as the final waypoint.
	-- This prevents the right-side clone route from ending at an earlier Rose waypoint.
	if typeof(_route[#_route]) ~= "Vector3" or (_route[#_route] - destPos).Magnitude > 0.05 then
		_route[#_route + 1] = destPos
	end
	_G.Trx_Step("route calculee", "waypoints=" .. tostring(#_route))

	local ASCEND_STEP = 10
	local _stepped = {}
	do
		local prev = hrp.Position
		for _, wp in ipairs(_route) do
			local dy = wp.Y - prev.Y
			if dy > ASCEND_STEP * 1.5 then
				local n = math.ceil(dy / ASCEND_STEP)
				for s = 1, n - 1 do
					local t = s / n
					_stepped[#_stepped + 1] = Vector3.new(
						prev.X + (wp.X - prev.X) * t,
						prev.Y + dy * t,
						prev.Z + (wp.Z - prev.Z) * t
					)
				end
			end
			_stepped[#_stepped + 1] = wp
			prev = wp
		end
	end
		local _mainSpeed
	if _G.Trx_BoostActive and _G.Trx_BoostActive() then
		_mainSpeed = math.clamp(tonumber(_G.Trx_GrappleFlightSpeed) or tonumber(_G.TPVelocity) or 400, 400, 1200)
	else
		_mainSpeed = math.clamp(tonumber(_G.TPVelocity) or 400, 200, 750)
		local _lenR, _prev = 0, hrp.Position
		for _, wp in ipairs(_route) do _lenR = _lenR + (wp - _prev).Magnitude; _prev = wp end
		if _lenR < 100 then
			_mainSpeed = math.clamp(tonumber(_G.TrxCloseSpeed) or 80, 20, 400)
		end
		_mainSpeed = _pingAdjustSpeed(_mainSpeed)
	end
	if _G.Trx_BoostActive and _G.Trx_BoostActive() then
		_G.Trx_GrappleFlightSpeed = _mainSpeed
	end

	_G.Trx_Step("VELOCITY: demarre", "vitesse=" .. tostring(math.floor(_mainSpeed)))
	local _hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
	if _hum then _hum.AutoRotate = false end
		velMoveThrough(hrp, _stepped, _mainSpeed, true, true)
	if type(_G.Trx_GrappleStop) == "function" then pcall(_G.Trx_GrappleStop) end
	if _hum then _hum.AutoRotate = true end
	if _G.trxTPStop then
		if hrp and hrp.Parent then vZero(hrp) end
		return _abortTp()
	end

	-- Approach the cord horizontally first. Do not add an artificial +16 stud
	-- altitude target or force a Humanoid jump; that made clone-cord TP shoot upward.
	do
		local approach = Vector3.new(destPos.X, hrp.Position.Y, destPos.Z)
		local _t0 = os.clock()
		while os.clock() - _t0 < 1.5 do
			if not hrp or not hrp.Parent then break end
			if LP:GetAttribute("Stealing") or _G.trxTPStop then break end
			equipCarpet()
			local d = approach - hrp.Position
			local flat = Vector3.new(d.X, 0, d.Z).Magnitude
			if flat <= 3 then break end
			local horizontal = Vector3.new(d.X, 0, d.Z)
			if horizontal.Magnitude > 0.01 then
				_setFlightVel(hrp, horizontal.Unit * math.min(math.max(flat * 8, 55), _useFlash and FLASH_TP.goSpeed() or 320))
			end
			hrp.AssemblyAngularVelocity = Vector3.zero
			RunService.Heartbeat:Wait()
		end
	end

	do
		local _runCap = _useFlash and FLASH_TP.goSpeed() or (_frontApproach and (tonumber(_G.trxFrontRunIn) or 130) or 400)
		local _t0 = os.clock()
		local _bestMag, _bestT = math.huge, os.clock()
		while os.clock() - _t0 < 4 do
			if not hrp or not hrp.Parent then break end
			if LP:GetAttribute("Stealing") or _G.trxTPStop then break end
			equipCarpet()
			local diff = destPos - hrp.Position
			local mag = diff.Magnitude
			if mag <= 3 then break end
			if mag < _bestMag - 0.5 then _bestMag = mag; _bestT = os.clock()
			elseif os.clock() - _bestT > 0.6 then
				if mag > 12 and _G.TrxAvoid then pcall(_G.TrxAvoid.stuck, hrp.Position) end
				break
			end
			_setFlightVel(hrp, diff.Unit * math.min(math.max(mag * 8, 55), _runCap))
			hrp.AssemblyAngularVelocity = Vector3.zero
			keepTPFacing(facingDir)
			RunService.Heartbeat:Wait()
		end
	end

		if hrp and hrp.Parent and not _G.trxTPStop then
    local _finalOff = (destPos - hrp.Position).Magnitude
    if _finalOff > 4 then
        local _tw = 0
        while _tw < 1 and hrp and hrp.Parent do
            _tw = _tw + 0.15
            hrp.CFrame = hrp.CFrame:Lerp(CFrame.new(destPos, destPos + facingDir), 0.5)
            RunService.Heartbeat:Wait()
        end
    end
end

		if not hrp or not hrp.Parent then return _abortTp() end

	local _off = (destPos - hrp.Position).Magnitude
	if _off > 6 then
		if _off <= 80 then
			_G.Trx_Step("TP: HARD SNAP fallback", string.format("off=%.1f", _off))
			local _hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
			if _hum then _hum.AutoRotate = false end
			local _safeDest = destPos + Vector3.new(0, 3.5, 0)
			for _ = 1, 10 do
				if not (hrp and hrp.Parent) then break end
				hrp.AssemblyLinearVelocity = Vector3.zero
				hrp.AssemblyAngularVelocity = Vector3.zero
				hrp.CFrame = CFrame.new(_safeDest, _safeDest + facingDir)
				RunService.Heartbeat:Wait()
			end
			if _hum then _hum.AutoRotate = true end
			_G.Trx_Step("TP: hard snap done", string.format("off=%.1f", (destPos - hrp.Position).Magnitude))
		else
			return _abortTp()
		end
	end

	if (destPos - hrp.Position).Magnitude > 8 then return _abortTp() end
	local _finalDest = _useFlash and destPos or (destPos + Vector3.new(0, 2, 0))
	hrp.CFrame = CFrame.new(_finalDest, _finalDest + facingDir)
	keepTPFacing(facingDir)
	vZero(hrp)
    if _useFlash and not _G.trxTPStop then
        FLASH_TP.say("firing flash", string.format("at %.1f, %.1f, %.1f", hrp.Position.X, hrp.Position.Y, hrp.Position.Z))
        local _flashCallOK, _flashed = pcall(FLASH_TP.fire, _flashStand)
        if not _flashCallOK or _flashed ~= true then
            _G.Trx_Step("Flash TP failed", "tool missing or no confirmed flash movement; stopping instead of falling back to normal TP")
            return _abortTp()
        end
        char = LP.Character
        hrp = char and char:FindFirstChild("HumanoidRootPart") or hrp
        hum = char and char:FindFirstChildOfClass("Humanoid") or hum
        if not hrp or not hum then return _abortTp() end
        destPos = hrp.Position
        facingDir = Vector3.new(hrp.CFrame.LookVector.X, 0, hrp.CFrame.LookVector.Z)
        if facingDir.Magnitude > 0.01 then facingDir = facingDir.Unit end
    end

	if _useFlash then
    else
	local syncFrames = 5
	local syncConn
	syncConn = RunService.Heartbeat:Connect(function()
		if not hrp or not hrp.Parent then syncConn:Disconnect(); return end
		syncFrames = syncFrames - 1
		if (destPos - hrp.Position).Magnitude <= 6 then
			hrp.CFrame = CFrame.new(destPos, destPos + facingDir)
			hrp.AssemblyLinearVelocity = Vector3.zero
			hrp.AssemblyAngularVelocity = Vector3.zero
		else
			syncConn:Disconnect()
			return
		end
		if syncFrames <= 0 then syncConn:Disconnect() end
	end)

	local _syncStep = (_G.TrxCampTPOnly == true) and 0.01 or 0.02
	for _ = 1, 5 do
		task.wait(_syncStep)
		local _hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") or hum
		if _hum and _hum.Parent and _hum.FloorMaterial ~= Enum.Material.Air then break end
		if _G.trxTPStop then break end
	end
    end -- end non-Flash TP launch-spot sync

	if healConn then healConn:Disconnect() end
    -- Flash TP does not use the Quantum Cloner transition.
    local _flashMode = (_useFlash)
    _cloneTP = not _flashMode
    _cloneFired = not _flashMode
    _G.TrxCloneTP = not _flashMode
    _G.TrxCloneFired = not _flashMode
	_lastTPOk = true

	if _G.trxTPStop then _G.trxStealHold = false; endTP(); return end

	if (not _useFlash) then do
		local stable = 0
		for _ = 1, 18 do
			if _G.trxTPStop then break end
			local _hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
			if not _hrp or not _hrp.Parent then break end
			local flat = (Vector3.new(_hrp.Position.X, 0, _hrp.Position.Z) - Vector3.new(destPos.X, 0, destPos.Z)).Magnitude
			if flat <= 3.5 and math.abs(_hrp.Position.Y - destPos.Y) <= 4 then
				stable = stable + 1
				if stable >= 2 then break end
			else
				stable = 0
				local correction = destPos - _hrp.Position
				if correction.Magnitude > 0.1 then
					_setFlightVel(_hrp, correction.Unit * math.min(math.max(correction.Magnitude * 8, 40), 120))
				end
				keepTPFacing(facingDir)
			end
			RunService.Heartbeat:Wait()
		end
	end end
	if _G.trxTPStop then _G.trxStealHold = false; endTP(); return end

	local _ahrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
	local _clonePos = (_ahrp and _ahrp.Parent and _ahrp.Position) or destPos

    local _flashMode = (_useFlash)
    local _clonePlat
    if not _flashMode then
        _clonePlat = Instance.new("Part")
        _clonePlat.Name = "TrxClonePlatform"
        _clonePlat.Size = Vector3.new(12, 1, 12)
        _clonePlat.Position = Vector3.new(_clonePos.X, _clonePos.Y - 3, _clonePos.Z)
        _clonePlat.Anchored = true
        _clonePlat.CanCollide = true
        _clonePlat.Transparency = 1
        _clonePlat.Material = Enum.Material.SmoothPlastic
        _clonePlat.Parent = workspace
    end

	if _ahrp and _ahrp.Parent then
		_ahrp.AssemblyLinearVelocity = Vector3.zero
		_ahrp.AssemblyAngularVelocity = Vector3.zero
	end

	local _caConn = LP.CharacterAdded:Connect(function() end)

		_G.trxStealHold = false

	-- Flash TP: skip the ordinary post-landing wait so the existing
	-- goToBrainrot phase starts immediately after the Flash/clone transition.
	-- Base Camp follows Rose's direct transition timing; normal TRX keeps its delay.
	local _postDelay = (_useFlash or _G.TrxCampTPOnly == true) and 0 or 0.12
	local _settleDelay = 0

	if facingDir and facingDir.Magnitude > 0.1 then
		local _pinHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
		if _pinHum then _pinHum.AutoRotate = false end
		local _h = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
		if _h and _h.Parent then
			_h.CFrame = CFrame.new(_h.Position, _h.Position + facingDir)
			_h.AssemblyLinearVelocity = Vector3.zero
			_h.AssemblyAngularVelocity = Vector3.zero
		end
	end

	local _cloneSwapConfirmed = (_useFlash)
	if not _G.trxTPStop and not _flashMode then
		if _postDelay > 0 then task.wait(_postDelay) end
		if _G.trxTPStop then endTP(); return end
		local function _attemptCloneAndWait(timeout)
			local _oldChar = LP.Character
			local _oldRoot = _oldChar and _oldChar:FindFirstChild("HumanoidRootPart")
			local _oldPos = _oldRoot and _oldRoot.Position
			local _cloneOK = doClone()
			if not _cloneOK then return false end
			local _deadline = os.clock() + timeout
			while not _G.trxTPStop and os.clock() < _deadline do
				local _char = LP.Character
				local _root = _char and _char:FindFirstChild("HumanoidRootPart")
				if _char and _char ~= _oldChar then return true end
				if _root and _root.Parent and _oldRoot and _oldRoot.Parent == nil then return true end
				if _oldPos and _root and _root.Parent and (_root.Position - _oldPos).Magnitude >= 0.75 then
					return true
				end
				RunService.Heartbeat:Wait()
			end
			return false
		end
		local _swapTimeout = (_G.TrxCampTPOnly == true) and 0.3 or 0.4
		_cloneSwapConfirmed = _attemptCloneAndWait(_swapTimeout)
		if not _cloneSwapConfirmed and not _G.trxTPStop then
			_G.Trx_Step("clone: swap not detected; retrying once")
			_cloneSwapConfirmed = _attemptCloneAndWait(_swapTimeout)
		end
		if not _cloneSwapConfirmed then
			_G.Trx_Step("clone: swap failed; Insta-Go cancelled")
		end
	end

	if _clonePlat then
		local _plat = _clonePlat
		_clonePlat = nil
		task.delay(1.5, function()
			if _plat and _plat.Parent then _plat:Destroy() end
		end)
	end

	if _settleDelay > 0 and (not _useFlash) then
		task.wait(_settleDelay)
	end

	if _caConn then _caConn:Disconnect() end
	local _rh = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
	if _rh then _rh.AutoRotate = true end

	if _G.trxTPStop then endTP(); return end
	if not _cloneSwapConfirmed then
		if healConn then healConn:Disconnect() end
		endTP()
		return false
	end

	_G._curStealSlot = tonumber(pet and pet.slot) or _G._curStealSlot
	_boostGrabWindow(15)
	_G.Trx_Step("clone: goToBrainrot", tostring(pet and pet.name))
	do
		local exact, exactPos = _resolveSwitchPet(pet)
		if exact and exactPos then
			pet = exact
			petPos = exactPos
		end
	end
	goToBrainrot(petPos, {slot = pet and pet.slot, plot = pet and pet.plot, noJump = true, speed = _useFlash and FLASH_TP.goSpeed() or nil})

	if healConn then healConn:Disconnect() end
	endTP()
	return true
end

do
local _eachCandidate = function(pets, fn)
	local seen = {}
	local function one(p)
		if not p then return end
		local uid = tostring(p.uid or "")
		local key = uid ~= "" and uid or (tostring(p.plot) .. "_" .. tostring(p.slot) .. "_" .. tostring(p.index or p.name))
		if seen[key] then return end
		seen[key] = true
		fn(p)
	end
	if type(pets) == "table" then
		for _, p in ipairs(pets) do one(p) end
	end
	if type(_G.TrxStealPetList) == "table" then
		for _, p in ipairs(_G.TrxStealPetList) do one(p) end
	end
end

-- Automatic and manual TP winner selection uses the highest generation/value across all allowed targets.
_G.TrxPriorityOnlyTP = false
pickTPWinner = function(pets)
	if type(pets) ~= "table" then pets = {} end
	local man = _G.TrxManualStealUID
	if type(man) == "string" and man ~= "" then
		local locked = _findPetByUid(pets, man)
		if (not locked) and type(_G.TrxStealPetList) == "table" then
			locked = _findPetByUid(_G.TrxStealPetList, man)
		end
		if locked and _petAllowed(locked) and _petMeetsMinGen(locked) then
			return locked, true
		end
		_G.TrxManualStealUID = nil
		if type(_G.TrxClearTPSync) == "function" then _G.TrxClearTPSync() end
	end
	local hud = _buildStealPetList(pets, "value")
	if #hud == 0 and type(_G.TrxStealPetList) == "table" then
		hud = _buildStealPetList(_G.TrxStealPetList, "value")
	end
	if hud[1] then return hud[1], true end
	return nil, false
end

_G.TrxCampRunTP = function(target)
    if type(target) ~= "table" then return false end
    return doVelocityTP(false, { target })
end


-- Trx automatic Carpet Brainrot TP (highest generation/value + live coordinates).
-- Scanner follows Rose.lua's moving-animal scan rules; TP execution stays on Trx's existing mover.
do
    _trxCarpetTPBusy = false
    local _trxCarpetTPDone = setmetatable({}, { __mode = "k" })
    local _trxCarpetAnimalMap
    local _trxCarpetTargets = {}
    local _trxCarpetLastScan = 0

    -- Normalize the same way as Trx's priority/sync name matcher so display names,
    -- animal indexes, and model names resolve to the same entry.
    local function _trxCarpetNorm(v)
        if type(_normName) == "function" then return _normName(v) end
        return tostring(v or ""):lower():gsub("[%s%-_'%.:+]", "")
    end

    _G.TrxCarpetSync = _G.TrxCarpetSync or { targets = {}, lastScan = 0, detected = 0, lastTarget = nil, lastPosition = nil, status = "starting" }

    local function _trxCarpetGetAnimalMap()
        if _trxCarpetAnimalMap then return _trxCarpetAnimalMap end
        local data = _G.TrxAnimalsData
        if type(data) ~= "table" then
            local ok, loaded = pcall(function()
                return require(game:GetService("ReplicatedStorage"):WaitForChild("Datas"):WaitForChild("Animals"))
            end)
            if ok and type(loaded) == "table" then
                data = loaded
                _G.TrxAnimalsData = loaded
            end
        end
        local map = {}
        if type(data) == "table" then
            for index, info in pairs(data) do
                local entry = { index = tostring(index), info = info }
                local key = _trxCarpetNorm(index)
                map[key] = entry
                if type(info) == "table" and info.DisplayName then
                    map[_trxCarpetNorm(info.DisplayName)] = entry
                end
            end
        end
        _trxCarpetAnimalMap = map
        return map
    end

    local function _trxCarpetGetModelPos(model)
        if not model or not model.Parent then return nil end
        local part = model.PrimaryPart or model:FindFirstChild("HumanoidRootPart", true)
            or model:FindFirstChildWhichIsA("BasePart", true)
        if part then return part.Position end
        local ok, pivot = pcall(function() return model:GetPivot() end)
        return ok and pivot and pivot.Position or nil
    end

    local function _trxIsHeadlessValue(value)
        return _trxCarpetNorm(value):find("headless", 1, true) ~= nil
    end

    -- The normal priority TP may target Headless Horseman, but not a separate
    -- generic Headless entry. Carpet TP continues to exclude all Headless variants.
    local function _trxIsGenericHeadlessValue(value)
        local normalized = _trxCarpetNorm(value)
        return normalized:find("headless", 1, true) ~= nil
            and normalized:find("headlesshorseman", 1, true) == nil
    end

    local function _trxCarpetIsHeadless(model)
        if not model then return false end
        if _trxIsHeadlessValue(model.Name) then return true end
        local animal = _trxCarpetGetAnimalMap()[_trxCarpetNorm(model.Name)]
        if animal then
            if _trxIsHeadlessValue(animal.index) then return true end
            if type(animal.info) == "table" and _trxIsHeadlessValue(animal.info.DisplayName) then return true end
        end
        return false
    end

    -- Arrival behavior: start Auto Buy and equip Medusa's Head only if another
    -- player's cached/live position is within 20 studs of the target brainrot.
    local function _trxCarpetArrival(model)
        -- Headless is excluded from both teleporting and arrival-triggered Auto Buy.
        if _trxCarpetIsHeadless(model) then
            _G.TrxCarpetSync.status = "skipped Headless Horseman; Auto Buy remains unchanged"
            return false
        end
        local targetPos = _trxCarpetGetModelPos(model)
        if not targetPos then return end
        -- Trigger Auto Buy immediately on arrival; use explicit true so it never toggles off.
        if _G.TrxAutoBuy ~= true then
            if type(_G.TrxSetAutoBuy) == "function" then
                pcall(_G.TrxSetAutoBuy, true)
            elseif type(_G.toggleAutoBuy) == "function" then
                pcall(_G.toggleAutoBuy, true)
            else
                _G.TrxAutoBuy = true
            end
        end

        local nearbyPlayer = false
        local cache = _G.TrxPlayerPositionCache
        if type(cache) == "table" then
            for userId, entry in pairs(cache) do
                if tonumber(userId) ~= LP.UserId and type(entry) == "table" and typeof(entry.position) == "Vector3"
                    and (entry.position - targetPos).Magnitude <= 20 then
                    nearbyPlayer = true
                    break
                end
            end
        end
        -- On first activation the half-second cache may not have populated yet.
        if not nearbyPlayer then
            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= LP then
                    local character = player.Character
                    local root = character and character:FindFirstChild("HumanoidRootPart")
                    if root and (root.Position - targetPos).Magnitude <= 20 then
                        nearbyPlayer = true
                        break
                    end
                end
            end
        end
        if nearbyPlayer then
            local tool = findTool("Medusa's Head")
            local character = LP.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if tool and tool:IsA("Tool") and humanoid and tool.Parent ~= character then
                pcall(function() humanoid:EquipTool(tool) end)
            end
            _G.TrxCarpetSync.status = "arrived; Auto Buy on; player near target, equipping Medusa's Head"
        else
            _G.TrxCarpetSync.status = "arrived; Auto Buy on; no player within 20 studs of target"
        end
    end

    local function _trxCarpetInsidePlots(obj)
        local p = obj and obj.Parent
        while p and p ~= workspace do
            if p.Name == "Plots" then return true end
            p = p.Parent
        end
        return false
    end

    local function _trxCarpetPrompt(model)
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("ProximityPrompt") and d.Enabled and d.ActionText == "Steal" then
                return d
            end
        end
        return nil
    end

    local function _trxCarpetCarried(index, displayName)
        for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
            local value = player:GetAttribute("StealingIndex")
            if value ~= nil and tostring(value) ~= "" then
                local s = tostring(value)
                if s == tostring(index) or (displayName and s == tostring(displayName)) then return true end
                if displayName and _trxCarpetNorm(s) == _trxCarpetNorm(displayName) then return true end
            end
        end
        return false
    end

    local function _trxCarpetScan(force)
        local now = os.clock()
        if not force and now - _trxCarpetLastScan < 0.3 then
            local refreshed = {}
            for _, entry in ipairs(_trxCarpetTargets) do
                if entry.model and entry.model.Parent and not _trxCarpetTPDone[entry.model] then
                    entry.position = _trxCarpetGetModelPos(entry.model)
                    if entry.position then refreshed[#refreshed + 1] = entry end
                end
            end
            _trxCarpetTargets = refreshed
            return refreshed
        end
        _trxCarpetLastScan = now
        local out, seen = {}, {}
        local map = _trxCarpetGetAnimalMap()
        local moving = workspace:FindFirstChild("RenderedMovingAnimals")
        local requireConveyor = _G.TrxCarpetRequireConveyor == true
        local narrowScan = _G.TrxCarpetNarrowScan == true
        local source
        if requireConveyor and narrowScan and moving then
            source = moving:GetDescendants()
        else
            source = workspace:GetDescendants()
        end
        local traitNames = {}
        pcall(function()
            local rs = game:GetService("ReplicatedStorage")
            local traits = rs:FindFirstChild("Datas") and rs.Datas:FindFirstChild("Traits")
            if traits then
                for traitName in pairs(require(traits)) do traitNames[traitName] = true end
            end
        end)
        local blacklist = { ["arcadopus"] = true, ["festive lucky block"] = true,
            ["spooky lucky block"] = true, ["leprechaun lucky block"] = true }
        for _, obj in ipairs(source) do
            if obj:IsA("Model") and not seen[obj] and not _trxCarpetInsidePlots(obj)
                and not game:GetService("Players"):GetPlayerFromCharacter(obj)
                and obj:FindFirstChildWhichIsA("Humanoid", true) then
                local found = map[_trxCarpetNorm(obj.Name)]
                if found and not _trxCarpetTPDone[obj] and not _trxIsHeadlessValue(obj.Name)
                    and not _trxIsHeadlessValue(found.index)
                    and not (type(found.info) == "table" and _trxIsHeadlessValue(found.info.DisplayName)) then
                    local display = type(found.info) == "table" and (found.info.DisplayName or found.index) or found.index
                    local displayLow = tostring(display):lower()
                    local objLow = tostring(obj.Name):lower()
                    if not blacklist[displayLow] and not blacklist[objLow]
                        and not _trxCarpetCarried(found.index, display) then
                        local onConveyor, nested = false, false
                        local ancestor = obj.Parent
                        while ancestor and ancestor ~= workspace do
                            if ancestor.Name == "RenderedMovingAnimals" then onConveyor = true; break end
                            if ancestor:IsA("Model") then
                                local aLow = ancestor.Name:lower()
                                if traitNames[ancestor.Name] or map[_trxCarpetNorm(aLow)] then nested = true; break end
                            end
                            ancestor = ancestor.Parent
                        end
                        local prompt = _trxCarpetPrompt(obj)
                        local walking = obj:GetAttribute("Walking")
                        local walkTagged = walking ~= nil and walking ~= false
                        local valid = true
                        -- Match Rose's conveyor/walking detection, but use Trx-owned flags
                        -- so this engine does not depend on Rose being loaded alongside it.
                        if nested and _G.TrxCarpetAllowNested ~= true then valid = false end
                        if traitNames[obj.Name] and not walkTagged and not prompt then valid = false end
                        if requireConveyor and not onConveyor and not walkTagged then valid = false end
                        if _G.TrxCarpetNeedPrompt == true and not prompt then valid = false end
                        local pos = _trxCarpetGetModelPos(obj)
                        if valid and pos and _G.TrxCarpetRestrictToAisle == true then
                            local centerX = tonumber(_G.TrxCarpetCenterX) or -410
                            local halfWidth = tonumber(_G.TrxCarpetHalfWidth) or 50
                            if math.abs(pos.X - centerX) > halfWidth then valid = false end
                            local bounds = _G.TrxCarpetMapBounds
                            if bounds and bounds.minZ and (pos.Z < bounds.minZ - 10 or pos.Z > bounds.maxZ + 10) then valid = false end
                        end
                        if valid and pos then
                            seen[obj] = true
                            local movingGen = type(found.info) == "table" and tonumber(found.info.Generation) or 0
                            if not movingGen or movingGen <= 0 then
                                movingGen = tonumber(_up9Mps({ Index = found.index })) or 0
                            end
                            out[#out + 1] = { model = obj, name = tostring(display), index = found.index, position = pos, prompt = prompt, mps = movingGen, genValue = movingGen }
                        end
                    end
                end
            end
        end
        _trxCarpetTargets = out
        _G.TrxCarpetSync.targets = out
        _G.TrxCarpetSync.lastScan = now
        _G.TrxCarpetSync.detected = #out
        _G.TrxCarpetSync.status = (#out > 0) and "targets detected" or "no carpet targets detected"
        return out
    end

    -- Rose.lua also reacts to newly spawned moving animals instead of relying on plot sync.
    local _trxCarpetSpawnScanPending = false
    workspace.DescendantAdded:Connect(function(obj)
        if not obj:IsA("Humanoid") or _trxCarpetSpawnScanPending then return end
        local model = obj.Parent
        if not model or not model:IsA("Model") or _trxCarpetInsidePlots(model) then return end
        _trxCarpetSpawnScanPending = true
        task.delay(0.35, function()
            _trxCarpetSpawnScanPending = false
            pcall(_trxCarpetScan, true)
        end)
    end)

    -- Manual TP requests are handled by this carpet scanner, not the normal
    -- side-TP launcher (which only equips a carpet as part of its setup).
    _G.TrxStartCarpetTPOnce = function()
        if _trxCarpetTPBusy or _G.__TrxManualCarpetTPRequested == true then return false end
        _G.__TrxManualCarpetTPRequested = true
        _G.__TrxManualTPActive = true
        _G.__TrxCancelAutoTP = true
        _G.TrxCarpetSync.status = "manual carpet TP requested"
        return true
    end

    task.spawn(function()
        while true do
            task.wait(0.25)
            local manualRequested = _G.__TrxManualCarpetTPRequested == true
            if _trxCarpetTPBusy or LP:GetAttribute("Stealing") == true
                or _G.trxStealHold == true or _G.trxTPStop == true or _G.TrxTPStop == true
                or (_G.__TrxManualTPActive == true and not manualRequested) or _G.TrxIsTeleporting == true
                or _G.trxIsTeleporting == true then
                continue
            end
            local tpBusy = false
            if type(_tpInProgress) == "function" then
                local ok, value = pcall(_tpInProgress)
                tpBusy = ok and value == true
            end
            if tpBusy then continue end

            -- Run both target sources on the same decision cycle: moving-carpet scan
            -- and the regular plot Synchronizer scan. Both are filtered to priority items.
            local targets = _trxCarpetScan(false)
            local normalPets = {}
            local normalScanOk, normalScan = pcall(scanAllPets, false)
            if normalScanOk and type(normalScan) == "table" then
                local built = type(_buildStealPetList) == "function"
                    and _buildStealPetList(normalScan, "priority") or normalScan
                for _, pet in ipairs(built) do
                    local petModel = pet and pet.model
                    local isHeadless = pet and (_trxIsGenericHeadlessValue(pet.index)
                        or _trxIsGenericHeadlessValue(pet.name) or _trxIsGenericHeadlessValue(pet.petName)
                        or (typeof(petModel) == "Instance" and _trxIsGenericHeadlessValue(petModel.Name)))
                    if pet and not isHeadless and (_priIndexOf(pet.index) ~= nil or _priIndexOf(pet.name) ~= nil
                        or _priIndexOf(pet.petName) ~= nil
                        or (typeof(pet.model) == "Instance" and _priIndexOf(pet.model.Name) ~= nil)) then
                        normalPets[#normalPets + 1] = pet
                    end
                end
            end
            -- Carpet TP is priority-only: never select a non-priority moving brainrot.
            -- Match using the same priority lookup used by the regular Trx target system.
            local priorityTargets = {}
            for _, entry in ipairs(targets) do
                local isPriority = false
                if entry then
                    if type(_priIndexOf) == "function" then
                        isPriority = _priIndexOf(entry.index) ~= nil
                            or _priIndexOf(entry.name) ~= nil
                            or (entry.model and _priIndexOf(entry.model.Name) ~= nil)
                    end
                end
                if isPriority then
                    priorityTargets[#priorityTargets + 1] = entry
                end
            end
            targets = priorityTargets
            -- Compare both sync results by priority-list order, then generation,
            -- then distance. The winning source owns this TP cycle so the two
            -- movement engines cannot launch against different targets together.
            local charForCompare = LP.Character
            local rootForCompare = charForCompare and charForCompare:FindFirstChild("HumanoidRootPart")
            local function _dualScore(item, isCarpet)
                local idx = item.index or item.name or item.petName
                local rank = tonumber(_priIndexOf(idx)) or math.huge
                local gen = tonumber(item.mps) or tonumber(item.genValue) or 0
                if gen <= 0 and item.index then
                    gen = tonumber(_up9Mps({ Index = item.index, Mutation = item.mutation, Traits = item.traits })) or 0
                end
                local pos = isCarpet and item.position or item.position
                if isCarpet and item.model then pos = _trxCarpetGetModelPos(item.model) end
                local dist = (rootForCompare and pos and (rootForCompare.Position - pos).Magnitude) or math.huge
                return rank, gen, dist
            end
            local carpetBest
            for _, item in ipairs(targets) do
                local r,g,d = _dualScore(item, true)
                if not carpetBest then carpetBest = { item=item, rank=r, gen=g, dist=d }
                elseif r < carpetBest.rank or (r == carpetBest.rank and (g > carpetBest.gen or (g == carpetBest.gen and d < carpetBest.dist))) then
                    carpetBest = { item=item, rank=r, gen=g, dist=d }
                end
            end
            local normalBest
            for _, item in ipairs(normalPets) do
                local r,g,d = _dualScore(item, false)
                if not normalBest then normalBest = { item=item, rank=r, gen=g, dist=d }
                elseif r < normalBest.rank or (r == normalBest.rank and (g > normalBest.gen or (g == normalBest.gen and d < normalBest.dist))) then
                    normalBest = { item=item, rank=r, gen=g, dist=d }
                end
            end
            local carpetWins = carpetBest ~= nil and (normalBest == nil
                or carpetBest.rank < normalBest.rank
                or (carpetBest.rank == normalBest.rank and (carpetBest.gen > normalBest.gen
                    or (carpetBest.gen == normalBest.gen and carpetBest.dist <= normalBest.dist))))
            _G.TrxDualSyncComparison = {
                carpetCount = #targets, normalCount = #normalPets,
                carpetWinner = carpetBest and (carpetBest.item.name or carpetBest.item.index) or nil,
                normalWinner = normalBest and (normalBest.item.name or normalBest.item.index or normalBest.item.petName) or nil,
                selectedSource = carpetWins and "carpet" or (normalBest and "normal" or "none"),
                updatedAt = os.clock()
            }
            _G.__TrxDualSyncPreferredSource = carpetWins and "carpet" or (normalBest and "normal" or nil)
            if not carpetWins then
                _G.TrxCarpetSync.status = normalBest and "normal sync won comparison" or "waiting: no priority targets in either sync"
                continue
            end
            if #targets == 0 then
                if manualRequested then
                    _G.__TrxManualCarpetTPRequested = false
                    _G.__TrxManualTPActive = false
                    _G.__TrxCancelAutoTP = false
                    _G.TrxCarpetSync.status = "manual carpet TP cancelled: no priority carpet brainrots detected"
                else
                    _G.TrxCarpetSync.status = "waiting: no priority carpet brainrots detected"
                end
                continue
            end
            local char = LP.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not root or not hum or hum.Health <= 0 then continue end

            -- Select the highest-generation/value moving brainrot, without priority-list filtering.
            local chosen, chosenValue, chosenDist
            chosenValue, chosenDist = -1, math.huge
            for _, entry in ipairs(targets) do
                local livePos = _trxCarpetGetModelPos(entry.model)
                if livePos then
                    entry.position = livePos
                    local value = tonumber(entry.mps) or tonumber(entry.genValue) or 0
                    if value <= 0 then
                        value = tonumber(_up9Mps({ Index = entry.index })) or 0
                        entry.mps, entry.genValue = value, value
                    end
                    local dist = (root.Position - livePos).Magnitude
                    if not chosen or value > chosenValue or (value == chosenValue and dist < chosenDist) then
                        chosen, chosenValue, chosenDist = entry, value, dist
                    end
                end
            end
            if not chosen then
                _G.TrxCarpetSync.status = "no valid moving targets"
                _G.TrxCarpetSync.lastTarget = nil
                _G.TrxCarpetSync.lastPosition = nil
                if manualRequested then
                    _G.__TrxManualCarpetTPRequested = false
                    _G.__TrxManualTPActive = false
                    _G.__TrxCancelAutoTP = false
                    _G.TrxCarpetSync.status = "manual carpet TP cancelled: no valid moving target"
                end
                continue
            end

            _G.TrxCarpetSync.status = "target selected"
            _G.TrxCarpetSync.lastTarget = tostring(chosen.name or chosen.index or (chosen.model and chosen.model.Name))
            _G.TrxCarpetSync.lastPosition = chosen.position
            -- Arrival is proximity-based, not an exact coordinate comparison.
            -- Latch this model as completed so its movement cannot trigger repeated TP.
            if chosenDist <= 6 then
                _trxCarpetTPDone[chosen.model] = true
                _trxCarpetArrival(chosen.model)
                if manualRequested then
                    _G.__TrxManualCarpetTPRequested = false
                    _G.__TrxManualTPActive = false
                    _G.__TrxCancelAutoTP = false
                end
                continue
            end

            -- One attempt per selected model. Freeze the destination snapshot now;
            -- never chase later coordinate updates from a moving brainrot.
            local frozenDestination = chosen.position
            _trxCarpetTPDone[chosen.model] = true
            _G.__TrxManualCarpetTPRequested = false
            _trxCarpetTPBusy = true
            task.spawn(function()
                local ok, err = pcall(function()
                    if not chosen.model or not chosen.model.Parent then return end
                    local destination = frozenDestination
                    if not destination then
                        _G.TrxCarpetSync.status = "target has no readable position"
                        return
                    end
                    _G.TrxCarpetSync.lastPosition = destination
                    -- Fire Grapple first, then equip the user's selected/available carpet tool.
                    local grappleCallOk, grappleResult = pcall(fireGrappleBeforeTP, destination)
                    if not grappleCallOk then
                        warn("[Trx Carpet TP] grapple error: " .. tostring(grappleResult))
                    end
                    task.wait(0.05)

                    local carpetName, carpetTool
                    local equipDeadline = os.clock() + 0.45
                    repeat
                        local okEquip, equippedName = pcall(equipCarpet)
                        if okEquip and type(equippedName) == "string" then
                            carpetName = equippedName
                            local currentChar = LP.Character
                            carpetTool = currentChar and currentChar:FindFirstChild(carpetName)
                            if carpetTool then break end
                        end
                        RunService.Heartbeat:Wait()
                    until os.clock() >= equipDeadline

                    local c = LP.Character
                    local hrp = c and c:FindFirstChild("HumanoidRootPart")
                    local h = c and c:FindFirstChildOfClass("Humanoid")
                    if not hrp or not h or h.Health <= 0 or LP:GetAttribute("Stealing") == true then return end
                    if _G.trxTPStop or _G.TrxTPStop or _G.TrxIsTeleporting or _G.trxIsTeleporting then return end
                    if not carpetTool then
                        _G.TrxCarpetSync.status = "grapple fired; no carpet tool available to equip"
                        return
                    end
                    -- Use Trx's existing path calculation + velocity movement style for the approach,
                    -- but keep this as a dedicated Carpet TP: no clone transition and no launchSideTP/doVelocityTP call.
                    local approachChar = LP.Character
                    local approachRoot = approachChar and approachChar:FindFirstChild("HumanoidRootPart")
                    local approachHum = approachChar and approachChar:FindFirstChildOfClass("Humanoid")
                    if not approachRoot or not approachHum or approachHum.Health <= 0 then return end

                    local approachStart = os.clock()
                    local nextRouteRefresh = 0
                    local routePoints = {}
                    local routeIndex = 1
                    local moveSpeed = math.clamp(tonumber(_G.TPVelocity) or 400, 200, 750)
                    _G.TrxCarpetSync.status = "Trx velocity path approach (no clone): " .. tostring(chosen.name or chosen.index)
                    while os.clock() - approachStart < 10 do
                        if not chosen.model or not chosen.model.Parent then
                            _G.TrxCarpetSync.status = "target disappeared during Trx path approach"
                            return
                        end
                        local liveChar = LP.Character
                        local liveRoot = liveChar and liveChar:FindFirstChild("HumanoidRootPart")
                        local liveHum = liveChar and liveChar:FindFirstChildOfClass("Humanoid")
                        if not liveRoot or not liveHum or liveHum.Health <= 0 then return end
                        if _G.trxTPStop or _G.TrxTPStop then
                            _G.TrxCarpetSync.status = "Carpet TP stopped"
                            return
                        end

                        local now = os.clock()
                        if now >= nextRouteRefresh then
                            nextRouteRefresh = now + 0.2
                            local liveTarget = _trxCarpetGetModelPos(chosen.model)
                            if not liveTarget then
                                _G.TrxCarpetSync.status = "target position unavailable during approach"
                                return
                            end
                            _G.TrxCarpetSync.lastPosition = liveTarget
                            if (liveRoot.Position - liveTarget).Magnitude <= 25 then break end

                            local facing = Vector3.new(liveTarget.X - liveRoot.Position.X, 0, liveTarget.Z - liveRoot.Position.Z)
                            if facing.Magnitude < 0.01 then facing = Vector3.new(0, 0, 1) else facing = facing.Unit end
                            local okRoute, calculated = pcall(computeRoute, liveRoot.Position, liveTarget + Vector3.new(0, 2, 0), facing, nil, true)
                            if okRoute and type(calculated) == "table" and #calculated > 0 then
                                routePoints = calculated
                            else
                                routePoints = { liveTarget + Vector3.new(0, 2, 0) }
                            end
                            -- Always make the newest target coordinate the final waypoint.
                            local newestEnd = liveTarget + Vector3.new(0, 2, 0)
                            if typeof(routePoints[#routePoints]) ~= "Vector3" or (routePoints[#routePoints] - newestEnd).Magnitude > 0.1 then
                                routePoints[#routePoints + 1] = newestEnd
                            end
                            routeIndex = 1
                            while routeIndex < #routePoints and typeof(routePoints[routeIndex]) == "Vector3"
                                and (routePoints[routeIndex] - liveRoot.Position).Magnitude < 4 do
                                routeIndex = routeIndex + 1
                            end
                        end

                        local waypoint = routePoints[routeIndex]
                        if typeof(waypoint) ~= "Vector3" then
                            local liveTarget = _trxCarpetGetModelPos(chosen.model)
                            if not liveTarget then return end
                            waypoint = liveTarget + Vector3.new(0, 2, 0)
                        end
                        local delta = waypoint - liveRoot.Position
                        if delta.Magnitude <= 4 and routeIndex < #routePoints then
                            routeIndex = routeIndex + 1
                        elseif delta.Magnitude > 0.1 then
                            _setFlightVel(liveRoot, delta.Unit * math.min(moveSpeed, math.max(55, delta.Magnitude * 8)))
                        else
                            _setFlightVel(liveRoot, Vector3.zero)
                        end
                        liveRoot.AssemblyAngularVelocity = Vector3.zero
                        RunService.Heartbeat:Wait()
                    end

                    local approachFinalTarget = chosen.model and chosen.model.Parent and _trxCarpetGetModelPos(chosen.model) or nil
                    local approachFinalChar = LP.Character
                    local approachFinalRoot = approachFinalChar and approachFinalChar:FindFirstChild("HumanoidRootPart")
                    if not approachFinalTarget or not approachFinalRoot then
                        _G.TrxCarpetSync.status = "target or character unavailable after Trx path approach"
                        return
                    end
                    if (approachFinalRoot.Position - approachFinalTarget).Magnitude > 25 then
                        _G.TrxCarpetSync.status = "Trx path approach timed out outside 25 studs; final snap skipped"
                        return
                    end
                    _setFlightVel(approachFinalRoot, Vector3.zero)
                    approachFinalRoot.AssemblyAngularVelocity = Vector3.zero

                    -- The final snap always uses the latest live coordinates. If the tween
                    -- has not brought the avatar within 25 studs, don't snap from far away.
                    local finalPos = chosen.model and chosen.model.Parent and _trxCarpetGetModelPos(chosen.model) or nil
                    local finalChar = LP.Character
                    local finalRoot = finalChar and finalChar:FindFirstChild("HumanoidRootPart")
                    local finalHum = finalChar and finalChar:FindFirstChildOfClass("Humanoid")
                    if not finalPos or not finalRoot or not finalHum or finalHum.Health <= 0 then
                        _G.TrxCarpetSync.status = "final snap cancelled: target or character unavailable"
                        return
                    end
                    local finalDistance = (finalRoot.Position - finalPos).Magnitude
                    if finalDistance > 25 then
                        _G.TrxCarpetSync.status = "tween finished outside 25 studs; final snap skipped"
                        return
                    end
                    _G.TrxCarpetSync.lastPosition = finalPos
                    _G.TrxCarpetSync.status = "instant snap within 25 studs"
                    finalRoot.AssemblyLinearVelocity = Vector3.zero
                    finalRoot.AssemblyAngularVelocity = Vector3.zero
                    finalRoot.CFrame = CFrame.new(finalPos + Vector3.new(0, 2, 0))
                    -- Turn Auto Buy on immediately after the close-range instant snap.
                    _trxCarpetArrival(chosen.model)
                    _G.TrxCarpetSync.status = "Trx velocity path + close-range instant TP complete; Auto Buy enabled"
                end)
                if not ok then warn("[Trx Carpet TP] " .. tostring(err)) end
                _G.__TrxManualTPActive = false
                _G.__TrxCancelAutoTP = false
                _trxCarpetTPBusy = false
            end)
        end
    end)
end

local function _getLaunchChar()
	local c = LP.Character
	if not c then return nil, nil end
	local hrp = c:FindFirstChild("HumanoidRootPart") or c.PrimaryPart
	return c, hrp
end

local function _clearStaleTeleport(maxSec)
	maxSec = tonumber(maxSec) or 25
	if not isTeleporting then
		_G.__trxTpBusySince = nil
		return
	end
	local since = _G.__trxTpBusySince or os.clock()
	_G.__trxTpBusySince = since
	if os.clock() - since >= maxSec then
		_G.Trx_Step("TP: stale clear")
		_clearTpGoState()
	end
end

local function launchSideTP(pets, winner)
	_clearStaleTeleport()
	if _tpInProgress() then return false end
	if LP:GetAttribute("Stealing") == true or _G.trxStealHold == true then return false end
	if type(pets) ~= "table" or #pets == 0 then return false end
	if false then
		local priorityPets = {}
		for _, candidate in ipairs(pets) do
			if candidate and (_priIndexOf(candidate.index) ~= nil or _priIndexOf(candidate.name) ~= nil
				or _priIndexOf(candidate.petName) ~= nil
				or (typeof(candidate.model) == "Instance" and _priIndexOf(candidate.model.Name) ~= nil)) then
				priorityPets[#priorityPets + 1] = candidate
			end
		end
		if #priorityPets == 0 then
			local fresh = scanAllPets(false)
			if type(fresh) == "table" then
				for _, candidate in ipairs(fresh) do
					if candidate and (_priIndexOf(candidate.index) ~= nil or _priIndexOf(candidate.name) ~= nil
						or _priIndexOf(candidate.petName) ~= nil
						or (typeof(candidate.model) == "Instance" and _priIndexOf(candidate.model.Name) ~= nil)) then
						priorityPets[#priorityPets + 1] = candidate
					end
				end
			end
		end
		if #priorityPets == 0 then
			_G.Trx_Step("TP blocked", "no priority brainrot available")
			return false
		end
		pets = priorityPets
		if not winner or not (_priIndexOf(winner.index) ~= nil or _priIndexOf(winner.name) ~= nil
			or _priIndexOf(winner.petName) ~= nil
			or (typeof(winner.model) == "Instance" and _priIndexOf(winner.model.Name) ~= nil)) then
			winner = select(1, pickTPWinner(pets))
		end
		if not winner then return false end
	end
	local c, hrp = _getLaunchChar()
	if not c then return false end
	_G.__trxRadarOff = true
	_G.trxFreezeUntil = os.clock() + 10
if _G.__TrxManualTPActive == true then
    _G.__trxChosenPet = winner
end
	if winner then
		if type(_G.TrxApplyStealTarget) == "function" then
			_G.TrxApplyStealTarget(winner)
		end
		if type(_G.trxArmSteal) == "function" then
			_G.trxArmSteal(winner)
		end
		_G.Trx_Step("cible choisie", tostring(winner.name) .. "  " .. tostring(winner.mps) .. "/s")
	end
	local res = doVelocityTP(false, pets)
	if res ~= true then
		if isTeleporting then _clearTpGoState() end
	end
	return res == true
end

function _autoTpOn()
	return _G.TrxAutoTP ~= false
end

local function _waitForStableAutoTarget(timeout)
	local deadline = os.clock() + (tonumber(timeout) or 3)
	local lastUid
	local stable = 0
	while os.clock() < deadline do
		if not _autoTpOn() then return nil end
		if _G.__TrxManualTPActive then return nil end
		if not _G.__trxStartupScansDone then
			RunService.Heartbeat:Wait()
			continue
		end
		local pets = scanAllPets(false)
		local winner = pickTPWinner(pets)
		local uid = winner and _petUid(winner)
		if uid and uid == lastUid then
			stable = stable + 1
		else
			lastUid = uid
			stable = uid and 1 or 0
		end
		if winner and stable >= 2 then
			return pets
		end
		for _ = 1, 2 do RunService.Heartbeat:Wait() end
	end
	return nil
end

local _manualTPBusy = false
local _manualTPRun = 0
local function runSideTPLaunch(maxWait, checkAuto)
	local _t0 = os.clock()
	local _gotOnce = false
	local _tpDelay = tonumber(_G._stp_tpDelay) or tonumber(_G.TPDelay) or 0
	local _delayed = false
	local _stablePets
	maxWait = tonumber(maxWait) or 60

	while os.clock() - _t0 < maxWait do
		if checkAuto and not _autoTpOn() then return end
		if checkAuto and _G.__TrxManualTPActive then return false end
		if not _G.__trxStartupScansDone then
			RunService.Heartbeat:Wait()
			continue
		end
		if _lastTPOk then return end
		_clearStaleTeleport()
		if checkAuto and not _stablePets then
			_stablePets = _waitForStableAutoTarget(1)
			if _G.__TrxManualTPActive then return false end
			if type(_stablePets) ~= "table" or #_stablePets == 0 then
				RunService.Heartbeat:Wait()
				continue
			end
		end
				if LP:GetAttribute("Stealing") == true or _G.trxStealHold == true then
			RunService.Heartbeat:Wait()
			continue
		end
		if not _tpInProgress() then
    if checkAuto and _G.__TrxDualSyncPreferredSource == "carpet" then
        RunService.Heartbeat:Wait()
        continue
    end
    local pets = _G.TrxStealPetList
    if type(pets) ~= "table" or #pets == 0 then
        pets = scanAllPets(false)
    end
    _stablePets = nil
    if type(pets) == "table" and #pets > 0 then
				if not _gotOnce then _G.Trx_Step("1er pet detecte", "#" .. tostring(#pets)) end
				_gotOnce = true
				local _winner, hasPriority = pickTPWinner(pets)
				local _c = LP.Character
				if _c and not _c:FindFirstChildOfClass("Humanoid") then
					_c = nil
				end
				if _c then
					local hasCarpet = false
					for _, n in ipairs(CARPET_NAMES) do
						local t = _c:FindFirstChild(n)
						if t and t:IsA("Tool") then hasCarpet = true; break end
					end
					if not hasCarpet then equipCarpet() end
				end
				if not _goBusy and not _tpInProgress() and _c and _winner then
					if _tpDelay > 0 and not _delayed and not hasPriority then
						_delayed = true
						local delayEnd = os.clock() + _tpDelay
						while os.clock() < delayEnd do
							if checkAuto and not _autoTpOn() then return end
							if checkAuto and _G.__TrxManualTPActive then return false end
							RunService.Heartbeat:Wait()
						end
						local pets2 = scanAllPets(true)
						if type(pets2) == "table" and #pets2 > 0 then
							pets = pets2
							local w2, hp2 = pickTPWinner(pets2)
							if w2 then _winner = w2; hasPriority = hp2 end
						end
					end
					if checkAuto and _G.__TrxManualTPActive then return false end
					if launchSideTP(pets, _winner) then
						return true
					end
				end
			end
		end
		RunService.Heartbeat:Wait()
	end
	return false
end

local _autoTpRunning = false
function ensureAutoTpLoop()
	_G.trxAutoTP = (_G.TrxAutoTP ~= false)
	if not _autoTpOn() then return end
	if _lastTPOk then return end
	if _autoTpRunning then return end
	_autoTpRunning = true
	task.spawn(function()
		local ok, err = pcall(function()
						while _autoTpOn() do
			if _lastTPOk then break end
			if _G.__TrxManualTPActive then
				RunService.Heartbeat:Wait()
			elseif LP:GetAttribute("Stealing") == true or _G.trxStealHold == true then
				RunService.Heartbeat:Wait()
			elseif not _tpInProgress() then
				runSideTPLaunch(60, true)
			else
				_clearStaleTeleport(25)
			end
			if _lastTPOk then break end
			if not _autoTpOn() then break end
			RunService.Heartbeat:Wait()
			end
		end)
		_autoTpRunning = false
		if not ok then warn("Trx auto TP loop failed: " .. tostring(err)) end
	end)
end
_G.TrxEnsureAutoTP = ensureAutoTpLoop

local function manualFullTP()
	if _manualTPBusy or isTeleporting or _goBusy then
		_G.trxTPStop = true
		_G.TrxTPStop = true
		RunService.Heartbeat:Wait()
		local activeRoot = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
		if activeRoot then vZero(activeRoot) end
		_clearTpGoState()
		_manualTPBusy = false
		_G.__TrxManualTPActive = false
		_G.__TrxCancelAutoTP = false
	end
	_manualTPBusy = true
	_manualTPRun = _manualTPRun + 1
	local thisRun = _manualTPRun
	_G.__TrxManualTPActive = true
	_G.__TrxCancelAutoTP = true
	_G.__trxChosenPet = nil
	_G.__trxRadarOff = true
	task.delay(70, function()
		if _manualTPBusy and _manualTPRun == thisRun then
			_clearTpGoState()
			_manualTPBusy = false
			_G.__TrxManualTPActive = false
			_G.__TrxCancelAutoTP = false
			_G.__trxRadarOff = false
		end
	end)
	_G.trxTPStop = false
	_G.TrxTPStop = false
	_G.__trxRadarOff = false
	_lastTPOk = false
	local ok, err = pcall(runSideTPLaunch, 60, false)
	_G.__TrxManualTPActive = false
	_G.__TrxCancelAutoTP = false
	_G.__trxRadarOff = false
	_G.trxTPStop = false
	_G.TrxTPStop = false
	_manualTPBusy = false
	if not ok then warn("Trx manual TP failed: " .. tostring(err)) end
end
_G.trxStartSideTP = manualFullTP

UIS.InputBegan:Connect(function(input, gameProcessed)
	if gameProcessed then return end
	if _G.TrxCapturingKey then return end
	if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
	local want = _G._stp_tpKeyName
	if type(want) ~= "string" or want == "" then want = "T" end
	if input.KeyCode.Name == want then
		task.spawn(function()
			if type(_G.trxStartSideTP) == "function" then
