task.spawn(function()
    local _fpCache = {}
    while true do
        local plots = Workspace:FindFirstChild("Plots")
        if plots then
            local now = tick()
            for _, plot in ipairs(plots:GetChildren()) do
                local pn = plot.Name
                local c = _fpCache[pn]
                if (not c) or c.plotRef ~= plot or (now - c.t) > 8 then
                    local ok, cf, sz = pcall(function() return plot:GetBoundingBox() end)
                    if ok and cf and sz then
                        local hx, hz = sz.X * 0.5, sz.Z * 0.5
                        if hx < 70 and hz < 70 then
                            _fpCache[pn] = {
                                plotRef = plot, t = now,
                                fp = {
                                    plot = pn,
                                    minX = cf.Position.X - hx, maxX = cf.Position.X + hx,
                                    minZ = cf.Position.Z - hz, maxZ = cf.Position.Z + hz,
                                    minY = cf.Position.Y - 4, maxY = cf.Position.Y + 16,
                                },
                            }
                        else
                            _fpCache[pn] = nil
                        end
                    else
                        _fpCache[pn] = nil
                    end
                    RunService.Heartbeat:Wait()
                end
            end
            for pn, c in pairs(_fpCache) do
                if not (c.plotRef and c.plotRef.Parent) then _fpCache[pn] = nil end
            end
            local fps = {}
            for _, c in pairs(_fpCache) do if c.fp then fps[#fps + 1] = c.fp end end
            _G.Trx_BaseFootprints = fps
        end
        task.wait(1)
    end
end)
