    local syncPairs = {
        {"TrxAutoTP", "TrxAutoTP"},
        {"TrxStealMode", "TrxStealMode"},
        {"TrxStealTarget", "TrxStealTarget"},
        {"TrxStealTargetUID", "TrxStealTargetUID"},
