    local last = {}
    for _, p in ipairs(syncPairs) do
        last[p[1]] = _G[p[1]]
        last[p[2]] = _G[p[2]]
    end
    task.spawn(function()
        while task.wait(0.25) do
            for _, p in ipairs(syncPairs) do
                local a, b = p[1], p[2]
                local av, bv = _G[a], _G[b]
                local aChanged = av ~= last[a]
                local bChanged = bv ~= last[b]
                if aChanged and not bChanged then
                    _G[b] = av
                elseif bChanged and not aChanged then
                    _G[a] = bv
                elseif aChanged and bChanged and av ~= bv then
                    _G[a] = bv
                end
                last[a], last[b] = _G[a], _G[b]
            end
        end
    end)
end

