		RefreshMobileActionButtons = nil,
	}

	_runSyncScannerTick = function(force)
		ensureSyncData()
		local scanned = scanAllPets(true)
		if type(scanned) ~= "table" then return end
		local anyMps = false
		for _, p in ipairs(scanned) do
			if type(_G.TrxEnsurePetGen) == "function" then
				_G.TrxEnsurePetGen(p)
			end
			if (tonumber(p.mps) or 0) > 0 then anyMps = true end
		end
		local datasReady = (_G.__trxDatasReady == true)
			or (type(_G.TrxGenReady) == "function" and _G.TrxGenReady())
			or (type(AnimalsData) == "table")
		if #scanned > 0 and (anyMps or datasReady) then
			_G.__trxEarlyReady = true
			_G.__trxEarlyFrames = (_G.__trxEarlyFrames or 0) + 1
		end
		local list = _buildStealPetList(scanned, _G.TrxStealMode)
		for _, p in ipairs(list) do
			if type(_G.TrxEnsurePetGen) == "function" then
				_G.TrxEnsurePetGen(p)
			end
		end
		local sig = _stealListSig(list)
		local forceRefresh = force == true or _G.__trxForceListRefresh == true
		if forceRefresh then _G.__trxForceListRefresh = false end
		if forceRefresh or sig ~= _stealListSig(_G.TrxStealPetList) then
			_G.TrxStealPetList = list
			P.AllAnimalsCache = list
			if type(_G.TrxOnStealList) == "function" then
				_G.TrxOnStealList(list)
			end
		end
	end
	_G.TrxRunSyncScanner = _runSyncScannerTick
	_G.TrxForceResortList = function()
		local scanned = scanAllPets(true)
		if type(scanned) ~= "table" then return end
		local list = _buildStealPetList(scanned, _G.TrxStealMode)
		_G.TrxStealPetList = list
		P.AllAnimalsCache = list
		if type(_G.TrxOnStealList) == "function" then
			_G.TrxOnStealList(list)
		end
	end

	local _scanTickLast = 0
	RunService.Heartbeat:Connect(function()
		local now = os.clock()
		if now - _scanTickLast < (tonumber(_G.TrxScanInterval) or 0.1) then return end
		_scanTickLast = now
		_runSyncScannerTick()
	end)

	local function _normalizeStealPet(pet)
		if type(pet) ~= "table" then
			return nil
		end
		if pet.plot ~= nil then
			pet.plot = tostring(pet.plot)
		end
		if pet.slot ~= nil then
			pet.slot = tostring(pet.slot)
		end
		if pet.plot and pet.slot then
			pet.uid = tostring(pet.plot) .. "_" .. tostring(pet.slot)
		end
		return pet
	end

	local _intendedStealPet = function(pets)
		pets = pets or _G.TrxStealPetList
		if type(pets) ~= "table" then
			pets = {}
		end
		local man = _G.TrxManualStealUID
		if type(man) == "string" and man ~= "" then
			local pet = _findPetByUid(pets, man)
			if pet and _petAllowed(pet) then
				return _normalizeStealPet(pet)
			end
			return nil
		end
		local mode = tostring(_G.TrxStealMode or "priority"):lower()
		if mode == "highest" then
			mode = "value"
		end
		local picked = _pickPetByMode(pets, mode)
		if picked and _petAllowed(picked) then
			return _normalizeStealPet(picked)
		end
		return nil
	end

	local function _applyStealTarget(pet)
		pet = _normalizeStealPet(pet)
		if not pet then
			return nil
		end
		if pet.plot and pet.slot then
			pet.uid = tostring(pet.plot) .. "_" .. tostring(pet.slot)
		elseif not pet.uid then
			pet.uid = _petUid(pet)
		end
		_G.TrxStealTarget = pet
		_G.TrxSelectedPetData = pet
		P.SelectedPetData = pet
		if pet.uid then
			_G.TrxStealTargetUID = pet.uid
		end
		return pet
	end
	_G.TrxApplyStealTarget = _applyStealTarget

	local function _forceSetPriorityTarget(pets)
		local best = _intendedStealPet(pets)
		if not best then
			_priDbg("noPriPet", "No steal-list pet found")
			return nil
		end
		best = _applyStealTarget(best)
		if best and _G.__TrxPriTargetUid ~= best.uid then
			_G.__TrxPriTargetUid = best.uid
			print("[DEBUG] Steal target SET to:", best.uid, best.name)
			print("[DEBUG] TrxStealTargetUID:", _G.TrxStealTargetUID)
		end
		return best
	end

	local function _selectPriorityTarget(pets)
		return _forceSetPriorityTarget(pets)
	end

	local function _readLoadedStealList()
		local list = _G.TrxStealPetList
		if type(list) == "table" and #list > 0 then
			local pet = _intendedStealPet(list)
			if _stealPetReady(pet) then
				return list, pet
			end
		end
		local scanned = scanAllPets(true)
		if type(scanned) ~= "table" then
			return list, nil
		end
		list = _buildStealPetList(scanned, _G.TrxStealMode)
		_G.TrxStealPetList = list
		P.AllAnimalsCache = list
		return list, _intendedStealPet(list)
	end

	local function _waitStealTargetReady(timeout)
		timeout = tonumber(timeout) or 45
		local t0 = os.clock()
		local lastPet, lastPets
		while os.clock() - t0 < timeout do
			if _G.TrxTPStop or _G.__TrxCancelAutoTP then
				return nil
			end
			local list, pet = _readLoadedStealList()
			if type(_G.TrxOnStealList) == "function" then
				_G.TrxOnStealList(list or _G.TrxStealPetList)
			end
			if _stealPetReady(pet) then
				return _applyStealTarget(pet), list
			end
			lastPet, lastPets = pet, list
			RunService.Heartbeat:Wait()
		end
		if _stealPetReady(lastPet) then
			return _applyStealTarget(lastPet), lastPets
		end
		return nil, lastPets or _G.TrxStealPetList
	end

	local _syncStealFlags = function()
		local auto = _G.TrxAutoSteal == true
		local mode = tostring(_G.TrxStealMode or "priority"):lower()
		if mode == "highest" then
			mode = "value"
		end
		_G.NEAREST_INSTANT_MODE = auto and mode == "nearest"
		local pet = _intendedStealPet(_G.TrxStealPetList)
		if pet then
			_applyStealTarget(pet)
		end
		if auto then
			if pet then
				P.SelectedPetData = pet
			elseif type(_G.TrxManualStealUID) ~= "string" or _G.TrxManualStealUID == "" then
				P.SelectedPetData = nil
			end
		else
			P.SelectedPetData = nil
			_G.NEAREST_INSTANT_MODE = false
		end
	end
	_G.TrxSyncNearestInstant = _syncStealFlags
	_G.TrxSetAutoStealRuntime = function(enabled)
		_G.TrxAutoSteal = enabled == true
		_G.MynxxStealMode = (_G.TrxStealMode == "nearest") and "nearest" or "priority"
		if enabled then _G._stealUserOff = false end
		_syncStealFlags()
	end
	_G.TrxPublishStealTarget = function(pet)
		if type(pet) ~= "table" then
			_G.MynxxStealTargetUID = nil
			_G.MynxxStealTarget = nil
			return
		end
		local uid = pet.uid or pet.id or pet.UID
		if type(uid) ~= "string" and type(_petUid) == "function" then
			pcall(function() uid = _petUid(pet) end)
		end
		_G.MynxxStealTargetUID = uid
		_G.MynxxStealTarget = pet
		_G.TrxStealTarget = pet
		_G.TrxSelectedPetData = pet
		if type(uid) == "string" and uid ~= "" then
			_G.TrxManualStealUID = uid
		end
	end
	_syncStealFlags()
	_G.TrxAfterCoreLoad(function()
