do
	local Lighting = game:GetService("Lighting")
	local Workspace = game:GetService("Workspace")
	local MaterialService = game:GetService("MaterialService")
	local on = false
	local restoreFns, hooks = {}, {}
	local CanBeEnabled = { ParticleEmitter = true, Trail = true, Smoke = true, Fire = true, Sparkles = true }

	local function partOfOtherChar(inst)
		for _, plr in ipairs(Players:GetPlayers()) do
			if plr ~= LP and plr.Character and inst:IsDescendantOf(plr.Character) then
				return true
			end
		end
		return false
	end

	local function checkIfBad(inst)
		if not inst then return end
		if inst:IsDescendantOf(Players) then return end
		if inst:IsA("ScreenGui") or inst:FindFirstAncestorOfClass("ScreenGui") then return end
		if inst:IsA("ProximityPrompt") or inst:FindFirstAncestorOfClass("ProximityPrompt") then return end
		if LP.Character and inst:IsDescendantOf(LP.Character) then return end
		if partOfOtherChar(inst) then return end
		if inst:IsA("BackpackItem") or inst:FindFirstAncestorWhichIsA("BackpackItem") then return end

		do
			if inst:IsA("DataModelMesh") then
				if inst:IsA("SpecialMesh") then
					inst.TextureId = inst.TextureId
				end
			elseif inst:IsA("FaceInstance") then
				inst.Transparency = 1
				inst.Shiny = 1
			elseif inst:IsA("ShirtGraphic") then
				inst.Graphic = ""
			elseif CanBeEnabled[inst.ClassName] then
				inst.Enabled = false
			elseif inst:IsA("PostEffect") then
				inst.Enabled = false
			elseif inst:IsA("Explosion") then
				inst.BlastPressure = 1
				inst.BlastRadius = 1
			elseif inst:IsA("Clothing") or inst:IsA("SurfaceAppearance") or inst:IsA("BaseWrap") then
				inst:Destroy()
			elseif inst:IsA("BasePart") and not inst:IsA("MeshPart") then
				inst.Material = Enum.Material.Plastic
				inst.Reflectance = 0
			elseif inst:IsA("TextLabel") and inst:IsDescendantOf(Workspace) then
				return
			elseif inst:IsA("Model") then
				inst.LevelOfDetail = Enum.ModelLevelOfDetail.StreamingMesh
			elseif inst:IsA("MeshPart") then

				inst.Reflectance = 0
				inst.Material = Enum.Material.Plastic
			end
		end
	end

	local function applyNow()
		do
			if setfpscap then setfpscap(1e6) end
		end
		do
			local terrain = Workspace:FindFirstChildOfClass("Terrain")
			if terrain then
				terrain.WaterWaveSize = 0
				terrain.WaterWaveSpeed = 0
				terrain.WaterReflectance = 0
				terrain.WaterTransparency = 0
				if sethiddenproperty then
					sethiddenproperty(terrain, "Decoration", false)
				else
					terrain.Decoration = false
				end
			end
		end
		do
			Lighting.GlobalShadows = false
			Lighting.FogEnd = 9e9
			Lighting.ShadowSoftness = 0
			if sethiddenproperty then
				sethiddenproperty(Lighting, "Technology", 2)
			else
				Lighting.Technology = Enum.Technology.Compatibility
			end
			for _, o in ipairs(Lighting:GetDescendants()) do
				if o:IsA("PostEffect") then o.Enabled = false end
			end
		end
		do
			local ok, s = true, settings()
			if ok and s then
				s.Rendering.QualityLevel = 1
				s.Rendering.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level04
			end
		end
		do
			for _, v in ipairs(MaterialService:GetChildren()) do
				v:Destroy()
			end
			MaterialService.Use2022Materials = false
		end

		if _G.TrxFpsDeepSweep == true then
			do
				task.spawn(function()
					local desc = game:GetDescendants()
					for i = 1, #desc do
						checkIfBad(desc[i])
						if i % 300 == 0 then task.wait() end
					end
				end)
			end
		end
	end

	local function stopFps()
		if not on then return end
		on = false
		_G.__TrxFpsBoostActive = false
		for _, c in ipairs(hooks) do
			pcall(function() c:Disconnect() end)
		end
		table.clear(hooks)
		for i = #restoreFns, 1, -1 do restoreFns[i]() end
		table.clear(restoreFns)
	end

	local function startFps()
		if on then
			applyNow()
			return
		end
		on = true
		_G.__TrxFpsBoostActive = true
		do
			local ok, s = true, settings()
			if ok and s then
				local prevQ, prevM = s.Rendering.QualityLevel, s.Rendering.MeshPartDetailLevel
				restoreFns[#restoreFns + 1] = function()
					s.Rendering.QualityLevel = prevQ
					s.Rendering.MeshPartDetailLevel = prevM
				end
			end
		end
		do
			local snap = {
				GlobalShadows = Lighting.GlobalShadows,
				FogEnd = Lighting.FogEnd,
				ShadowSoftness = Lighting.ShadowSoftness,
			}
			restoreFns[#restoreFns + 1] = function()
				for k, v in pairs(snap) do Lighting[k] = v end
			end
		end
		applyNow()
		hooks[#hooks + 1] = game.DescendantAdded:Connect(function(v)
			task.delay(0.35, function()
				if on then checkIfBad(v) end
			end)
		end)
	end

	_G.TrxApplyFpsBooster = applyNow
	_G.TrxSetFpsBooster = function(v)
		_G.TrxFpsBooster = v and true or false
		if v then
			if _G.__trxAllowFpsBoost == true then
				startFps()
			end
		else
			stopFps()
		end
	end
	_trxAfter(2, function()
		_G.__trxAllowFpsBoost = true
		if _G.TrxFpsBooster == true then
			startFps()
		end
	end)
end
do
	local GuiService = game:GetService("GuiService")
	local CoreGui = game:GetService("CoreGui")
	local on = false
	local conns = {}
	local lastClose = 0
	local FULL_NEEDLES = {
		"full", "this experience is full", "this game is full",
		"the experience is full", "the game is full", "server is full",
		"servers are full", "unable to join", "couldn't join", "could not join",
	}

	local function disc()
		for _, c in ipairs(conns) do
			if typeof(c) == "RBXScriptConnection" then pcall(function() c:Disconnect() end) end
		end
		conns = {}
	end

	local function isFullError(text)
		if type(text) ~= "string" or text == "" then return false end
		local lower = string.lower(text)
		for i = 1, #FULL_NEEDLES do
			if string.find(lower, FULL_NEEDLES[i], 1, true) then return true end
		end
		return false
	end

	local function clickPromptButtons(root)
		do
			for _, d in ipairs(root:GetDescendants()) do
				if d:IsA("TextButton") or d:IsA("ImageButton") then
					do
						if firesignal then
							firesignal(d.MouseButton1Click)
							firesignal(d.Activated)
						end
					end
					d.MouseButton1Click:Fire()
					d.Activated:Fire()
				end
			end
		end
	end

	local function overlayLooksFull(overlay)
		if not overlay then return false end
		local blob = ""
		do
			for _, d in ipairs(overlay:GetDescendants()) do
				if d:IsA("TextLabel") or d:IsA("TextButton") then
					blob = blob .. " " .. (d.Text or "")
				end
			end
		end
		return isFullError(blob)
	end

	local function closeFullError()
		local now = os.clock()
		if now - lastClose < 0.15 then return end
		local msg = ""
		msg = GuiService:GetErrorMessage() or ""
		local promptGui = CoreGui:FindFirstChild("RobloxPromptGui")
		local overlay = promptGui and promptGui:FindFirstChild("promptOverlay")
		local overlayFull = overlayLooksFull(overlay)
		if not isFullError(msg) and not overlayFull then return end
		lastClose = now
		GuiService:ClearError()
		if overlay then clickPromptButtons(overlay) end
	end

	local function enable()
		if on then return end
		on = true
		disc()
		conns[#conns + 1] = GuiService.ErrorMessageChanged:Connect(function()
			task.defer(closeFullError)
		end)
		task.spawn(function()
			local promptGui = CoreGui:FindFirstChild("RobloxPromptGui")
				or CoreGui:WaitForChild("RobloxPromptGui", 60)
			if not promptGui then return end
			local overlay = promptGui:FindFirstChild("promptOverlay")
				or promptGui:WaitForChild("promptOverlay", 15)
			if not overlay then return end
			conns[#conns + 1] = overlay.ChildAdded:Connect(function()
				task.wait(0.05)
				closeFullError()
			end)
			conns[#conns + 1] = overlay.DescendantAdded:Connect(function(d)
				if d:IsA("TextLabel") or d:IsA("TextButton") then
					task.wait(0.05)
					closeFullError()
				end
			end)
		end)
		conns[#conns + 1] = LP.OnTeleport:Connect(function(state)
			if state == Enum.TeleportState.Failed then
				task.defer(closeFullError)
			end
		end)
		task.defer(closeFullError)
		print("[error fix] watching for server-full errors")
	end

	local function disable()
		on = false
		disc()
	end

	_G.TrxSetErrorFix = function(v)
		if v then enable() else disable() end
	end
end

	do
		local Lighting = game:GetService("Lighting")
		local conns = {}
		local on = false
		local function disc()
			for _, c in ipairs(conns) do
				if typeof(c) == "RBXScriptConnection" then pcall(function() c:Disconnect() end) end
			end
			conns = {}
		end
		local function protected(obj)
			if not obj then return true end
			if obj:IsA("ScreenGui") or obj:FindFirstAncestorOfClass("ScreenGui") then return true end
			if obj:FindFirstAncestor("AnimalPodiums") then return true end
			local m = obj:FindFirstAncestorOfClass("Model")
			if m and Players:GetPlayerFromCharacter(m) then return true end
			if obj:IsA("Tool") or obj:FindFirstAncestorOfClass("Tool") then return true end
			if obj:IsA("ProximityPrompt") then return true end
			return false
		end
		local function strip(obj)
			if protected(obj) then return end
			if obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
					or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
					obj.Enabled = false
				elseif obj:IsA("BloomEffect") or obj:IsA("BlurEffect") or obj:IsA("SunRaysEffect")
					or obj:IsA("DepthOfFieldEffect") or obj:IsA("ColorCorrectionEffect") then
					obj.Enabled = false
				elseif obj:IsA("Atmosphere") or obj:IsA("Clouds") then
					obj:Destroy()
				elseif obj:IsA("Texture") or obj:IsA("Decal") then
					if not (obj.Name == "face" and obj.Parent and obj.Parent.Name == "Head") then
						obj:Destroy()
					end
				elseif obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
					obj.Enabled = false
				elseif obj:IsA("BasePart") then
					obj.CastShadow = false
					obj.Material = Enum.Material.Plastic
					obj.Reflectance = 0
				end
		end
		local function lightingOn()
			do
				Lighting.GlobalShadows = false
				Lighting.FogEnd = 9e9
				Lighting.FogStart = 9e9
				Lighting.EnvironmentDiffuseScale = 0
				Lighting.EnvironmentSpecularScale = 0
				Lighting.Brightness = 1.5
				Lighting.Ambient = Color3.fromRGB(70, 70, 70)
				for _, v in ipairs(Lighting:GetChildren()) do
					if v:IsA("PostEffect") then v.Enabled = false
					elseif v:IsA("Atmosphere") or v:IsA("Clouds") then v:Destroy() end
				end
	end
			do
				settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
			end
			pcall(setfpscap, 999)
		end
		local function lightingOff()
			Lighting.GlobalShadows = true
				Lighting.FogEnd = 100000
				Lighting.EnvironmentDiffuseScale = 1
				Lighting.EnvironmentSpecularScale = 1
			settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic
		end
		local function enable()
			if on then return end
			on = true
			disc()
			lightingOn()
			task.spawn(function()
				local desc = workspace:GetDescendants()
				for i, obj in ipairs(desc) do
					if not on then return end
					strip(obj)
					if i % 80 == 0 then task.wait() end
				end
			end)
			conns[#conns + 1] = workspace.DescendantAdded:Connect(function(obj)
				if on then strip(obj) end
			end)
			conns[#conns + 1] = Lighting.DescendantAdded:Connect(function(obj)
				if not on then return end
				if obj:IsA("PostEffect") then obj.Enabled = false
				elseif obj:IsA("Atmosphere") or obj:IsA("Clouds") then obj:Destroy() end
			end)
		end
		local function disable()
			on = false
			disc()
			lightingOff()
		end
		_G.TrxSetSuperOptimizer = function(v)
			if v then enable() else disable() end
		end
	end

	do
		local fired = false
		local watchConns = {}
		local function parsePSInput(input)
			if type(input) ~= "string" then return nil end
			input = input:gsub("%s+", "")
			if input == "" then return nil end
			local placeId = tonumber(input:match("/games/(%d+)"))
			local code = input:match("[?&]privateServerLinkCode=([%w%-_]+)")
				or input:match("[?&]linkCode=([%w%-_]+)")
			if code then return code, placeId, false end
			if input:match("[?&]code=([%w%-_]+)") then return nil, placeId, true end
			if input:match("^[%w%-_]+$") then
				local looksShare = (#input == 32) and (input:match("^[0-9a-fA-F]+$") ~= nil)
				if looksShare then return nil, placeId, true end
				return input, placeId, false
			end
			return nil
		end
		local function kickToPs()
			local code, placeId, shareWarn = parsePSInput(tostring(_G.TrxPSCode or ""))
			if shareWarn or not code then return false end
			placeId = placeId or game.PlaceId
			local ok = pcall(function()
				game:GetService("ExperienceService"):LaunchExperience({ placeId = placeId, linkCode = code })
			end)
			if ok then return true end
			local teleported = pcall(function()
				game:GetService("TeleportService"):TeleportToPrivateServer(placeId, code, { LP })
			end)
			return teleported
		end
		local function doKick(fromSteal)
			if fromSteal and _G.TrxKickToPS ~= false then
				local ok, moved = pcall(kickToPs)
				if ok and moved then return end
			end
			pcall(function() LP:Kick("") end)
			pcall(function() game:Shutdown() end)
		end
		local function stopWatch()
			for _, c in ipairs(watchConns) do
				if typeof(c) == "RBXScriptConnection" then pcall(function() c:Disconnect() end) end
			end
			watchConns = {}
		end
		local _lastStealConfirmAt = 0
		local _watchStarted = false
		local function checkText(t)
			local lowerText = string.lower(tostring(t or ""))
			if not string.find(lowerText, "you stole", 1, true) then return end
			local now = os.clock()
			if now - _lastStealConfirmAt > 1 then
				_lastStealConfirmAt = now
				if type(_G.TrxOnStealConfirmed) == "function" then
					task.defer(function()
						pcall(_G.TrxOnStealConfirmed, tostring(t or ""))
					end)
				end
			end
			if _G.TrxAutoKick == true and not fired then
				fired = true
				doKick(true)
			end
		end
		local function hookObj(obj)
			if not (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then return end
			checkText(obj.Text)
			watchConns[#watchConns + 1] = obj:GetPropertyChangedSignal("Text"):Connect(function()
				checkText(obj.Text)
			end)
		end
		local function watchRoot(root)
			if not root then return end
			for _, obj in ipairs(root:GetDescendants()) do hookObj(obj) end
			watchConns[#watchConns + 1] = root.DescendantAdded:Connect(hookObj)
		end
		local function startWatch()
			stopWatch()
			fired = false
			local pg = LP:FindFirstChild("PlayerGui")
			if not pg then return end
			for _, g in ipairs(pg:GetChildren()) do watchRoot(g) end
			watchConns[#watchConns + 1] = pg.ChildAdded:Connect(watchRoot)
		end
		_G.TrxDoKick = function(fromSteal)
			fired = false
			doKick(fromSteal == true)
		end
		_G.TrxSetAutoKick = function(on)
			if not _watchStarted then
				pcall(startWatch)
				_watchStarted = #watchConns > 0
			end
		end
		_G.TrxAfterTpLoad(function()
			for _ = 1, 20 do
				if _watchStarted then break end
				pcall(startWatch)
				_watchStarted = #watchConns > 0
				if not _watchStarted then task.wait(0.5) end
			end
		end)
	end

			do
		local active, conns = false, {}
		local realHRP, cloneHRP, track, hip, origT
		local stuck, restarting = false, false
		local start, stop
		local _invisToggleCooldown = 0

		local function depth()
			local v = tonumber(_G.SinkSliderValue) or tonumber(_G.TrxInvisDepth) or 7
			if v > 10 then v = v * 0.5 end
			return 0.01 + (math.clamp(v, 0, 10) / 10) * 0.50
		end
		local function angle()
			return math.clamp(tonumber(_G.InvisStealAngle) or tonumber(_G.TrxInvisAngle) or 180, 0, 360)
		end
		local function add(c) conns[#conns + 1] = c end
		local function rewire(char, from, to)
			for _, v in ipairs(char:GetDescendants()) do
				if v:IsA("Weld") or v:IsA("Motor6D") then
					if v.Part0 == from then v.Part0 = to end
					if v.Part1 == from then v.Part1 = to end
				end
			end
		end

		local invisOrb = nil
		local invisOrbConn = nil
		local function destroyInvisOrb()
			if invisOrbConn then
				pcall(function() invisOrbConn:Disconnect() end)
				invisOrbConn = nil
			end
			if invisOrb then
				pcall(function() invisOrb:Destroy() end)
				invisOrb = nil
			end
			local old = workspace:FindFirstChild("TrxInvisOrb")
			if old then pcall(function() old:Destroy() end) end
		end
		local function ensureInvisOrb()
			if invisOrb and invisOrb.Parent then return invisOrb end
			destroyInvisOrb()
			local p = Instance.new("Part")
			p.Name = "TrxInvisOrb"
			p.Shape = Enum.PartType.Ball
			p.Size = Vector3.new(1.35, 1.35, 1.35)
			p.Material = Enum.Material.Neon
			p.Color = Color3.fromRGB(170, 120, 255)
			p.Transparency = 0.15
			p.Anchored = true
			p.CanCollide = false
			p.CanTouch = false
			p.CanQuery = false
			p.CastShadow = false
			p.Parent = workspace
			invisOrb = p
			invisOrbConn = RunService.Heartbeat:Connect(function()
				if not active then return end
				local char = LP.Character
				local base = char and (char.PrimaryPart or char:FindFirstChild("HumanoidRootPart"))
				if not (base and invisOrb and invisOrb.Parent) then return end
				local pos = base.Position - Vector3.new(0, (base.Size.Y * 0.5) + 1.05, 0)
				invisOrb.CFrame = CFrame.new(pos)
			end)
			return p
		end
		local function setEnabled(on)
			active = on and true or false
			_G.invisibleStealEnabled = active
			_G.TrxInvisActive = active
			if active then
				ensureInvisOrb()
			else
				destroyInvisOrb()
			end
			if type(_G.TrxPaintInvisToggles) == "function" then
				pcall(_G.TrxPaintInvisToggles)
			end
		end

		stop = function()
			stuck = false
			for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
			conns = {}
			if origT then
				for p, v in pairs(origT) do
					if p and p.Parent then pcall(function() p.LocalTransparencyModifier = v end) end
				end
				origT = nil
			end
			if track then
				pcall(function() track:AdjustSpeed(1) track:Stop(0) track:Destroy() end)
				track = nil
			end
			local char = LP.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if realHRP and realHRP:IsDescendantOf(game) and hum then
				local tmp = Instance.new("Model")
				tmp.Parent = game
				char.Parent = tmp
				realHRP.Parent = char
				char.PrimaryPart = realHRP
				char.Parent = workspace
				realHRP.CanCollide = true
				rewire(char, cloneHRP, realHRP)
				if cloneHRP then
					local at = cloneHRP.CFrame
					cloneHRP:Destroy()
					cloneHRP = nil
					realHRP.CFrame = at
				end
				hum.HipHeight = hip or 0
				tmp:Destroy()
			end
			realHRP, cloneHRP = nil, nil
			setEnabled(false)
		end

		local function animTrick(char, hum)
			if not (char and hum and hum.Health > 0) then return end
			local a = Instance.new("Animation")
			a.AnimationId = "http://www.roblox.com/asset/?id=18537363391"
			local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
			track = animator:LoadAnimation(a)
			track.Priority = Enum.AnimationPriority.Action4
			track.Looped = true
			track:Play(0, 1, 0)
			a:Destroy()
			add(track.Stopped:Connect(function()
				if active then animTrick(char, hum) end
			end))
			task.defer(function()
				if not track then return end
				track.TimePosition = 0.7
				task.delay(0.1, function() if track then track:AdjustSpeed(math.huge) end end)
			end)
		end

		start = function()
			local char = LP.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if not hum or active then return false end

			local folder = workspace:FindFirstChild(LP.Name)
			if folder then
				for _, n in ipairs({ "DoubleRig", "Constraints" }) do
					local x = folder:FindFirstChild(n)
					if x then x:Destroy() end
				end
				add(folder.ChildAdded:Connect(function(c)
					if c.Name == "DoubleRig" or c.Name == "Constraints" then c:Destroy() end
				end))
			end
			for _, s in ipairs({ "Dead", "FallingDown", "Ragdoll" }) do
				hum:SetStateEnabled(Enum.HumanoidStateType[s], false)
			end

			hip = hum.HipHeight
			realHRP = char:FindFirstChild("HumanoidRootPart")
			if not (realHRP and realHRP.Parent) then return false end

			local tmp = Instance.new("Model")
			tmp.Parent = game
			char.Parent = tmp
			cloneHRP = realHRP:Clone()
			cloneHRP.Parent = char
			realHRP.Parent = workspace.CurrentCamera
			cloneHRP.CFrame = realHRP.CFrame
			char.PrimaryPart = cloneHRP
			char.Parent = workspace
			rewire(char, realHRP, cloneHRP)
			tmp:Destroy()

			setEnabled(true)
			animTrick(char, hum)

			origT = {}
			for _, p in ipairs(char:GetDescendants()) do
				if p:IsA("BasePart") then
					origT[p] = p.LocalTransparencyModifier
					p.LocalTransparencyModifier = 1
				end
			end
			add(char.DescendantAdded:Connect(function(d)
				if not (active and d:IsA("BasePart")) then return end
				if origT and origT[d] == nil then origT[d] = d.LocalTransparencyModifier end
				pcall(function() d.LocalTransparencyModifier = 1 end)
			end))

			add(RunService.Heartbeat:Connect(function()
				if not active or not hum.Parent then return end
				hum.Health = hum.MaxHealth
				hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
				local st = hum:GetState()
				if st == Enum.HumanoidStateType.Dead or st == Enum.HumanoidStateType.FallingDown
					or st == Enum.HumanoidStateType.Ragdoll then
					hum:ChangeState(Enum.HumanoidStateType.Running)
				end
			end))

			local lastTarget, grace = nil, 60
			add(RunService.PreSimulation:Connect(function()
				if not (active and realHRP and hum.Health > 0) then return end
				local base = char.PrimaryPart or char:FindFirstChild("HumanoidRootPart")
				if not base then return end
				if grace > 0 then
					grace = grace - 1
				elseif not stuck and lastTarget
					and (realHRP.Position - lastTarget).Magnitude > 2.25 then
					stuck = true
					if not restarting then
						task.spawn(function()
							restarting = true
							stop()
							task.wait(0.5)
							restarting = false
							start()
						end)
					end
				end
				local cf = base.CFrame
					- Vector3.new(0, hum.HipHeight + (base.Size.Y / 2) - 1 + depth(), 0)
				realHRP.CFrame = cf * CFrame.Angles(math.rad(angle()), 0, 0)
				realHRP.AssemblyLinearVelocity = base.AssemblyLinearVelocity
				realHRP.CanCollide = false
				if realHRP.Parent ~= workspace.CurrentCamera then
					realHRP.Parent = workspace.CurrentCamera
				end
				lastTarget = cf.Position
			end))

			add(LP.CharacterAdded:Connect(function() if active then stop() end end))
			return true
		end

		_G.TrxInvisStart, _G.TrxInvisStop = start, stop
		_G.TrxInvisToggle = function()
			if active then stop() else start() end
		end

		local function forceToggle()
			if active then stop() else start() end
		end

		_G.toggleInvisibleSteal = function()
			if (tick() - _invisToggleCooldown) < 0.3 then return end
			_invisToggleCooldown = tick()
			pcall(forceToggle)
		end
		_G._forceInvisToggle = forceToggle
		_G.TrxInvisOff = function()
			if active then stop() end
		end
		_G.TrxInvisOn = function()
			if not active then start() end
		end
		_G.invisibleStealEnabled = false
		_G.TrxInvisActive = false

		local armed, autoOn = false, false
		local function syncAuto()
			local want = (_G.AutoInvisDuringSteal == true) and (LP:GetAttribute("Stealing") == true)
			if not want then
				armed = false
				if active and autoOn then autoOn = false pcall(stop) end
				return
			end
			if active or armed then return end
			armed = true
			task.delay(tonumber(_G.TrxInvisAutoDelay) or 1.5, function()
				armed = false
				if _G.AutoInvisDuringSteal == true and not active
					and LP:GetAttribute("Stealing") == true then
					autoOn = true
					pcall(start)
				end
			end)
		end
		_G.TrxInvisSync = syncAuto
		LP:GetAttributeChangedSignal("Stealing"):Connect(syncAuto)

		_G.TrxAfterTpLoad(function()
			local wasStealing = false
			while true do
				task.wait(0.15)
				if _G.AutoInvisDuringSteal == true then
					local isStealing = LP:GetAttribute("Stealing") == true
					if isStealing ~= wasStealing then
						syncAuto()
					end
					wasStealing = isStealing
				else
					wasStealing = false
					if autoOn and active then
						autoOn = false
						pcall(stop)
					end
				end
			end
		end)
	end

			do
		local POTION = "Body Swap Potion"
		local lastSwap = -math.huge
		local loadedAt = os.clock()
		local COOLDOWN     = 3       -- min seconds between two responses
		local JUMP_MIN     = 15      -- both players must move at least this many studs
		local MATCH_TOL    = 15      -- positions must line up within this many studs
		local STALE_AFTER  = 2       -- forget a holder this long after they lose the potion

		local tracked = {}  -- [player] = { lastPos, armedAt, lostAt }

		local function hasPotion(plr)
			local char = plr.Character
			local bp   = plr:FindFirstChildOfClass("Backpack")
			if char and char:FindFirstChild(POTION) then return true end
			if bp   and bp:FindFirstChild(POTION)   then return true end
			return false
		end

		local function getRoot(plr)
			local char = plr.Character
			if not char then return nil end
			return char.PrimaryPart or char:FindFirstChild("HumanoidRootPart")
		end

				local function fireToolUI(frameName, btnName)
			local pg = LP:FindFirstChild("PlayerGui")
			if not pg then return false end
			local tf = pg:FindFirstChild("ToolsFrames")
			if not tf then return false end

			local frame = tf:FindFirstChild(frameName)
			if not frame then
				for _, c in ipairs(tf:GetChildren()) do
					if c.Name:lower() == frameName:lower() then frame = c; break end
				end
			end
			if not frame then
				warn("[ABS] no frame named " .. frameName .. " in ToolsFrames")
				return false
			end

			local btn = frame:FindFirstChild(btnName)
			if not btn then
				for _, d in ipairs(frame:GetDescendants()) do
					if d:IsA("TextButton") or d:IsA("ImageButton") then
						btn = d
						break
					end
				end
			end
			if not btn then
				warn("[ABS] no button found in " .. frameName)
				return false
			end

			if type(firesignal) ~= "function" then
				warn("[ABS] firesignal not available")
				return false
			end

			pcall(function() btn.Visible = true end)
			pcall(function() firesignal(btn.MouseButton1Click) end)
			pcall(function() firesignal(btn.MouseButton1Down) end)
			pcall(function() firesignal(btn.MouseButton1Up) end)
			pcall(function() firesignal(btn.Activated) end)
			return true
		end

		local function swapBack()
			local char = LP.Character
			local bp   = LP:FindFirstChildOfClass("Backpack")
			local hum  = char and char:FindFirstChildOfClass("Humanoid")
			if not (char and hum) then warn("[ABS] no char/hum") return false end
			local tool = (bp and bp:FindFirstChild(POTION)) or char:FindFirstChild(POTION)
			if not tool then warn("[ABS] no potion in inventory") return false end

			warn("[ABS] equipping " .. tool.Name)
			pcall(function() hum:EquipTool(tool) end)
			for _ = 1, 20 do
				if tool.Parent == char then break end
				RunService.Heartbeat:Wait()
			end
			if tool.Parent ~= char then
				warn("[ABS] failed to equip potion")
				return false
			end

			task.wait(0.12)  -- let the tool fully settle

			local fired = fireToolUI("BodySwapPotion", "Activate")
			warn("[ABS] firesignal: " .. tostring(fired))

			if not fired then
				warn("[ABS] falling back to tool:Activate()")
				pcall(function() tool:Activate() end)
			end

			return true
		end
				local function respond(why)
			local now = os.clock()
			if (now - lastSwap) < COOLDOWN then
				warn("[ABS] cooldown (" .. why .. ")")
				return
			end
			if (now - loadedAt) < 2 then return end
			lastSwap = now
			_G.TrxBodySwapLast = why
			_G.TrxBodySwapAt = tick()
			warn("[ABS] DETECTED: " .. why .. " -> firing back")
						task.spawn(function()
				pcall(swapBack)
			end)
		end

		local function busy()
			return _G.TrxIsTeleporting == true
				or _G.trxIsTeleporting == true
				or _G.__TrxManualTPActive == true
				or _G.isCloning == true
				or _G.MynxxStealHold == true
		end

		task.spawn(function()
			local myLastPos
			while true do
				RunService.Heartbeat:Wait()

				if _G.TrxAntiBodySwap ~= true or busy() then
					tracked = {}
					myLastPos = nil
					continue
				end

				local myRoot = getRoot(LP)
				if not myRoot then
					tracked = {}
					myLastPos = nil
					continue
				end

				local myPos = myRoot.Position

				for _, plr in ipairs(Players:GetPlayers()) do
					if plr ~= LP then
						local holding = hasPotion(plr)
						local entry   = tracked[plr]

						if holding and not entry then
							local root = getRoot(plr)
							if root then
								tracked[plr] = { lastPos = root.Position, armedAt = os.clock(), lostAt = 0 }
								entry = tracked[plr]
							end
						elseif (not holding) and entry and entry.lostAt == 0 then
							entry.lostAt = os.clock()
						end

						if entry then
							if entry.lostAt > 0 and (os.clock() - entry.lostAt) > STALE_AFTER then
								tracked[plr] = nil
							else
								local root = getRoot(plr)
								if root and myLastPos then
									local theirPos     = root.Position
									local theirLastPos = entry.lastPos

									local myJump    = (myPos      - myLastPos   ).Magnitude
									local theirJump = (theirPos   - theirLastPos).Magnitude
									local cross1    = (myPos      - theirLastPos).Magnitude
									local cross2    = (theirPos   - myLastPos   ).Magnitude

									if myJump    >= JUMP_MIN
									   and theirJump >= JUMP_MIN
									   and cross1    <= MATCH_TOL
									   and cross2    <= MATCH_TOL then
										warn(string.format(
											"[ABS] SWAP with %s | myJump=%.0f theirJump=%.0f cross=(%.0f,%.0f)",
											plr.Name, myJump, theirJump, cross1, cross2))
										respond("swap with " .. plr.Name)
										entry.lastPos = theirPos
										myLastPos = myPos
									else
										entry.lastPos = theirPos
									end
								end
							end
						end
					end
				end

				myLastPos = myPos
			end
		end)

		Players.PlayerRemoving:Connect(function(p) tracked[p] = nil end)

		_G.TrxSetAntiBodySwap = function(on)
			_G.TrxAntiBodySwap = on and true or false
			if type(saveTpSettings) == "function" then
				pcall(saveTpSettings)
			elseif type(_G.TrxSaveConfig) == "function" then
				pcall(_G.TrxSaveConfig)
			end
		end
		if _G.TrxAntiBodySwap == true then
			pcall(_G.TrxSetAntiBodySwap, true)
		end
	end

	local _BLOCKING_MACHINE_TYPES = {
		Fuse     = true,
		Duel     = true,
		Trade    = true,
		Crafting = true,
	}
	local function _TrxIsFusing(animalData)
		if type(animalData) ~= "table" then return false end
		local m = animalData.Machine
		if type(m) ~= "table" then return false end
		return _BLOCKING_MACHINE_TYPES[m.Type] == true
	end

	local secure_call
	do
		local LAYERS = 2
		local TEMPLATE do
			local lines = {
				"return function(__renv, __func, ...)",
				"    setfenv(0, __renv)",
				("    local function l%d(...) return __func(...) end"):format(LAYERS),
			}
			for c = LAYERS - 1, 1, -1 do
				lines[#lines + 1] = ("    local function l%d(...) return l%d(...) end"):format(c, c + 1)
			end
			lines[#lines + 1] = "    return l1(...)"
			lines[#lines + 1] = "end"
			TEMPLATE = table.concat(lines, string.char(10))
		end
		local _gti = getthreadidentity or get_thread_identity or getidentity
		local _sti = setthreadidentity or set_thread_identity or setidentity
		local _sentinel, _senv
		secure_call = (function(func, mask, ...)
			if type(func) ~= "function" or typeof(mask) ~= "Instance" then return nil end
			if not (_gti and _sti and getrenv and loadstring and setfenv) then return nil end
			local okRenv, renv = pcall(getrenv)
			if not okRenv or type(renv) ~= "table" then return nil end
			if not _sentinel then
				local okEnv, env = pcall(getsenv, mask)
				if not okEnv or type(env) ~= "table" then
					env = setmetatable({ script = mask, _G = {}, shared = {} }, { __index = renv, __newindex = renv })
				end
				local okLoad, loader = pcall(loadstring, TEMPLATE, "=" .. mask:GetFullName())
				if not okLoad or not loader then return nil end
				if not pcall(setfenv, loader, env) then return nil end
				local okSentinel, sentinel = pcall(loader)
				if not okSentinel then return nil end
				_sentinel, _senv = sentinel, env
			end
			local okLevel, level = pcall(_gti)
			if not okLevel then return nil end
			local changed = {}
			local okSnap, snap = pcall(debug.getupvalues, func)
			if okSnap and type(snap) == "table" then
				for i, v in pairs(snap) do
					if typeof(v) == "Instance" and v:IsA("LuaSourceContainer") then
						if pcall(debug.setupvalue, func, i, mask) then changed[i] = v end
					end
				end
			end
			if not pcall(_sti, 2) then return nil end
			local co, args = coroutine.create(_sentinel), table.pack(renv, func, ...)
			local response, err
			while true do
				local r = table.pack(coroutine.resume(co, table.unpack(args, 1, args.n)))
				if not r[1] then err = r[2] break end
				if coroutine.status(co) == "dead" then
					response = table.pack(table.unpack(r, 2, r.n)) break
				end
				args = table.pack(coroutine.yield(table.unpack(r, 2, r.n)))
			end
			pcall(_sti, level)
			for i, orig in pairs(changed) do pcall(debug.setupvalue, func, i, orig) end
			if err or not response then return nil end
			return table.unpack(response, 1, response.n)
		end)
	end
	_G.secure_call = secure_call

