		local worldMax = tonumber(_G.TrxWorldWaitMax) or 90
		local settle = tonumber(_G.TrxUiSettle) or 1.5
		local function worldReady()
			local char = LP.Character
			if not char then return false end
			local hrp = char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart
			local plots = workspace:FindFirstChild("Plots")
			if not hrp or not plots then return false end
			local okKids = true
			pcall(function()
				if #plots:GetChildren() == 0 then okKids = false end
			end)
			return okKids
		end
		local t0 = os.clock()
		while not worldReady() and (os.clock() - t0) < worldMax do
			task.wait(0.15)
		end
		task.wait(math.max(0.5, settle))
		_G.__trxPhase = "ui-build"
	end

