			local function fmt(v)
				if v >= 1000000 then return string.format("%.1fM", v / 1000000) end
				if v >= 10000 then return string.format("%.0fk", v / 1000) end
				if step < 1 then return string.format("%.2f", v) end
				return tostring(math.floor(v + 0.5))
			end
			local function paint()
				local v = tonumber(getV()) or min
				lab.Text = label .. ": " .. fmt(v)
			end
			local function bump(dir)
				local v = tonumber(getV()) or min
				v = math.clamp(v + dir * step, min, max)
				v = math.floor(v / step + 0.5) * step
				v = math.clamp(v, min, max)
				setV(v)
				paint()
				saveTpSettings()
			end
			minus.MouseButton1Click:Connect(function() bump(-1) end)
			plus.MouseButton1Click:Connect(function() bump(1) end)
			paint()
			return row, paint
		end
