		do
			local dragging = false
			local dragInput = nil
			local dragStart = nil
			local startPosition = nil
			local moveConnection, endConnection
			local function finishDrag()
				dragging = false
				if moveConnection then moveConnection:Disconnect(); moveConnection = nil end
				if endConnection then endConnection:Disconnect(); endConnection = nil end
				local p = wm.Position
				_G.TrxDiscordLinkX = math.clamp(p.X.Offset, -2000, 2000)
				_G.TrxDiscordLinkY = math.clamp(p.Y.Offset, 0, 1400)
				if type(_G.TrxSaveConfigNow) == "function" then
					pcall(_G.TrxSaveConfigNow)
				elseif type(_G.TrxSaveConfig) == "function" then
					pcall(_G.TrxSaveConfig)
				end
			end
			wm.InputBegan:Connect(function(input)
				if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
				dragging = true
				dragStart = input.Position
				startPosition = wm.Position
				if input.UserInputType == Enum.UserInputType.Touch then dragInput = input end
				moveConnection = UIS.InputChanged:Connect(function(changed)
					if not dragging then return end
					if changed.UserInputType == Enum.UserInputType.MouseMovement or changed == dragInput then
						local delta = changed.Position - dragStart
						local x = math.clamp(startPosition.X.Offset + delta.X, -2000, 2000)
						local y = math.clamp(startPosition.Y.Offset + delta.Y, 0, 1400)
						wm.Position = UDim2.new(0.5, x, 0, y)
					end
				end)
				endConnection = UIS.InputEnded:Connect(function(ended)
					if ended.UserInputType == Enum.UserInputType.MouseButton1 or ended.UserInputType == Enum.UserInputType.Touch then
						finishDrag()
					end
				end)
			end)
		end
