        local pingLabel = mk("TextLabel", baseTimerBox, {
            BackgroundTransparency = 1, Size = UDim2.fromOffset(70, 20),
            Position = UDim2.new(1, -76, 0, 0), Font = FB, TextSize = 11,
            TextColor3 = Color3.fromRGB(255, 255, 255), Text = "PING: --",
            TextXAlignment = Enum.TextXAlignment.Right, TextYAlignment = Enum.TextYAlignment.Center,
            ZIndex = 122,
        })

        local baseTimerLbl = mk("TextLabel", baseTimerBox, {
            BackgroundTransparency = 1, Size = UDim2.new(1, -140, 1, 0),
            Position = UDim2.fromOffset(70, 0), Font = FB, TextSize = 11,
            TextColor3 = Color3.fromRGB(255, 255, 255), Text = "BASE --",
            TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Center,
            ZIndex = 122,
        })
		do
			local lastTimerScan = 0
			local function fmtSec(sec)
				sec = math.max(0, math.floor(tonumber(sec) or 0))
				local m = math.floor(sec / 60)
				local s = sec % 60
				if m > 0 then
					return string.format("%d:%02d", m, s)
				end
				return string.format("%ds", s)
			end
			local function closestPlot()
				local char = LP.Character
				local hrp = char and char:FindFirstChild("HumanoidRootPart")
				local plots = workspace:FindFirstChild("Plots")
				if not hrp or not plots then return nil end
				local best, bd = nil, math.huge
				for _, plot in ipairs(plots:GetChildren()) do
					local pos
					pcall(function()
						if plot:IsA("Model") then pos = plot:GetPivot().Position
						elseif plot:IsA("BasePart") then pos = plot.Position end
					end)
					if pos then
						local d = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(pos.X, 0, pos.Z)).Magnitude
						if d < bd then bd, best = d, plot end
					end
				end
				if best and bd <= 140 then return best end
				return nil
			end
			local function parseTimerText(t)
				if type(t) ~= "string" or t == "" then return nil, nil end
				local low = t:lower()
				if low:find("empty") then return nil, nil end
				if low == "locked" or low == "lock" then return 0, "LOCKED" end
				local mm, ss = t:match("(%d+)%s*:%s*(%d+)")
				if mm and ss then
					return (tonumber(mm) or 0) * 60 + (tonumber(ss) or 0), t
				end
				local sec = tonumber(t:match("(%d+)%s*[sS]%f[^%a]")) or tonumber(t:match("^%s*(%d+)%s*$"))
				if sec then return sec, t end
				return nil, nil
			end
			local function findRemainingTimeLabel(plot)
				if not plot then return nil end
				local purchases = plot:FindFirstChild("Purchases")
				local block = purchases and purchases:FindFirstChild("PlotBlock")
				if not block then block = plot:FindFirstChild("PlotBlock", true) end
				local main = block and block:FindFirstChild("Main")
				local bb = main and main:FindFirstChild("BillboardGui")
				local lbl = bb and bb:FindFirstChild("RemainingTime")
				if lbl and (lbl:IsA("TextLabel") or lbl:IsA("TextButton")) then
					return lbl
				end
				local deep = plot:FindFirstChild("RemainingTime", true)
				if deep and (deep:IsA("TextLabel") or deep:IsA("TextButton") or deep:IsA("StringValue") or deep:IsA("NumberValue") or deep:IsA("IntValue")) then
					return deep
				end
				return nil
			end
			local function readPlotTimer(plot)
				if not plot then return nil, nil end
				local lbl = findRemainingTimeLabel(plot)
				if lbl then
					if lbl:IsA("TextLabel") or lbl:IsA("TextButton") then
						local sec, raw = parseTimerText(tostring(lbl.Text or ""))
						if sec ~= nil then return sec, raw or lbl.Text end
						if tostring(lbl.Text or "") ~= "" then return nil, tostring(lbl.Text) end
					elseif lbl:IsA("NumberValue") or lbl:IsA("IntValue") then
						return tonumber(lbl.Value), nil
					elseif lbl:IsA("StringValue") then
						return parseTimerText(tostring(lbl.Value or ""))
					end
				end
				local ch = nil
				if type(_G.Trx_GetPlotChannel) == "function" then
					ch = _G.Trx_GetPlotChannel(plot)
				elseif type(_G.TrxSyncGet) == "function" then
					local ord
					pcall(function() ord = plot:GetAttribute("Order") end)
					if ord ~= nil then ch = _G.TrxSyncGet("Plot" .. tostring(ord)) end
					if not ch then ch = _G.TrxSyncGet(plot.Name) end
				end
				if type(ch) == "table" then
					local keys = { "RemainingTime", "Timer", "BaseTimer", "LockTimer", "TimeLeft", "Cooldown", "BlockTimer" }
					for _, k in ipairs(keys) do
						local v = nil
						if type(_G.sProp) == "function" then v = _G.sProp(ch, k) end
						if v == nil and type(_G.trxChannelGet) == "function" then v = _G.trxChannelGet(ch, k) end
						if v == nil then v = rawget(ch, k) end
						if type(v) == "number" then return v, nil end
						if type(v) == "string" then
							local sec, raw = parseTimerText(v)
							if sec ~= nil then return sec, raw end
						end
					end
				end
				local roots = {}
				local purchases = plot:FindFirstChild("Purchases")
				if purchases then roots[#roots + 1] = purchases end
				local block = plot:FindFirstChild("PlotBlock", true)
				if block then roots[#roots + 1] = block end
				for _, root in ipairs(roots) do
					local ok, desc = pcall(function() return root:GetDescendants() end)
					if ok and type(desc) == "table" then
						for _, d in ipairs(desc) do
							if d:IsA("TextLabel") or d:IsA("TextButton") then
								local n = d.Name:lower()
								if n:find("remain") or n:find("timer") or n:find("time") or n:find("lock") then
									local sec, raw = parseTimerText(tostring(d.Text or ""))
									if sec ~= nil then return sec, raw end
								end
								local sec, raw = parseTimerText(tostring(d.Text or ""))
								if sec ~= nil and tostring(d.Text or ""):find(":") then
									return sec, raw
								end
							end
						end
					end
				end
				return nil, nil
			end
			RunService.RenderStepped:Connect(function(dt)
				local now = os.clock()
				if now - lastTimerScan >= 0.2 then
					lastTimerScan = now
					local plot = closestPlot()
					local sec, raw = readPlotTimer(plot)
										if raw and tostring(raw):upper() == "LOCKED" then
						baseTimerLbl.Text = "LOCKED"
					elseif sec ~= nil then
						if sec <= 0 then
							baseTimerLbl.Text = "00:00"
						else
							baseTimerLbl.Text = (raw and tostring(raw):find(":") and tostring(raw) or fmtSec(sec))
						end
					else
						baseTimerLbl.Text = plot and "--" or "none"
					end
				end
			end)
		end
                local RunService = game:GetService("RunService")
        local Stats = game:GetService("Stats")
        local fpsFrames = 0
        local fpsTime = 0
        RunService.RenderStepped:Connect(function(dt)
            fpsFrames = fpsFrames + 1
            fpsTime = fpsTime + dt
            if fpsTime >= 0.5 then
                local fps = math.floor(fpsFrames / fpsTime)
                fpsLabel.Text = "FPS: " .. tostring(fps)
                local ping = LP:GetNetworkPing() * 1000
                if type(ping) ~= "number" or ping <= 0 then
                    ping = Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
                end
                pingLabel.Text = "PING: " .. tostring(math.floor(ping)) .. "ms"
                fpsFrames = 0
                fpsTime = 0
            end
        end)
