			local b = mk("TextButton", tpBody, {
				Size = UDim2.new(1, 0, 0, 26), BackgroundColor3 = btnC, BorderSizePixel = 0,
				Text = label .. ": off", AutoButtonColor = false, Font = FB, TextSize = 11, TextColor3 = tx,
			})
			corner(b, 8)
			local function paint()
				local onv = getOn() and true or false
				b.BackgroundColor3 = onv and onC or btnC
				b.TextColor3 = onv and onTx or tx
				b.Text = label .. (onv and ": on" or ": off")
			end
			b.MouseButton1Click:Connect(function()
				setOn(not getOn())
				paint()
				saveTpSettings()
			end)
			paint()
			return paint
		end
		local function tpBtn(label, onClick)
			local b = mk("TextButton", tpBody, {
