					Size = UDim2.fromOffset(66, 20),
					Position = UDim2.new(1, -66, 0.5, -10),
					BackgroundColor3 = btnC,
					BorderSizePixel = 0,
					Text = "",
					AutoButtonColor = false,
					Font = FB, TextSize = 9, TextColor3 = tx,
				})
				corner(b, 7)
				local opts = {"front", "side", "auto"}
				local function paint()
					b.Text = string.upper(tostring(getMode() or "auto"))
				end
				b.MouseButton1Click:Connect(function()
					local cur = tostring(getMode() or "auto"):lower()
					local idx = 1
					for i, v in ipairs(opts) do
						if v == cur then idx = i break end
					end
					setMode(opts[(idx % #opts) + 1])
					paint()
					if type(_G.TrxSaveConfig) == "function" then pcall(_G.TrxSaveConfig) end
				end)
				paint()
				return paint
			end

