					Font = FB, TextSize = 10, TextColor3 = tx, TextXAlignment = Enum.TextXAlignment.Left,
					Text = "MINI UI",
				})
				mk("Frame", miniUi, {
					Size = UDim2.new(1, -14, 0, 1), Position = UDim2.fromOffset(7, 20),
					BackgroundColor3 = onC, BackgroundTransparency = 0.4, BorderSizePixel = 0,
				})
				local miniScroll = mk("ScrollingFrame", miniUi, {
					Position = UDim2.fromOffset(4, 24), Size = UDim2.new(1, -8, 0, 0),
					AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
					BorderSizePixel = 0, ScrollBarThickness = 3, ScrollBarImageColor3 = mute,
					CanvasSize = UDim2.fromOffset(0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y,
					ScrollingDirection = Enum.ScrollingDirection.Y,
				})
				local miniMaxH = 160
				miniBody = mk("Frame", miniScroll, {
					Position = UDim2.fromOffset(2, 0), Size = UDim2.new(1, -4, 0, 0),
					AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
				})
				mk("UIListLayout", miniBody, {Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder})
				mk("UIPadding", miniBody, {PaddingBottom = UDim.new(0, 4)})
				local function clampMiniHeight()
					local contentH = miniBody.AbsoluteSize.Y
					if contentH <= 1 then
						miniScroll.Size = UDim2.new(1, -8, 0, 0)
						return
					end
					local h = math.min(contentH, miniMaxH)
					miniScroll.Size = UDim2.new(1, -8, 0, h)
				end
				miniBody:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
					task.defer(clampMiniHeight)
				end)
				_G.TrxClampMiniHeight = clampMiniHeight
				drag(miniHead, miniUi, function(fr)
					_G._stp_toolX = fr.Position.X.Offset
					_G._stp_toolY = fr.Position.Y.Offset
					saveTpSettings()
				end)
