				local function miniHL(parent, label, getOn, setOn, onGear)
					local row = mk("TextButton", parent, {
						Size = UDim2.new(1, -2, 0, 26), BackgroundColor3 = btnC,
						BackgroundTransparency = 0, BorderSizePixel = 0,
						Text = "", AutoButtonColor = false,
