					if onGear then
						gearBtn = mk("TextButton", row, {
							Size = UDim2.fromOffset(22, 20), Position = UDim2.new(1, -24, 0.5, -10),
							BackgroundTransparency = 1, BorderSizePixel = 0,
							Text = "*", Font = FB, TextSize = 12, TextColor3 = mute,
							AutoButtonColor = false,
						})
						gearBtn.MouseButton1Click:Connect(function()
							if onGear then onGear() end
						end)
					end
					local function paint()
						local onv = getOn() and true or false
						row.BackgroundColor3 = onv and onC or btnC
						row.BackgroundTransparency = 0
						lab.Text = label .. (onv and ": on" or ": off")
						lab.TextColor3 = onv and onTx or tx
						if gearBtn then gearBtn.TextColor3 = onv and onTx or mute end
					end
					row.MouseButton1Click:Connect(function()
						setOn(not getOn())
						paint()
						saveTpSettings()
					end)
					paint()
					return paint
				end
