				})
				corner(ivPanel, 10)
				stroke(ivPanel)
				local ivHead = mk("TextButton", ivPanel, {
					Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1,
					Text = "", AutoButtonColor = false,
				})
				mk("TextLabel", ivHead, {
					BackgroundTransparency = 1, Size = UDim2.new(1, -12, 1, 0), Position = UDim2.fromOffset(0, 0),
