				mk("UIListLayout", ivBody, {Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder})
				local function ivPill(label, getOn, setOn)
					local b = mk("TextButton", ivBody, {
						Size = UDim2.new(1, 0, 0, 26), BackgroundColor3 = btnC, BorderSizePixel = 0,
						Text = label .. ": off", AutoButtonColor = false, Font = FB, TextSize = 11, TextColor3 = tx,
