				end
				local function ivStepper(label, minV, maxV, step, getV, setV, fmt)
					local row = mk("Frame", ivBody, {
						Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1, BorderSizePixel = 0,
					})
					local lab = mk("TextLabel", row, {
						BackgroundTransparency = 1, Position = UDim2.fromOffset(2, 0), Size = UDim2.new(1, -56, 1, 0),
						Font = F, TextSize = 11, TextColor3 = mute,
						TextXAlignment = Enum.TextXAlignment.Left, Text = "",
					})
					local minus = mk("TextButton", row, {
						Size = UDim2.fromOffset(22, 20), Position = UDim2.new(1, -48, 0.5, -10),
						BackgroundColor3 = btnC, BorderSizePixel = 0, Text = "-",
						Font = FB, TextSize = 12, TextColor3 = tx, AutoButtonColor = false,
					})
					corner(minus, 5)
					local plus = mk("TextButton", row, {
						Size = UDim2.fromOffset(22, 20), Position = UDim2.new(1, -22, 0.5, -10),
						BackgroundColor3 = btnC, BorderSizePixel = 0, Text = "+",
						Font = FB, TextSize = 12, TextColor3 = tx, AutoButtonColor = false,
					})
					corner(plus, 5)
					local function paint()
						local v = tonumber(getV()) or minV
						lab.Text = label .. ": " .. (fmt and fmt(v) or tostring(v))
					end
					local function bump(dir)
						local v = tonumber(getV()) or minV
						v = math.clamp(v + dir * step, minV, maxV)
						v = math.floor((v / step) + 0.5) * step
						v = math.clamp(v, minV, maxV)
						setV(v)
						paint()
						saveTpSettings()
					end
					minus.MouseButton1Click:Connect(function() bump(-1) end)
					plus.MouseButton1Click:Connect(function() bump(1) end)
					paint()
					return paint
				end
				paintInvisIv = ivPill("invis steal", function()
