				end)
				ivPill("auto recover", function()
					return _G.AutoRecoverLagback ~= false
				end, function(v)
					_G.AutoRecoverLagback = v and true or false
				end)
								ivStepper("rotation", 0, 360, 5, function()
					return tonumber(_G.InvisStealAngle) or 180
				end, function(v)
					_G.InvisStealAngle = v
					_G.TrxInvisAngle = v
				end, function(v) return tostring(math.floor(v + 0.5)) .. " deg" end)
				ivStepper("depth", 0, 20, 0.5, function()
					return tonumber(_G.SinkSliderValue) or 5
				end, function(v)
					_G.SinkSliderValue = v
					_G.TrxInvisDepth = v
				end, function(v)
					return string.format("%.1f", v)
				end)
				ivStepper("walkspeed", 16, 100, 1, function()
					return tonumber(_G.TrxWalkSpeed) or 20
				end, function(v)
					_G.TrxWalkSpeed = math.clamp(tonumber(v) or 20, 16, 100)
					if type(_G.TrxPaintWalkSpeed) == "function" then pcall(_G.TrxPaintWalkSpeed) end
				end, function(v) return tostring(math.floor(v + 0.5)) end)
				local _prevPaintInvis = paintInvisIv
				paintInvisIv = function()
					if _prevPaintInvis then _prevPaintInvis() end
					if paintWsPill then paintWsPill() end
				end

			local pri = mk("Frame", sg, {
				Size = UDim2.fromOffset(260, 300),
				Position = UDim2.fromOffset(tonumber(_G._stp_priX) or 300, tonumber(_G._stp_priY) or 80),
				BackgroundColor3 = bg, BorderSizePixel = 0, Visible = false, Active = true,
			})
			corner(pri, 10)
			stroke(pri)
			local priH = mk("TextButton", pri, {
				Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1,
				Text = "edit priority", Font = FB, TextSize = 12, TextColor3 = tx, AutoButtonColor = false,
			})
			bindPanelDrag(priH, pri, "_stp_priX", "_stp_priY")
			local priPasteBox = mk("TextBox", pri, {
				Position = UDim2.fromOffset(6, 24), Size = UDim2.new(1, -12, 0, 48),
				BackgroundColor3 = btnC, BorderSizePixel = 0, Font = F, TextSize = 10,
				TextColor3 = tx, PlaceholderText = 'Paste priority JSON list here, then click Apply',
				Text = "", ClearTextOnFocus = false, MultiLine = true, TextWrapped = true,
				TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
			})
			corner(priPasteBox, 6)
			local priPasteApply = btn(pri, "Apply list", UDim2.new(1, -12, 0, 22), UDim2.fromOffset(6, 75))
			local priPasteStatus = mk("TextLabel", pri, {
				Position = UDim2.fromOffset(8, 98), Size = UDim2.new(1, -16, 0, 14),
				BackgroundTransparency = 1, Font = F, TextSize = 10, TextColor3 = mute,
				TextXAlignment = Enum.TextXAlignment.Left, Text = "Order = priority (top is #1)",
			})
			local priScroll = mk("ScrollingFrame", pri, {
				Position = UDim2.fromOffset(6, 114), Size = UDim2.new(1, -12, 1, -146),
				BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4,
				ScrollBarImageColor3 = onC,
				AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.fromOffset(0, 0),
			})
			mk("UIListLayout", priScroll, {Padding = UDim.new(0, 3)})
			local addBox = mk("TextBox", pri, {
				Position = UDim2.new(0, 6, 1, -28), Size = UDim2.new(1, -40, 0, 22),
				BackgroundColor3 = btnC, BorderSizePixel = 0, Font = F, TextSize = 12,
				TextColor3 = tx, PlaceholderText = "add name", Text = "",
			})
			corner(addBox, 6)
			local addBtn = btn(pri, "+", UDim2.fromOffset(24, 22), UDim2.new(1, -30, 1, -28))
			local function priCopy()
				local t = {}
				local src = _G.SHARED_PRIORITY_ITEMS
				if type(src) == "table" then for i, v in ipairs(src) do t[i] = v end end
				return t
			end
			local function priCommit(t)
				_G.SHARED_PRIORITY_ITEMS = t
				_G._stp_priorityCfg = t
				if type(_G.TrxInvalidatePriMap) == "function" then _G.TrxInvalidatePriMap() end
				if type(_G.TrxBustScanCache) == "function" then _G.TrxBustScanCache() end
				if type(_G.TrxForceResortList) == "function" then _G.TrxForceResortList() end
				if type(_G.TrxSaveConfigNow) == "function" then
					_G.TrxSaveConfigNow()
				else
					saveTpSettings()
				end
				if type(_G.TrxRefreshStealTarget) == "function" then _G.TrxRefreshStealTarget() end
			end
			local refreshPri
			priPasteApply.MouseButton1Click:Connect(function()
				local raw = tostring(priPasteBox.Text or "")
				local ok, decoded = pcall(function()
					return game:GetService("HttpService"):JSONDecode(raw)
				end)
				if not ok or type(decoded) ~= "table" then
					priPasteStatus.Text = "Invalid JSON list — paste an array of quoted names."
					return
				end
				local items, seen = {}, {}
				for _, value in ipairs(decoded) do
					if type(value) == "string" then
						local name = value:gsub("^%s+", ""):gsub("%s+$", "")
						local key = name:lower()
						if name ~= "" and not seen[key] then
							seen[key] = true
							items[#items + 1] = name
						end
					end
				end
				if #items == 0 then
					priPasteStatus.Text = "No names found in that list."
					return
				end
				priCommit(items)
				priPasteStatus.Text = "Applied " .. tostring(#items) .. " priorities."
				refreshPri()
			end)
			refreshPri = function()
				for _, ch in ipairs(priScroll:GetChildren()) do
					if ch:IsA("Frame") then ch:Destroy() end
				end
				local t = priCopy()
				for i, name in ipairs(t) do
					local row = mk("Frame", priScroll, {Size = UDim2.new(1, -4, 0, 20), BackgroundTransparency = 1})
					mk("TextLabel", row, {
						BackgroundTransparency = 1, Size = UDim2.new(1, -72, 1, 0), Font = F, TextSize = 11,
						TextColor3 = tx, TextXAlignment = Enum.TextXAlignment.Left, Text = tostring(name),
					})
					local up = btn(row, "^", UDim2.fromOffset(20, 18), UDim2.new(1, -62, 0, 1))
					local dn = btn(row, "v", UDim2.fromOffset(20, 18), UDim2.new(1, -40, 0, 1))
					local dl = btn(row, "x", UDim2.fromOffset(20, 18), UDim2.new(1, -18, 0, 1))
					up.MouseButton1Click:Connect(function()
						if i <= 1 then return end
						t[i], t[i - 1] = t[i - 1], t[i]
						priCommit(t)
						refreshPri()
					end)
					dn.MouseButton1Click:Connect(function()
						if i >= #t then return end
						t[i], t[i + 1] = t[i + 1], t[i]
						priCommit(t)
						refreshPri()
					end)
					dl.MouseButton1Click:Connect(function()
						table.remove(t, i)
						priCommit(t)
						refreshPri()
					end)
				end
			end
			addBtn.MouseButton1Click:Connect(function()
				local n = tostring(addBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
				if n == "" then return end
				local t = priCopy()
				t[#t + 1] = n
				priCommit(t)
				addBox.Text = ""
				refreshPri()
			end)
			local function togglePri()
				refreshPri()
				if blkPanel then blkPanel.Visible = false end
				pri.Visible = not pri.Visible
			end
			_G.TrxOpenPriorityList = function() refreshPri(); pri.Visible = true end
			_G.TrxTogglePriorityList = togglePri

			blkPanel = mk("Frame", sg, {
				Size = UDim2.fromOffset(204, 166),
				Position = UDim2.fromOffset(tonumber(_G._stp_blkX) or 548, tonumber(_G._stp_blkY) or 80),
				BackgroundColor3 = bg, BorderSizePixel = 0, Visible = false, Active = true,
			})
			corner(blkPanel, 10)
			stroke(blkPanel)
			local blkH = mk("TextButton", blkPanel, {
				Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1,
				Text = "brainrot blacklist", Font = FB, TextSize = 12, TextColor3 = tx, AutoButtonColor = false,
			})
			bindPanelDrag(blkH, blkPanel, "_stp_blkX", "_stp_blkY")
			local blkScroll = mk("ScrollingFrame", blkPanel, {
				Position = UDim2.fromOffset(6, 24), Size = UDim2.new(1, -12, 1, -56),
				BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4,
				ScrollBarImageColor3 = onC,
				AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.fromOffset(0, 0),
			})
			mk("UIListLayout", blkScroll, {Padding = UDim.new(0, 3)})
			local blkBox = mk("TextBox", blkPanel, {
				Position = UDim2.new(0, 6, 1, -28), Size = UDim2.new(1, -40, 0, 22),
				BackgroundColor3 = btnC, BorderSizePixel = 0, Font = F, TextSize = 11,
				TextColor3 = tx, PlaceholderText = "brainrot name", Text = "",
			})
			corner(blkBox, 6)
			local blkAdd = btn(blkPanel, "+", UDim2.fromOffset(24, 22), UDim2.new(1, -30, 1, -28))
			local function blkCopy()
				local out = {}
				local src = _G.SHARED_BLACKLIST_ITEMS
				if type(src) == "table" then
					for i, name in ipairs(src) do out[i] = name end
				end
				return out
			end
			local function blkCommit(items)
				_G.SHARED_BLACKLIST_ITEMS = items
				_G._stp_blacklistCfg = items
				if type(_G.TrxRebuildBlacklist) == "function" then _G.TrxRebuildBlacklist() end
				local selected = _G.TrxStealTarget or _G.TrxSelectedPetData
				if selected and _isBlacklistedPet(selected) then
					_G.TrxManualStealUID = nil
					_G.__trxChosenPet = nil
					if type(_G.TrxClearTPSync) == "function" then _G.TrxClearTPSync() end
				end
				if type(_G.TrxBustScanCache) == "function" then _G.TrxBustScanCache() end
				if type(_G.TrxForceResortList) == "function" then _G.TrxForceResortList() end
				if type(_G.TrxRefreshStealTarget) == "function" then _G.TrxRefreshStealTarget() end
				if type(_G.TrxSaveConfigNow) == "function" then
					_G.TrxSaveConfigNow()
				else
					saveTpSettings()
				end
			end
			local refreshBlk
			refreshBlk = function()
				for _, child in ipairs(blkScroll:GetChildren()) do
					if child:IsA("Frame") then child:Destroy() end
				end
				local items = blkCopy()
				for i, name in ipairs(items) do
					local row = mk("Frame", blkScroll, {Size = UDim2.new(1, -4, 0, 20), BackgroundTransparency = 1})
					mk("TextLabel", row, {
						BackgroundTransparency = 1, Size = UDim2.new(1, -26, 1, 0), Font = F, TextSize = 10,
						TextColor3 = tx, TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd, Text = tostring(name),
					})
					local del = btn(row, "x", UDim2.fromOffset(20, 18), UDim2.new(1, -20, 0, 1))
					del.MouseButton1Click:Connect(function()
						table.remove(items, i)
						blkCommit(items)
						refreshBlk()
					end)
				end
			end
			blkAdd.MouseButton1Click:Connect(function()
				local name = tostring(blkBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
				if name == "" then return end
				local items = blkCopy()
				local normalized = _normName(name)
				for _, existing in ipairs(items) do
					if _normName(existing) == normalized then
						blkBox.Text = ""
						return
					end
				end
				items[#items + 1] = name
				blkCommit(items)
				blkBox.Text = ""
				refreshBlk()
			end)
			_G.TrxToggleBlacklist = function()
				refreshBlk()
				pri.Visible = false
				blkPanel.Visible = not blkPanel.Visible
			end
			_G.TrxOpenBlacklist = function()
				refreshBlk()
				pri.Visible = false
				blkPanel.Visible = true
			end

			end
			buildRestGuis()
			if applyGuiTheme then applyGuiTheme() end
			layoutCompactTools()
			priPanel = pri
			if extrasHidden or guiHidden then extras.Visible = false end
			if guiHidden then setGuiHidden(true) end
			paintOpenGuiBtn()
			return extras
		end
		_trxAfter(1, ensureExtras)
	end
end)

task.spawn(function()
	local _resetCamLocked = false
	local _resetCamCF = nil
	local _resetCamConn = nil
	local _resetThread = nil
	local _resetStop = false
	local function _freezeCam()
		local cam = workspace.CurrentCamera
		if not cam then return end
		_resetCamCF = cam.CFrame
		cam.CameraType = Enum.CameraType.Scriptable
		cam.CFrame = _resetCamCF
		_resetCamLocked = true
		if _resetCamConn then pcall(function() _resetCamConn:Disconnect() end) end
		_resetCamConn = RunService.RenderStepped:Connect(function()
			if _resetCamLocked and _resetCamCF and workspace.CurrentCamera then
				local c = workspace.CurrentCamera
				c.CameraType = Enum.CameraType.Scriptable
				c.CFrame = _resetCamCF
			end
		end)
	end
	local function _unfreezeCam()
		_resetCamLocked = false
		if _resetCamConn then
			pcall(function() _resetCamConn:Disconnect() end)
			_resetCamConn = nil
		end
		local cam = workspace.CurrentCamera
		if cam then
			cam.CameraType = Enum.CameraType.Custom
			local ch = LP.Character
			local hum = ch and ch:FindFirstChildOfClass("Humanoid")
			if hum then cam.CameraSubject = hum end
		end
	end
	local function instantReset()
