task.spawn(function()
    local Players = game:GetService("Players")
    local LP = Players.LocalPlayer
    while not LP do task.wait() end
    local PG = LP:WaitForChild("PlayerGui")
    local lastBalloonReset = 0

    while true do
        task.wait(1) -- Scan once per second
        if _G.TrxResetOnBalloon == true and not (_G.TrxIsTeleporting or _G.trxIsTeleporting or _G.MynxxStealHold) then
            for _, g in ipairs(PG:GetDescendants()) do
                if g:IsA("TextLabel") or g:IsA("TextButton") then
                    local txt = g.Text
                    if txt and string.find(string.lower(txt), 'ran "balloon" on you', 1, true) then
                        if os.clock() - lastBalloonReset > 20 then
                            lastBalloonReset = os.clock()
                            if type(_G.TrxInstantReset) == "function" then
                                pcall(_G.TrxInstantReset)
                            end
                        end
                        break -- Exit loop once detected
                    end
                end
            end
        end
    end
end)
