    local pad = Instance.new("UIPadding", list)
    pad.PaddingTop = UDim.new(0, 5); pad.PaddingLeft = UDim.new(0, 5); pad.PaddingRight = UDim.new(0, 5)
    local status = Instance.new("TextLabel")
