    status.TextYAlignment = Enum.TextYAlignment.Top
    status.Text = "Status: Choose a player"
    status.Parent = frame
    _G.TrxCampStatusLabel = status
    local selectedLabel = Instance.new("TextLabel")
    selectedLabel.Position = UDim2.fromOffset(10, 254)
    selectedLabel.Size = UDim2.new(1, -20, 0, 16)
    selectedLabel.BackgroundTransparency = 1
    selectedLabel.Font = Enum.Font.Gotham
    selectedLabel.TextSize = 10
    selectedLabel.TextColor3 = Color3.fromRGB(190, 145, 255)
    selectedLabel.TextXAlignment = Enum.TextXAlignment.Left
    selectedLabel.Text = "Selected: none"
    selectedLabel.Parent = frame
    local chosenPlayer
    local function button(parentObj, text, color, size, pos)
        local b = Instance.new("TextButton")
        b.Text = text; b.Font = Enum.Font.GothamBold; b.TextSize = 11
        b.TextColor3 = Color3.fromRGB(245, 245, 250); b.BackgroundColor3 = color
        b.BorderSizePixel = 0; b.Size = size; b.Position = pos; b.AutoButtonColor = true; b.Parent = parentObj
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
        return b
    end
    local refreshPlayers
    local camp = button(frame, "STOP CAMP", Color3.fromRGB(100, 45, 175), UDim2.new(1, -20, 0, 26), UDim2.fromOffset(10, 278))
    _G.TrxCampToggle = camp

    refreshPlayers = function()
        for _, child in ipairs(list:GetChildren()) do if child:IsA("TextButton") then child:Destroy() end end
        local players = Players:GetPlayers()
        table.sort(players, function(a, b) return a.Name:lower() < b.Name:lower() end)
        for _, player in ipairs(players) do
            if player ~= LocalPlayer then
                local b = Instance.new("TextButton")
                b.Size = UDim2.new(1, -4, 0, 27)
                b.BackgroundColor3 = (chosenPlayer == player) and Color3.fromRGB(255, 210, 45) or Color3.fromRGB(8, 8, 10)
                b.BorderSizePixel = 0
                b.Text = player.DisplayName .. "  (@" .. player.Name .. ")"
                b.Font = Enum.Font.Gotham
                b.TextSize = 10
                b.TextColor3 = (chosenPlayer == player) and Color3.fromRGB(0, 0, 0) or Color3.fromRGB(235, 230, 245)
                b.Parent = list
                Instance.new("UICorner", b).CornerRadius = UDim.new(0, 5)
                b.MouseButton1Click:Connect(function()
                    chosenPlayer = player
                    selectedLabel.Text = "Selected: " .. player.Name
                    frame.Visible = true
                    beginCamp(player)
                    refreshPlayers()
                end)
            end
        end
        task.defer(function() list.CanvasSize = UDim2.fromOffset(0, layout.AbsoluteContentSize.Y + 10) end)
    end
    camp.MouseButton1Click:Connect(function()
        if State.active then
            stopCamp("Stopped")
        elseif chosenPlayer then
            beginCamp(chosenPlayer)
        else
            notify("Click a player in the list first")
        end
    end)
    Players.PlayerAdded:Connect(refreshPlayers)
    Players.PlayerRemoving:Connect(function(p)
        if State.target == p then stopCamp("Target left the server") end
        if chosenPlayer == p then chosenPlayer = nil; selectedLabel.Text = "Selected: none" end
        refreshPlayers()
    end)
    do
        local dragging, dragInput, dragStart, startPos
        header.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true; dragStart = input.Position; startPos = frame.Position
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                        _G.TrxCampUiX = frame.Position.X.Offset
                        _G.TrxCampUiY = frame.Position.Y.Offset
                        if type(_G.TrxSaveConfig) == "function" then pcall(_G.TrxSaveConfig) end
                    end
                end)
            end
        end)
        header.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then dragInput = input end
        end)
        game:GetService("UserInputService").InputChanged:Connect(function(input)
            if dragging and input == dragInput then
                local delta = input.Position - dragStart
                frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
                _G.TrxCampUiX = frame.Position.X.Offset
                _G.TrxCampUiY = frame.Position.Y.Offset
            end
        end)
    end
    refreshPlayers()
    notify("Ready — choose a player")
end

do
    if type(_G.ROSE_K7_SHUTDOWN) == "function" then pcall(_G.ROSE_K7_SHUTDOWN) end
    local controllerAlive = true
    local k7Started = false
    local k7Starting = false
    local capturedSetNearest = nil
    local capturedSetInstant = nil

        local function roseK7Wanted()
        -- Rose: run K7 whenever nearest is on OR camp is active.
        if _G.TrxStealMode == "nearest" then return true end
        local camp = _G.TrxBaseCamp
        return camp ~= nil and camp.active == true
    end

    local function startRoseK7()
        if k7Started or k7Starting then return end
        k7Starting = true
        _G.ROSE_K7_ENABLED = true
        task.spawn(function()
            if not game:IsLoaded() then
                game.Loaded:Wait()
            end
            getgenv().K7_STEAL_MODE = "Instant"
            pcall(function()
                if setthreadidentity then
                    setthreadidentity(8)
                end
            end)
            local P = game:GetService("Players")
            local C = P.LocalPlayer
            local P = {
                SelectedPetData = nil,
                AllAnimalsCache = nil,
                DisableStealSpeed = nil,
                ListNeedsRedraw = true,
                StealSpeedToggleFunc = nil,
                _ssUpdateBtn = nil,
                BalloonedPlayers = {},
                MobileScaleObjects = {},
                RefreshMobileScale = nil,
                MobileActionButtons = {},
                RefreshMobileActionButtons = nil,
            }
            -- Rose-style Base Camp steering: do not force a prompt directly.
            -- Select the nearest real stealable record anywhere in the camped plot,
            -- then feed that record to the existing Trx/K7 steal pipeline.
            task.spawn(function()
                while controllerAlive and _G.ROSE_K7_ENABLED == true do
                    local camp = _G.TrxBaseCamp
                    if camp and camp.active == true and camp.arrived == true and camp.plot then
                        local plotName = tostring(camp.plot.Name or camp.plotName or "")
                        local pets = {}
                        if type(_G.scanAllPets) == "function" then
                            local scanOk, scanResult = pcall(_G.scanAllPets, true)
                            if scanOk and type(scanResult) == "table" then pets = scanResult end
                        elseif type(_G.TrxStealPetList) == "table" then
                            pets = _G.TrxStealPetList
                        end

                        local hrp = C.Character and C.Character:FindFirstChild("HumanoidRootPart")
                        local myPos = hrp and hrp.Position
                        local chosen, chosenDistance, firstAny = nil, math.huge, nil
                        for _, pet in ipairs(pets) do
                            if type(pet) == "table"
                                and tostring(pet.plot) == plotName
                                and pet.name and pet.position and pet.conveyor ~= true
                                and pet.isWalking ~= true
                                and tostring(pet.owner or "") ~= tostring(C.Name) then
                                firstAny = firstAny or pet
                                local pos = pet.position
                                if typeof(pos) == "Vector3" and myPos then
                                    local distance = (pos - myPos).Magnitude
                                    if distance < chosenDistance then
                                        chosen, chosenDistance = pet, distance
                                    end
                                end
                            end
                        end
                        chosen = chosen or firstAny

                        if chosen then
                            local chosenSlot = tostring(chosen.slot or "")
                            if chosenSlot ~= "" then
                                camp.slot = chosenSlot
                                local uid = tostring(chosen.uid or chosen.id or (plotName .. "_" .. chosenSlot))
                                chosen.uid = uid
                                if type(_G.TrxApplyStealTarget) == "function" then
                                    pcall(_G.TrxApplyStealTarget, chosen)
                                end
                                -- This is the Trx equivalent of Rose SharedState.SetManualTarget.
                                _G.TrxManualStealUID = uid
                                P.SelectedPetData = chosen
                                _G.TrxSelectedPetData = chosen
                                _G.TrxStealTarget = chosen
                                _G.__trxChosenPet = chosen
                                _G.ROSE_K7_CAMP_SYNC = {
                                    plot = plotName, slot = chosenSlot,
                                    podiumFound = true, petDetected = true,
                                    petName = tostring(chosen.name), petUID = uid,
                                    syncedAt = os.clock(),
                                }
                            end
                        else
                            _G.ROSE_K7_CAMP_SYNC = {
                                plot = plotName, slot = tostring(camp.slot or ""),
                                podiumFound = true, petDetected = false,
                                syncedAt = os.clock(),
                            }
                        end
                    end
                    task.wait(0.25)
                end
            end)
            do
                local C = { AUTO_STEAL = false, RADIUS = 12 }
                local r =
                    {
