                    local S = cG[CG.uid]
                    if not S or not S.Parent then
                        S = b(CG.animalData)
                    end
                    if S then
                        oG(S, CG.uid)
                    end
                end)
                task.spawn(function()
                    while task.wait(0.01) do
                        sG(nG, TG())
                    end
                end)
                task.spawn(function()
                    task.wait(0.01)
                    P.ListNeedsRedraw = true
                    sG(nG, TG())
                end)
                task.spawn(function()
                    while true do
                        P.AllAnimalsCache = yG
                        task.wait(0.01)
                    end
                end)
            end)
            k7Started = true
            k7Starting = false
        end)
    end

    _G.ROSE_K7_SHUTDOWN = function()
        controllerAlive = false
        _G.ROSE_K7_ENABLED = false
        if type(_G.ROSE_K7_RESTORE_NORMAL_BAR) == "function" then
            pcall(_G.ROSE_K7_RESTORE_NORMAL_BAR)
        end
        _G.ROSE_K7_OWNS_STEAL = true
        if capturedSetNearest then pcall(capturedSetNearest, false) end
        if capturedSetInstant then pcall(capturedSetInstant, false) end
        _G.ROSE_K7_OWNS_STEAL = false
    end

    task.spawn(function()
        local applied = nil
        local wasReady = false
        while controllerAlive do
            local wanted = roseK7Wanted()
            if wanted and not k7Started then startRoseK7() end
            local ready = k7Started
                and type(_G.K7SetStealNearest) == "function"
                and type(_G.K7SetInstantSteal) == "function"
            if ready and not capturedSetNearest then
                capturedSetNearest = _G.K7SetStealNearest
                capturedSetInstant = _G.K7SetInstantSteal
            end

            _G.ROSE_K7_ENABLED = wanted
            if _G.ROSE_K7_HUD_GUI and _G.ROSE_K7_HUD_GUI.Parent then _G.ROSE_K7_HUD_GUI.Enabled = false end

            if ready and (applied ~= wanted or not wasReady) then
                _G.ROSE_K7_OWNS_STEAL = true
                if wanted then
                    pcall(capturedSetInstant, true)
                    pcall(capturedSetNearest, true)
                else
                    pcall(capturedSetNearest, false)
                    pcall(capturedSetInstant, false)
                    _G.ROSE_K7_OWNS_STEAL = false
                end
                applied = wanted
            elseif not ready then
                _G.ROSE_K7_OWNS_STEAL = wanted and (k7Starting or k7Started)
            elseif wanted then
                _G.ROSE_K7_OWNS_STEAL = true
            else
                _G.ROSE_K7_OWNS_STEAL = false
            end

            wasReady = ready
            task.wait(0.01)
        end
    end)
end


-- Keep equipped tools from changing the player's camera FOV.
-- The baseline is refreshed while no Tool is equipped, so normal FOV changes
-- made by the player are still respected. When a Tool changes FOV, restore the
-- last non-tool FOV immediately.
;(function()
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local player = Players.LocalPlayer
    if not player then return end

    local camera = workspace.CurrentCamera
    local desiredFov = camera and camera.FieldOfView or 70
    local lastCamera = camera

    local function hasEquippedTool()
        local character = player.Character
        if not character then return false end
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("Tool") then
                return true
            end
        end
        return false
    end

    local function onCameraChanged()
        local current = workspace.CurrentCamera
        if current and current ~= lastCamera then
            lastCamera = current
            -- Preserve the current FOV if the camera is recreated.
            if _G.TrxFovOn == true then
                desiredFov = math.clamp(tonumber(_G.TrxFov) or desiredFov, 70, 120)
                current.FieldOfView = desiredFov
            else
                desiredFov = current.FieldOfView
            end
        end
    end

    workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(onCameraChanged)
    RunService.Heartbeat:Connect(function()
        local current = workspace.CurrentCamera
        if not current then return end
        onCameraChanged()

        if _G.TrxFovOn == true then
            desiredFov = math.clamp(tonumber(_G.TrxFov) or desiredFov, 70, 120)
            if math.abs(current.FieldOfView - desiredFov) > 0.05 then
                current.FieldOfView = desiredFov
            end
        elseif hasEquippedTool() then
            if math.abs(current.FieldOfView - desiredFov) > 0.05 then
                current.FieldOfView = desiredFov
            end
        else
            -- No item is held: allow the game/player to set their preferred FOV.
            desiredFov = current.FieldOfView
        end
    end)
end)()